window.POEM_DB=window.POEM_DB||{};POEM_DB["song_004"]={"n":"赵蕃","dyn":"宋","poems":[{"t":"别朱子大苏召叟昆仲","f":"七言律诗","c":["薄宦尘埃易满襟，问盟犹喜盍朋簪。","只今风月一杯酒，明日云山千里心。","杨柳阴疏秋馆净，芙蓉香冷暮江深。","潮回一信西兴渡，频寄相思别后吟。"]},{"t":"丁卯除夕寓泸南独坐舟中有感去岁此夕","f":"七言绝句","c":["米仓山寨雪连云，不见椒盘见贼尘。","今日江城闻爆竹，莫嫌杯酒不沾唇。"]},{"t":"七月十有五夜一再梦故舒州使君侍御公宛如平生且于其案间得若纸若缯者一沓皆公所书或印者翻之有如帜者三有曰苛政曰赃吏忘其一焉问傍立者以何所用云始朝议欲遣公为某使故建此云觉而赋诗四绝 其四","f":"七言绝句","c":["梦回始觉死生分，愁咏江东日暮云。","安得分明再如昨，并须示我玉楼文。"]},{"t":"七月十有五夜一再梦故舒州使君侍御公宛如平生且于其案间得若纸若缯者一沓皆公所书或印者翻之有如帜者三有曰苛政曰赃吏忘其一焉问傍立者以何所用云始朝议欲遣公为某使故建此云觉而赋诗四绝 其三","f":"七言绝句","c":["弟过江东得附辞，奠犹乖往恸奚为。","情真未觉幽明负，贫病牢人甚絷维。"]},{"t":"七月十有五夜一再梦故舒州使君侍御公宛如平生且于其案间得若纸若缯者一沓皆公所书或印者翻之有如帜者三有曰苛政曰赃吏忘其一焉问傍立者以何所用云始朝议欲遣公为某使故建此云觉而赋诗四绝 其二","f":"七言绝句","c":["一夕安能再与俱，话言宁觉死生殊。","帜书更识埋轮志，生有不忘如是夫。"]},{"t":"七月十有五夜一再梦故舒州使君侍御公宛如平生且于其案间得若纸若缯者一沓皆公所书或印者翻之有如帜者三有曰苛政曰赃吏忘其一焉问傍立者以何所用云始朝议欲遣公为某使故建此云觉而赋诗四绝 其一","f":"七言绝句","c":["谁云死别已吞声，此恨何年得遽平。","林响风声雨萧瑟，败人残梦欲残更。"]},{"t":"七月六夜闻雨寄怀钦止斯远而玉山使来亦得斯远六月十五日怀去年夜雨之绝句复次韵以报","f":"七言绝句","c":["夜闻檐雨忆年时，亦复思君近寄诗。","开卷忽来同此作，信知神合但形离。"]},{"t":"七盘岭","f":"五言绝句","c":["远近分浓淡，阴晴异蔽亏。","不知山路险，却幸马行迟。"]},{"t":"九日怀在伯","f":"七言绝句","c":["雨过中秋明月时，病孤九日菊花期。","绝怜佳处有如此，亦劝斯人共和之。"]},{"t":"九日题越州光孝观壁","f":"七言绝句","c":["小槛丛花未肯香，客中我亦忘重阳。","要酬风雨满城句，旱合四郊尘政黄。"]},{"t":"二十夜起对月怀斯远成父 其二","f":"七言绝句","c":["虫鸣切切故关听，重感跳丸去不停。","不足有馀空岁计，书来吾友愧丁宁。"]},{"t":"二十夜起对月怀斯远成父 其一","f":"七言绝句","c":["雨落馀雷风罢狂，二更江月照苍凉。","蓬窗白发醒无寐，感此虫鸣草岸旁。"]},{"t":"二十夜起对月怀斯远成父 其三","f":"七言绝句","c":["昨朝执热扇慵挥，今夕凉生寝益衣。","想见山房听风竹，怅余何日定成归。"]},{"t":"二月初八日","f":"七言绝句","c":["只道贫无置锥地，根株戢戢自何生。","春风向暖浑宜裌，抛掷残绵傍砌楹。"]},{"t":"人日寄成父","f":"七言绝句","c":["人日今年合有诗，还犹成忆近成悲。","试令一问津头柳，早似山中寒食时。"]},{"t":"入严州界二首 其二","f":"七言绝句","c":["有山如此可忘看，政恐轻舟下急滩。","卯酒一杯扶病起，秋风千里怯衣单。"]},{"t":"入严州界二首 其一","f":"七言绝句","c":["朝来爽气致西山，孰愈严州百里间。","佣贩悬知尽冰玉，不惟二士眇难攀。"]},{"t":"八月八日发潭州后得绝句四十首 其十七","f":"七言绝句","c":["露冷初疑是晓霜，风高已觉爱朝阳。","莫云节变能如此，直念吾衰不复强。"]},{"t":"八月八日发潭州后得绝句四十首 其一","f":"七言绝句","c":["湘神知我爱湘中，故遣舟迟匪厄穷。","可笑儿曹不解事，故云常值打头风。"]},{"t":"八月八日发潭州后得绝句四十首 其十五","f":"七言绝句","c":["晓山能浅复能深，浅似朝晴深似阴。","山色岂知朝暮改，行人自费短长吟。"]},{"t":"八月八日发潭州后得绝句四十首 其三十四","f":"七言绝句","c":["煮泉树石閟幽深，来景栏干敞眺临。","可是溪山须一面，怀人政尔动哀吟。"]},{"t":"八月八日发潭州后得绝句四十首 其三","f":"七言绝句","c":["平岸朝阳已映光，高林宿霭尚深藏。","客中亟起繇何事，要趁侵晨数刻凉。"]},{"t":"八月八日发潭州后得绝句四十首 其十三","f":"七言绝句","c":["卢溪望望接宣风，景富犹能慰客穷。","已爱熙熙村舍好，更欣漠漠稻田丰。"]},{"t":"八月八日发潭州后得绝句四十首 其三十二","f":"七言绝句","c":["老去真成病不禁，炎蒸三日疟如侵。","江山旧识思新面，佳处真成略枕衾。"]},{"t":"八月八日发潭州后得绝句四十首 其十八","f":"七言绝句","c":["城上青山远近横，城边草树亦相萦。","城中台殿还相倚，画手其谁为写成。"]},{"t":"八月八日发潭州后得绝句四十首 其二十八","f":"七言绝句","c":["昌江直下水能平，却爱泷流激激声。","频岁水灾何自拯，政由疏凿欠流行。"]},{"t":"八月八日发潭州后得绝句四十首 其十四","f":"七言绝句","c":["晚山能紫复能青，远岭犹分近已冥。","好语忽然生眼底，遽将摹写已无形。"]},{"t":"八月八日发潭州后得绝句四十首 其三十","f":"七言绝句","c":["三径虽荒菊尚存，重阳想见露花繁。","那知欲去去不及，病卧他州空断魂。"]},{"t":"八月八日发潭州后得绝句四十首 其九","f":"七言绝句","c":["借居虽陋自如常，舟小安能具斛汤。","却羡沈牛浮鼻去，绿桑阴下趁苍凉。"]},{"t":"八月八日发潭州后得绝句四十首 其二十六","f":"七言绝句","c":["秀植如云不可穷，长杉钜竹略相同。","嗟余讵可如材者，政似飘飘秋后枫。"]},{"t":"八月八日发潭州后得绝句四十首 其三十六","f":"七言绝句","c":["落日苍苍烟树林，渚鸥沙鸟更浮沉。","过湖未远犹空阔，不见遥山出寸岑。"]},{"t":"八月八日发潭州后得绝句四十首 其三十一","f":"七言绝句","c":["去岁重阳事已讹，今年亦复病蹉跎。","明年想见山中集，弟妹团栾黄菊歌。"]},{"t":"八月八日发潭州后得绝句四十首 其二十","f":"七言绝句","c":["仰山林壑旧曾游，拟欲重寻不自由。","倚赖舣舟相对处，为予排闼向城头。"]},{"t":"八月八日发潭州后得绝句四十首 其三十九","f":"七言绝句","c":["午蔼纷纷无奈浓，晚来微敛见山容。","鹅湖旧日经行地，清吹思乘十里松。"]},{"t":"八月八日发潭州后得绝句四十首 其五","f":"七言绝句","c":["罾塘断港劣容舟，鱍鱍盈篮叫不休。","我亦买之将作腊，要和蔬茹绐饥喉。"]},{"t":"八月八日发潭州后得绝句四十首 其十一","f":"七言绝句","c":["午风吹坼稻花香，晨雨翻掀稻叶凉。","道上尘埃犹净尽，田间欢乐讵能量。"]},{"t":"八月八日发潭州后得绝句四十首 其三十七","f":"七言绝句","c":["日之夕矣下羊牛，想见吾庐树掩幽。","儿自閒行牛自去，溪头熟路不须求。"]},{"t":"八月八日发潭州后得绝句四十首 其二十二","f":"七言绝句","c":["仰山山峙季溪流，知我东归俾暂留。","尽日如推复如荡，为之成喜不成忧。"]},{"t":"八月八日发潭州后得绝句四十首 其十六","f":"七言绝句","c":["山驿虽荒亦可安，要眠杉月夜深寒。","昨宵虚落才闻鼓，明夕江皋想枕湍。"]},{"t":"八月八日发潭州后得绝句四十首 其三十五","f":"七言绝句","c":["暮色苍然遂不开，我舟亦欲傍崖隈。","不唯帆过谁家宿，水鸟林栖亦并来。"]},{"t":"八月八日发潭州后得绝句四十首 其二十三","f":"七言绝句","c":["两岸多为激水轮，创由人力用如神。","山田枯旱湖田涝，惟此丰凶岁岁均。"]},{"t":"八月八日发潭州后得绝句四十首 其七","f":"七言绝句","c":["南风纵急但温其，小雨虽微却透肌。","永日蓬窗难坐卧，祇随舷侧就阴移。"]},{"t":"八月八日发潭州后得绝句四十首 其四","f":"七言绝句","c":["鸥如玉洁鹭霜明，閒意相看了不惊。","乃不悟予非慕者，决然飞背晚烟轻。"]},{"t":"八月八日发潭州后得绝句四十首 其二十五","f":"七言绝句","c":["鹭鸶虽说擅风标，永日滩头腹苦枵。","凫鹜杂居宁自异，鸡群鹤处更加骄。"]},{"t":"八月八日发潭州后得绝句四十首 其十二","f":"七言绝句","c":["一年风月属中秋，今昔相传无异流。","定自天公亦兴此，故教雨脚破云头。"]},{"t":"八月八日发潭州后得绝句四十首 其八","f":"七言绝句","c":["刻木如瓶粉渍之，挂林聊当酒家旗。","我当物色登临处，亦复因之为解颐。"]},{"t":"八月八日发潭州后得绝句四十首 其二","f":"七言绝句","c":["才把离觞已足悲，况哦别句慰相思。","月明未比夜来别，人影已知天外追。"]},{"t":"八月八日发潭州后得绝句四十首 其二十九","f":"七言绝句","c":["病思昏昏略未醒，木犀谁遣浸饶瓶。","兀然随我故山梦，竹故青青雨自零。"]},{"t":"八月八日发潭州后得绝句四十首 其六","f":"七言绝句","c":["投罾政尔不能逃，偶逭还遭别网要。","此意岂能知数罟，不论他日且今朝。"]},{"t":"八月八日发潭州后得绝句四十首 其二十七","f":"七言绝句","c":["遥看巨石屹相冲，不道中江有路通。","几度跨羸行荦确，又成全室寄蓬笼。"]},{"t":"八月八日发潭州后得绝句四十首 其十","f":"七言绝句","c":["扁舟往作槠州过，烟雾空濛祇市声。","今夕再来还小泊，却逢江月正空明。"]},{"t":"八月八日发潭州后得绝句四十首 其三十八","f":"七言绝句","c":["大琛酒价旧知名，樟树姑洲得并行。","晨起亟思谋一醉，远钟已作叫岩声。"]},{"t":"八月八日发潭州后得绝句四十首 其三十三","f":"七言绝句","c":["季月将穷更起风，秋声乱杂橹声中。","倦游归去浑忘事，淹速从渠不计穷。"]},{"t":"八月八日发潭州后得绝句四十首 其十九","f":"七言绝句","c":["溪上秋来境倍佳，附城犹尔况村赊。","却嗟政尔营行棹，不得于兹理钓车。"]},{"t":"八月八日发潭州后得绝句四十首 其二十一","f":"七言绝句","c":["晚日才能度两滩，诘朝应复又成乾。","从来但说溯流苦，到我顺流良亦难。"]},{"t":"十一日 其二","f":"七言绝句","c":["老去读书非少年，故怜觳觫尚加鞭。","看竹偶然閒半日，归来还愧腹便便。"]},{"t":"十八夜宿秀城外","f":"七言绝句","c":["月子弯弯四面歌，扁舟今夜泊嘉禾。","颇欲歌呼起相和，一声轧轧又前波。"]},{"t":"十五夜看月","f":"七言绝句","c":["碧天涌出烂银盘，万里颠风落树端。","懒复持杯向渠问，径思飞步蹑翔鸾。"]},{"t":"十月十五日","f":"七言绝句","c":["柳行摇落参差际，雁字虚无灭没中。","醉面红来因卯酒，征衣脆去为霜风。"]},{"t":"十月见菊二首 其二","f":"七言绝句","c":["花前曳杖极徜徉，为汝临风一慨慷。","直自东坡仙去后，无人十月作重阳。"]},{"t":"十月见菊二首 其一","f":"七言绝句","c":["黄花狼籍晚犹香，冷蝶频来著意忙。","不见东篱千载士，自应埋没老风霜。"]},{"t":"又次签判丈惜花绝句三首 其三","f":"七言绝句","c":["春事违人去若狂，便惊鶗鴂怨年芳。","儿童强作留连意，拾去残花学试妆。"]},{"t":"又次签判丈惜花绝句三首 其二","f":"七言绝句","c":["蚤作抽书对白间，瓦炉犹有宿香残。","诗来报我群花尽，亟起巡檐忘帽寒。"]},{"t":"又次签判丈惜花绝句三首 其一","f":"七言绝句","c":["江南花草易芳菲，今我还家已似迟。","最恨春风苦无思，卷藏红绮不容披。"]},{"t":"又次韵宋茂叔送行五绝兼谢修叔 其四","f":"七言绝句","c":["前年过语漫匆匆，今喜追随数日同。","诗里固知俱有味，酒边宁复重言功。"]},{"t":"又次韵宋茂叔送行五绝兼谢修叔 其二","f":"七言绝句","c":["平日长嗟取友难，年来颇得见班班。","顾怜蹇步终无及，天马逍遥十二闲。"]},{"t":"又次韵宋茂叔送行五绝兼谢修叔 其五","f":"七言绝句","c":["山到穷时一径开，数松几竹与萦回。","我归酿黍仍锄菜，准拟篮舆窈窕来。"]},{"t":"又次韵宋茂叔送行五绝兼谢修叔 其三","f":"七言绝句","c":["太息平原生事疏，老来亦欲事犁锄。","傥然识得箪瓢乐，祇见何妨有不如。"]},{"t":"又次韵宋茂叔送行五绝兼谢修叔 其一","f":"七言绝句","c":["送我归舟水一篙，更携佳语赆吾曹。","暮云真作江东去，不复沅湘诵楚骚。"]},{"t":"三月一日","f":"七言绝句","c":["粤山深历备辞劳，虽有故人谁赠袍。","归卧茅斋且休歇，竹风山雨两萧骚。"]},{"t":"三月六日 其二","f":"七言绝句","c":["自把残书洗睡昏，欲求甚解与谁论。","乍然好鸟闻深樾，忽尔荒鸡听远村。"]},{"t":"三月六日 其三","f":"七言绝句","c":["怪底朝来暖欲昏，故应晚雨剧翻盆。","空斋寂寞催成睡，风为捲书还闭门。"]},{"t":"三月六日 其一","f":"七言绝句","c":["桐花最晚开已落，春色全归草满园。","破衲欲捐还未可，炎凉翻覆在朝昏。"]},{"t":"上元口号呈莫令三首 其三","f":"七言绝句","c":["华灯能得几时新，明日当为刍狗陈。","我识令君敦厚意，不能奉己厉吾民。"]},{"t":"上元口号呈莫令三首 其二","f":"七言绝句","c":["一盏华灯直万钱，谁知下里取薪然。","绮纨照耀舆台体，民得褐衣犹破穿。"]},{"t":"上元口号呈莫令三首 其一","f":"七言绝句","c":["令君忧乐与民同，灯火随时祝岁丰。","我亦颇怀归去乐，田蚕处处逐儿童。"]},{"t":"上饶道中","f":"七言绝句","c":["踏土忧疑似踏船，土塍滑汰胜于舷。","川行可怖陆行苦，谁遣为之空自怜。"]},{"t":"与庆伯广声别后有怀 其一","f":"七言绝句","c":["清虚亭上晚凭栏，正我扁舟堕险艰。","举酒纵君能酬我，未闻流水有西还。"]},{"t":"与庆伯广声别后有怀 其二","f":"七言绝句","c":["万壑分争汹汹来，扁舟寸上亦难哉。","晚晴只有山堪看，望极还忧远思哀。"]},{"t":"与成父自信同舟到饶分路而别以诗送之三首 其三","f":"七言绝句","c":["向来三复渭阳诗，羡汝此行亲见之。","若问乃兄何样似，家徒四壁更书痴。"]},{"t":"与成父自信同舟到饶分路而别以诗送之三首 其二","f":"七言绝句","c":["我自飘零更汝忧，贱贫骨肉不相收。","马家堤上休停骑，愁有居民说故侯。"]},{"t":"与成父自信同舟到饶分路而别以诗送之三首 其一","f":"七言绝句","c":["川行历览不知劳，我有新诗听汝抄。","今日语离还索句，况堪风雨满江郊。"]},{"t":"与李衢州峄四首 其四","f":"七言绝句","c":["洪井登龙记昔年，祇今太末又行缠。","馀波所及盖多矣，一夜水高溪有船。"]},{"t":"与李衢州峄四首 其三","f":"七言绝句","c":["黄尘扑扑倦征途，忽雨能来快洗苏。","旱接夏秋才得此，一身宁敢叹沾濡。"]},{"t":"与李衢州峄四首 其二","f":"七言绝句","c":["跨驴冲晚背常山，急雨飞来瞬息间。","问讯元从禹迹洞，我家虽近却愁悭。"]},{"t":"与李衢州峄四首 其一","f":"七言绝句","c":["忽逢旗鼓去翩翩，道上行人喜欲颠。","为说吾州新得雨，使君惠政实关天。"]},{"t":"与欧阳伯威同饮遇卿江楼","f":"七言绝句","c":["不上江楼又两春，人间到处略知津。","劳君置酒仍呼客，快语端能洗劫尘。"]},{"t":"与硕父沈弟伯仲晚行河堤硕父欲作小亭于其上且云西南得山最多即其语作绝句","f":"七言绝句","c":["断水桥横独木过，西南尽处得山多。","自嗟不及儿童乐，横笛骑牛稳下坡。"]},{"t":"口占简去非","f":"七言绝句","c":["春风春雨急仍颠，闻道远劳从事贤。","软脚不应惟命酒，池塘生草要新篇。"]},{"t":"夕庵观吴寿宁画","f":"七言绝句","c":["樛木蟠崖错节深，拍天风浪捲江心。","有人来问夕庵境，万里孤云无处寻。"]},{"t":"大风二首 其二","f":"七言绝句","c":["颇爱峡江江上山，几回陶冶付毫端。","眼中谁为善图貌，貌与桐江相并看。"]},{"t":"大风二首 其一","f":"七言绝句","c":["杯水得风犹渺然，况兹章贡远连天。","一穷坐我靡他问，下水宁闻劳挽牵。"]},{"t":"山中四绝句 其二","f":"七言绝句","c":["去年徂暑桃源过，今岁秋高到武夷。","不遇名山一来访，箧中宁有此山诗。"]},{"t":"山中四绝句 其四","f":"七言绝句","c":["欲访武夷毛洞竹，路穷九曲更山深。","道人知我衰无力，乞与一枝酬素心。"]},{"t":"山中四绝句 其一","f":"七言绝句","c":["桃源政自人间世，山故苍苍水故流。","不是幔亭张席地，卒然风雨卷山头。"]},{"t":"山中四绝句 其三","f":"七言绝句","c":["武夷仙伯定能诗，解赏仙人张湛词。","更诵人间可哀曲，飘飘亦复动人思。"]},{"t":"山行见野樱桃花","f":"七言绝句","c":["徐行历历转深豅，人意何如鸟语同。","山路梅花浑扫迹，春风尽属野樱红。"]},{"t":"己亥十月送成父弟絜两户幼累归玉山五首 其五","f":"七言绝句","c":["十月江行多北风，打头不用怨天公。","清音堂下换船处，想见挂帆滩已空。"]},{"t":"己亥十月送成父弟絜两户幼累归玉山五首 其四","f":"七言绝句","c":["误身何必叹儒冠，粗粝须甘苜蓿盘。","瓜地可耕归独负，未应真坐缚微官。"]},{"t":"己亥十月送成父弟絜两户幼累归玉山五首 其三","f":"七言绝句","c":["造物知君时欲进，江山佳处遣频回。","霜风日夜摧摇落，面目端须见本来。"]},{"t":"己亥十月送成父弟絜两户幼累归玉山五首 其二","f":"七言绝句","c":["去岁归营丘嫂葬，今年那复以家行。","挽须无用祇嗔喝，念我只儿同短檠。"]},{"t":"己亥十月送成父弟絜两户幼累归玉山五首 其一","f":"七言绝句","c":["已办知津送去舟，重临快阁亦悠悠。","黄知橘柚江行好，此去况经龙雾洲。"]},{"t":"中秋寄上饶赴试亲友池阳当涂三沈弟","f":"七言绝句","c":["中秋佳月去年同，卧病还应记此翁。","不但婵娟千里共，客游俱在大江东。"]},{"t":"为龙泉令赵舜徒题","f":"五言绝句","c":["诚能得初心，何必返初服。","有以固中扃，不须防外逐。"]},{"t":"书双径铺","f":"七言绝句","c":["昔者曾看紫柞花，今焉梅谢柳生芽。","无穷甲子随车毂，有限光阴属鬓华。"]},{"t":"书合龙寺旧题后","f":"七言绝句","c":["题诗客子鬓如银，壁上题诗墨尚新。","犬已久忘曾宿客，半山风铎似迎人。"]},{"t":"书灵鹫壁","f":"七言绝句","c":["支颐独立到栖鸦，送了虚廊日却斜。","冷蝶不知时节晚，伶仃犹自抱寒花。"]},{"t":"书案上三种梅三首 其三","f":"七言绝句","c":["翠袖佳人倚竹诗，昔人比兴乃陈辞。","我今顾欲求真相，绿萼梅花并竹枝。"]},{"t":"书案上三种梅三首 其二","f":"七言绝句","c":["我贵当由知我希，蜡梅全不事芳菲。","自非牢落山中士，谁可与之同一归。"]},{"t":"书案上三种梅三首 其一","f":"七言绝句","c":["人人共说梅花好，试问梅花好奈何。","到底物名嫌太甚，市区酒肆尽东坡。"]},{"t":"书乾明庵壁","f":"七言绝句","c":["道人持钵向何村，黄叶投风静拥门。","自买束薪来烧浴，浴终早已四山昏。"]},{"t":"予方作书招成父入山成父亦移书招予出县报以两绝 其一","f":"七言绝句","c":["阿连折简能招我，危坐哦诗正忆渠。","不是下山防破戒，政缘抱病怯行舆。"]},{"t":"云锦","f":"五言绝句","c":["西湖万顷荷，护以堤千丈。","应诏待新辞，无为恋盆盎。"]},{"t":"五月十七日谒伏波庙四首 其四","f":"七言绝句","c":["几从江上望朱栏，今日扁舟径往还。","潢潦傥收应易耳，白汀翠竹最相关。"]},{"t":"五月十七日谒伏波庙四首 其三","f":"七言绝句","c":["邬江江上祀陶公，亦以吾孙靖节从。","我谓辰州升德庙，要当并写少游容。"]},{"t":"五月十七日谒伏波庙四首 其二","f":"七言绝句","c":["仰视飞鸢始欲愁，要之乐死胜怀忧。","功名慷慨吾无志，所愿平生马少游。"]},{"t":"五月十七日谒伏波庙四首 其一","f":"七言绝句","c":["万里才传却瘴方，药囊翻谓橐中装。","谗人不敢投豺虎，空见壶头石室荒。"]},{"t":"仁智堂","f":"五言绝句","c":["公乎仁且智，意托山与水。","唱道本龙门，遗尘仍栗里。"]},{"t":"仆有诗思成父辄知之而绝不肯道一语以二十八字戏赠","f":"七言绝句","c":["诗情郁郁见须眉，何意君能辄识之。","目击道存真有得，傍观袖手岂非痴。"]},{"t":"从元衡借庐山记偶成三首 其三","f":"七言绝句","c":["山南山北富深幽，羽服方袍占上头。","吾道才馀白鹿洞，寂寥几载有新修。"]},{"t":"从元衡借庐山记偶成三首 其二","f":"七言绝句","c":["要为冷语豁心胸，孰若相羊涧谷中。","试把遗编一开读，恍疑涧谷为鸣风。"]},{"t":"从元衡借庐山记偶成三首 其一","f":"七言绝句","c":["吾家昔住匡庐北，少小未能知看山。","南北东西今老矣，欲从图籍见班班。"]},{"t":"从王彦博觅洞庭柑三首 其三","f":"七言绝句","c":["闻道居家近橘坡，青黄遥想问疏篱。","可能乞我数包否，仍寄韦郎七字诗。"]},{"t":"从王彦博觅洞庭柑三首 其二","f":"七言绝句","c":["踰淮为枳信堪奴，珍植何分楚与吴。","不但居家有遗帖，酿成赋辱长公苏。"]},{"t":"从王彦博觅洞庭柑三首 其一","f":"七言绝句","c":["扁舟几泊洞庭霜，曾见连林橘柚黄。","祇道陋邦无此物，那知种树有诸王。"]},{"t":"从礼折花携具见过且赋二诗 其一","f":"七言绝句","c":["出门政觉病躯难，已分春风负牡丹。","送花载酒能俱至，愧尔交情殊未阑。"]},{"t":"从礼折花携具见过且赋二诗 其二","f":"七言绝句","c":["花好千金未当价，只宜屏隐绣芙蓉。","调笑颇似年少日，妄心今已退重重。"]},{"t":"从礼载酒要余及明叔游合普六首 其六","f":"七言绝句","c":["宦忙未抵作诗忙，九十春光自短长。","三径可归谁是伴，若人风节慕求羊。"]},{"t":"从礼载酒要余及明叔游合普六首 其五","f":"七言绝句","c":["一轩高竹似高人，鸟雀驯除不动尘。","首夏清和故应好，可须载酒祇寻春。"]},{"t":"从礼载酒要余及明叔游合普六首 其四","f":"七言绝句","c":["尘埃老矣未收身，每对山林强自亲。","诗纵满囊惭李贺，笔虽成冢愧藏真。"]},{"t":"从礼载酒要余及明叔游合普六首 其三","f":"七言绝句","c":["儿曹谩作看花忙，我辈看山兴更长。","败意幸赊凫雁集，少须落日下牛羊。"]},{"t":"从礼载酒要余及明叔游合普六首 其二","f":"七言绝句","c":["花开无计杜游人，未若栽松远世尘。","莫问何年栋梁用，也胜开落总由春。"]},{"t":"从礼载酒要余及明叔游合普六首 其一","f":"七言绝句","c":["此君佳处是长身，静绕吟行要日亲。","何事当前遽安障，未能忘俗遂忘真。"]},{"t":"从李崇道觅潘衡墨四首 其四","f":"七言绝句","c":["识字才能项籍欺，灶煤研瓦分甘之。","如何乞索忘唐突，拟赋江南鹤膝枝。"]},{"t":"从李崇道觅潘衡墨四首 其三","f":"七言绝句","c":["丈夫久弭江西节，闻道诸侯尚扫门。","箧有玄圭肯分似，从今默默面称冤。"]},{"t":"从李崇道觅潘衡墨四首 其二","f":"七言绝句","c":["眼寒不识黟川李，相好长迷大禹圭。","见说潘郎亲有女，独能传业向深闺。"]},{"t":"从李崇道觅潘衡墨四首 其一","f":"七言绝句","c":["人言潘谷久腾空，衡也崎岖隐墨中。","谷见坡诗衡用诀，了知真是一家风。"]},{"t":"从郑秀才觅菊二首 其二","f":"七言绝句","c":["漫从僧舍移甘菊，清蕊重阳摘未堪。","径欲过君篱下看，二儿端可为舆篮。"]},{"t":"从郑秀才觅菊二首 其一","f":"七言绝句","c":["好事风流有郑庄，买园栽菊待重阳。","傥能怜我耽佳句，为遣秋根到草堂。"]},{"t":"从俞少孟觅橘","f":"七言绝句","c":["忆昔为农近石田，年年为橘走霜天。","大踰三寸曾何直，裁得开元斗米钱。"]},{"t":"从赵崇道求蜀纸五首 其五","f":"七言绝句","c":["病起犹馀觅句勤，要题柿叶厌缤纷。","陟釐尽付五十万，今代谁为王右军。"]},{"t":"从赵崇道求蜀纸五首 其四","f":"七言绝句","c":["麻纸敷腴色胜银，冷金凝滑倍精神。","自馀族类犹多有，王谢名家总绝人。"]},{"t":"从赵崇道求蜀纸五首 其三","f":"七言绝句","c":["人伪区区信日穷，楮藤苔竹互争雄。","自从蜀纸东南见，凡马真成一洗空。"]},{"t":"从赵崇道求蜀纸五首 其二","f":"七言绝句","c":["旧闻黄雀走头颅，近岁清江亦与俱。","舒卷定怜无尺枉，敷陈尽可见臣愚。"]},{"t":"从赵崇道求蜀纸五首 其一","f":"七言绝句","c":["紫岩黟歙略相同，小字缄题寄子公。","纵使分沾能到我，质粗肉缓不堪攻。"]},{"t":"从赵常德觅鼎帖","f":"七言绝句","c":["宇法微芒久失真，时闻鼎帖尚精神。","小诗试向铃斋乞，近舍远求公勿嗔。"]},{"t":"从徐处士乞梅二首 其二","f":"七言绝句","c":["我居旧植千竿竹，剩欲栽梅苦未成。","要写横斜须老手，是君头白眼犹明。"]},{"t":"从徐处士乞梅二首 其一","f":"七言绝句","c":["江南处士杨无咎，畴昔最工梅写真。","闻道徐郎得其妙，何妨乞我一枝春。"]},{"t":"从萧君来茶二首 其二","f":"七言绝句","c":["旧传汉殿三眠柳，烧烛仍闻照海棠。","草木困春人可奈，政烦茗椀为禁当。"]},{"t":"从萧君来茶二首 其一","f":"七言绝句","c":["园官阙菜犹形讽，年例求茶可欠诗。","为报萧郎勿多怪，已令汲涧拾松枝。"]},{"t":"从萧秀才求茶二首 其二","f":"七言绝句","c":["磊落真同席上珍，忆蒙况我意殊真。","今年尚许分张否，试遣诗筒告及春。"]},{"t":"从萧秀才求茶二首 其一","f":"七言绝句","c":["丁蔡纷纷竞宠加，底如好事玉溪家。","至今有子能传业，不待茶精句亦佳。"]},{"t":"从潘丈求字二首 其二","f":"七言绝句","c":["摩挲石刻叹微茫，孰若汗青移硬黄。","几净窗明肯游戏，千金便当橐中装。"]},{"t":"从潘丈求字二首 其一","f":"七言绝句","c":["束发学书今白头，腕中无力合休休。","规模尚欲从公乞，翰墨于今第一流。"]},{"t":"以山药茶送沈宜之兄","f":"七言绝句","c":["山药本为林下享，筠篮那得致兵厨。","传担云月并持与，长夜读书应所须。"]},{"t":"以穷藁借全真","f":"七言绝句","c":["平生不识宋亨伯，老去手将穷藁编。","六一家风真好事，要渠行世欲抄传。"]},{"t":"以坡公君如大江日千里我如此水千山底为韵作小诗十四首重送在伯盖深有感于斯句云 其十一","f":"五言绝句","c":["频登采芹亭，所乐非山水。","君今去我东，愁绝重来倚。"]},{"t":"以坡公君如大江日千里我如此水千山底为韵作小诗十四首重送在伯盖深有感于斯句云 其一","f":"五言绝句","c":["落此鼪鼯野，宜从麋鹿群。","何知交友内，而乃得夫君。"]},{"t":"以坡公君如大江日千里我如此水千山底为韵作小诗十四首重送在伯盖深有感于斯句云 其四","f":"五言绝句","c":["楚国千年薮，岷山万里江。","胡为入吟笔，政以落蓬窗。"]},{"t":"以坡公君如大江日千里我如此水千山底为韵作小诗十四首重送在伯盖深有感于斯句云 其六","f":"五言绝句","c":["今日东阳郡，城南尺五天。","胡为五溪行，道里踰几千。"]},{"t":"以坡公君如大江日千里我如此水千山底为韵作小诗十四首重送在伯盖深有感于斯句云 其二","f":"五言绝句","c":["何氏之从学，源流远有馀。","穷经类元凯，能赋似相如。"]},{"t":"以茶寄杨溥之二首 其二","f":"七言绝句","c":["忆过君家置酒杯，病予方止只空陪。","而今梦想论文地，柳合沙堤鸥去来。"]},{"t":"以茶寄杨溥之二首 其一","f":"七言绝句","c":["要题尺素问何如，病过春风体益癯。","采得山茶漫持寄，草玄馀暇想时须。"]},{"t":"以笋送诸公二首 其二","f":"七言绝句","c":["昔闻市上三时卖，今已春深见未尝。","莫道寒历只寒相，及时也复事分张。"]},{"t":"以笋送诸公二首 其一","f":"七言绝句","c":["兰在当门未免锄，竹生那可碍阶除。","莫言无罪充庖宰，自汝为生托地疏。"]},{"t":"以酒钱送明叔二绝代简 其一","f":"七言绝句","c":["酒钱时乞故怜苏，三百青铜寄与沽。","砚水长枯肺仍渴，可兹涓滴所能濡。"]},{"t":"以酒钱送明叔二绝代简 其二","f":"七言绝句","c":["我乃病多长止酒，有时渴梦落江湖。","江天阔处识君阁，要破熟茶共嗫嚅。"]},{"t":"以湖州酥秀州木犀面油太和石本观音像送莫万安三首 其三","f":"七言绝句","c":["涪翁昔作白下宰，遗墨到今多雁书。","尽说补陀存相好，更传雷火护持馀。"]},{"t":"以湖州酥秀州木犀面油太和石本观音像送莫万安三首 其二","f":"七言绝句","c":["天教桂蕊擅秋分，只道非秋无复存。","底事兰开梅落际，忽于膏饰见追魂。"]},{"t":"以湖州酥秀州木犀面油太和石本观音像送莫万安三首 其一","f":"七言绝句","c":["蚁浮犹腊要酥同，长恨中州信不通。","忽得吴中所持寄，急令分减报乡风。"]},{"t":"以短轴从杨谨仲求字仅书其半而见还绝句戏谢","f":"七言绝句","c":["先生字有千金直，乞取宁非亦坐贪。","更欲从公请终卷，又虞卖菜或蒙惭。"]},{"t":"以蜡梅分供堂头希卢首座冲南首座惠绝句次韵并简堂头二首 其二","f":"七言绝句","c":["才尽年来怕及春，上人那说是诗人。","拨残芋火宁馀事，故欲撩公懒是真。"]},{"t":"以蜡梅分供堂头希卢首座冲南首座惠绝句次韵并简堂头二首 其一","f":"七言绝句","c":["蜜黄初出一枝春，分似堂中得定人。","各各闻香获三昧，信知文字本非真。"]},{"t":"元日寄成父四首 其四","f":"七言绝句","c":["客里那知岁月迁，梅花报我又今年。","兰溪桥下扁舟泊，把笔题诗意惘然。"]},{"t":"元日寄成父四首 其三","f":"七言绝句","c":["冒晨造谒愧悠悠，残客不来门更幽。","邂逅行人觅花看，春风已属杏梢头。"]},{"t":"元日寄成父四首 其二","f":"七言绝句","c":["家家节物竞今朝，风俗未分南北遥。","莫向除薪觅如愿，且凭爆竹走山魈。"]},{"t":"元日寄成父四首 其一","f":"七言绝句","c":["旧时元日羡吾庐，称寿献觞欢有馀。","今日儿曹还效我，凄然事忆十年初。"]},{"t":"六月二十二日病中得雨顿觉沈疴去体欣然起饮遂成一绝","f":"七言绝句","c":["涉秋得雨便生凉，起我萧然病在床。","径自典衣谋一醉，要令清梦略还乡。"]},{"t":"午过无锡明日五更到平江门外","f":"七言绝句","c":["百里风帆日未中，惠山紫翠忽重重。","姑苏城外枫林寺，夜半已过闻晓钟。"]},{"t":"反禽言二首 其二","f":"七言绝句","c":["禦雨无过以瓦为，古人朴直致君辞。","我今闭户疏还往，滑滑从深三尺泥。"]},{"t":"反禽言二首 其一","f":"七言绝句","c":["雨后翛然欲变秋，意捐絺绤揽衣裘。","林间脱裤催人急，时有炎凉底过忧。"]},{"t":"尹丈少稷旧作借竹轩诗数首如雨重时惊入屋梢风微亦得听萧骚之句尤为警拔雨中看竹因用其语作两绝句 其二","f":"七言绝句","c":["离立何妨出屋高，风微亦得听萧骚。","南山昨夜新雷起，行有横鞭破土膏。"]},{"t":"尹丈少稷旧作借竹轩诗数首如雨重时惊入屋梢风微亦得听萧骚之句尤为警拔雨中看竹因用其语作两绝句 其一","f":"七言绝句","c":["山居面面皆脩竹，雨重时惊入屋梢。","坐诵方斋旧诗句，人间那有续弦胶。"]},{"t":"廿二日题水南寺壁","f":"七言绝句","c":["落花飞蝶两翾翾，二月清明雨后天。","白酒一杯成坐睡，宿寒犹在未除绵。"]},{"t":"文殊院晨起","f":"七言绝句","c":["山禽百族自呼名，撩我僧窗睡不成。","纵汝多言吾自喜，了知今日十分晴。"]},{"t":"方池","f":"五言绝句","c":["藻荇参遮面，菰蒲耸立隅。","飞来双野鸭，几幅画成图。"]},{"t":"日者张一麟求诗谩与二绝句 其一","f":"七言绝句","c":["惶恐离头住过秋，秋风吹白几分头。","倚楼看镜嫌多事，况问阴阳家者流。"]},{"t":"日者张一麟求诗谩与二绝句 其二","f":"七言绝句","c":["袖里之书辱见捐，细看知是我行年。","家徒四壁将何赠，乞与两诗赊卦钱。"]},{"t":"月 其一","f":"七言绝句","c":["万顷苍波月一钩，鹭鸥栖稳雁悠悠。","老夫于此兴不浅，无奈凛乎何可留。"]},{"t":"月 其二","f":"七言绝句","c":["水鸟飞鸣自往还，苍然暝色暗林峦。","离家又见磨镰月，九月谁怜絺绤寒。"]},{"t":"月岩 其一","f":"七言绝句","c":["论画以形诗必此，东坡老子笑人痴。","月岩本是梯空石，底事轻论圆与亏。"]},{"t":"月岩 其二","f":"七言绝句","c":["举头见日犹为近，何况凌虚到月边。","更欲裴徊究真妄，无人与我共谈玄。"]},{"t":"木芙蓉","f":"七言绝句","c":["三两芙蓉并水丛，向人能白亦能红。","浩然不在芍药下，如何独占晚秋风。"]},{"t":"木犀四首 其四","f":"七言绝句","c":["我生天与山林相，不羡人间富贵花。","折得幽芳顿何许，纸窗书屋伴煎茶。"]},{"t":"木犀四首 其三","f":"七言绝句","c":["浪说西京斗大花，赤栏青幄五侯家。","那知林下馀幽物，雨打风吹不怨嗟。"]},{"t":"木犀四首 其二","f":"七言绝句","c":["人言山水钟人物，我道英灵属此花。","枯死犹堪作香供，不同桃李混泥沙。"]},{"t":"木犀四首 其一","f":"七言绝句","c":["细看秋露黄金蕊，不减春风白玉枝。","人道江南富山水，江南山水富于斯。"]},{"t":"王主簿以湘潭检旱诗卷为示用其广惠寺蠲放韵谢之 其二","f":"七言绝句","c":["陇亩循行不惮难，是知汉诏本从宽。","讲求利病非无补，老矣犹能策治安。"]},{"t":"王主簿以湘潭检旱诗卷为示用其广惠寺蠲放韵谢之 其一","f":"七言绝句","c":["旱年蠲赋本深仁，州县宁闻以实论。","细读赋诗知用意，是为忧国爱元元。"]},{"t":"王兆明惠梅花诗二十首口占谢之","f":"七言绝句","c":["腊前再雪已相侵，年后更连人日阴。","欲问梅花苦无地，把君诗卷得参寻。"]},{"t":"王昭君","f":"七言绝句","c":["绝代方能入汉宫，画图何必更求工。","纵令得幸因图画，已落君王疑信中。"]},{"t":"见马奉先宁祖诗于伯言处题其后","f":"七言绝句","c":["闻说湘中马奉先，数诗初喜见流传。","何处宜州勿多薄，金华曾识老诗仙。"]},{"t":"见卖梅花者作卖花行 其一","f":"七言绝句","c":["来时才卖木犀花，卖到梅花未返家。","作客悠悠有何好，定应诗兴在天涯。"]},{"t":"见卖梅花者作卖花行 其二","f":"七言绝句","c":["连日阴风作许寒，晚来妍暖似春阑。","十分待放梅花否，留我数枝归到看。"]},{"t":"见梁检法书怀八绝句于广文尉曹处次韵 其五","f":"七言绝句","c":["山行难得上天梯，舟泛还忧水路迷。","忆我故栖何许在，玉为山下是冰溪。"]},{"t":"见梁检法书怀八绝句于广文尉曹处次韵 其八","f":"七言绝句","c":["傥欲昌身诗莫昌，折腰也莫叹凄凉。","上书假传非无例，慷慨相期入皂囊。"]},{"t":"见梁检法书怀八绝句于广文尉曹处次韵 其四","f":"七言绝句","c":["汉诏元从漏网宽，可将数罟作惊澜。","幕中有此贤从事，我亦他时逭免冠。"]},{"t":"见梁检法书怀八绝句于广文尉曹处次韵 其一","f":"七言绝句","c":["文力纵横昔未窥，每闻二子说襟期。","来朝借得新诗卷，起我閒窗病酒时。"]},{"t":"见梁检法书怀八绝句于广文尉曹处次韵 其三","f":"七言绝句","c":["修眉画就莫求工，自昔常闻妒入宫。","不为无人芳自吐，也胜能白又能红。"]},{"t":"见梁检法书怀八绝句于广文尉曹处次韵 其六","f":"七言绝句","c":["辞好曾闻喻色丝，那知妙处本天姿。","若穷句法源流远，曾见梅山唱和诗。"]},{"t":"见梁检法书怀八绝句于广文尉曹处次韵 其七","f":"七言绝句","c":["中圣流风久未寒，渺然何但酒肠宽。","渠诗下笔如山峡，我思攀危上七盘。"]},{"t":"见梁检法书怀八绝句于广文尉曹处次韵 其二","f":"七言绝句","c":["醉眠攲侧似乘舠，飒飒溪风吹鬓毛。","颇念乘流觅归路，兀然惊起遇滩高。"]},{"t":"见紫荆有怀成父","f":"七言绝句","c":["一树幽花见紫荆，杜陵诗句属吾情。","江东消息关河阔，况我平生寡弟兄。"]},{"t":"邓林寺用孙温叟韵","f":"七言绝句","c":["上天有路不为难，丈七坳头莫据鞍。","小憩还寻去时寺，戏拈枯笔臂犹酸。"]},{"t":"长田铺二首 其二","f":"五言绝句","c":["晚日东西路，秋风长短亭。","悲歌浑欲绝，衰泪不胜零。"]},{"t":"长田铺二首 其一","f":"五言绝句","c":["野驿人稀到，空庭草自生。","霜清殊未觉，雨细更含晴。"]},{"t":"风","f":"七言绝句","c":["逆风忽作大王雄，客岸淹留半日中。","亭午却回张席去，向来骇浪亦潜空。"]},{"t":"代书示逸二首 其二","f":"七言绝句","c":["别日才留两月粮，况经裘葛变炎凉。","未知别后端何似，不见寄来书一行。"]},{"t":"代书示逸二首 其一","f":"七言绝句","c":["风号窗外独株松，想汝看书趁晓钟。","是我起行茅店月，禦寒还觉欠茏茸。"]},{"t":"代书送橘沈临江","f":"七言绝句","c":["谁贻新橘两筠笼，尚带霜林错落红。","转送清江供寿酒，草书因病废匆匆。"]},{"t":"代书寄成父","f":"七言绝句","c":["已作南山半月留，欲行更复待新秋。","不知几日潮当发，可及沙头一醉不。"]},{"t":"代书寄张次律二首 其二","f":"七言绝句","c":["闻道浮家历上塘，寒山钟接洞庭霜。","是中佳句知多少，傥有书来幸不忘。"]},{"t":"代书寄张次律二首 其一","f":"七言绝句","c":["道入袁州首问君，却言守舍有宗文。","不知木落风高际，何处登临对夕曛。"]},{"t":"代书寄周愚卿二首 其二","f":"七言绝句","c":["穷冈冈上欧阳子，荷屋屋中常不轻。","邂逅论诗傥相及，为言即日鬓霜生。"]},{"t":"代书寄周愚卿二首 其一","f":"七言绝句","c":["友于阁上友于人，忽忽分携又两春。","剩欲作书书不得，旧知吾懒是吾真。"]},{"t":"代简琛卿","f":"七言绝句","c":["是处梅花与雪融，竹间开晚正玲珑。","陈君为我言如此，折赠当期慰眼中。"]},{"t":"兰溪溪岸梅花","f":"七言绝句","c":["不用温家玉镜台，下临溪水静无埃。","若非姑射冰肌至，即是罗浮缟袂来。"]},{"t":"北风","f":"五言绝句","c":["北风故应阴，南风还当晴。","占风更占雨，巢穴寄吾生。"]},{"t":"发大通","f":"七言绝句","c":["五更催发船无限，及此风收浪不生。","何事渔舟亦争进，始知为利总营营。"]},{"t":"发石佛","f":"七言绝句","c":["石佛如今果有灵，尽驱昏翳作空青。","松原白石今朝过，云洞月岩明日经。"]},{"t":"发豫章后二首 其二","f":"七言绝句","c":["诗成欲赋江山好，政尔多言恐害廉。","只恨十分朝日美，可能身独负茅檐。"]},{"t":"发豫章后二首 其一","f":"七言绝句","c":["枫林灭没橘林多，酒户渔家奈若何。","剩欲与渠论久住，一官老矣尚奔波。"]},{"t":"对月赠答二首 其二","f":"七言绝句","c":["焚香拜月君怀我，对月停杯我忆君。","莫羡月圆圆又缺，会看人合合无分。"]},{"t":"对月赠答二首 其一","f":"七言绝句","c":["闺中月是天涯月，照妾遥知亦照君。","月解令人千里共，人能似月两头分。"]},{"t":"对梅有作六首 其六","f":"七言绝句","c":["寥落江山无故人，见梅忆著故园春。","水南水北寻诗地，想见风流一幅巾。"]},{"t":"对梅有作六首 其五","f":"七言绝句","c":["日未落时香未归，晚风方觉雪霏霏。","月明纵可形模似，不比风流殆庶几。"]},{"t":"对梅有作六首 其四","f":"七言绝句","c":["酒恶思茶更炷香，不如梅蕊嚼冰霜。","文园病渴知如此，未遽骑鲸返帝乡。"]},{"t":"对梅有作六首 其三","f":"七言绝句","c":["老来诗兴苦无多，折得梅花奈若何。","便恐飘零不堪触，正须绕树数婆娑。"]},{"t":"对梅有作六首 其二","f":"七言绝句","c":["四十飞腾暮景斜，更云学易数年加。","勿谓衰催便欺我，尚能高兴属梅花。"]},{"t":"对梅有作六首 其一","f":"七言绝句","c":["剩欲将梅月下看，却愁风露不胜寒。","有时暂作披衣看，积雪凝霜不可干。"]},{"t":"归近","f":"七言绝句","c":["黄溪潭上晚风生，吹我孤舟直又横。","归近尚馀三十里，不妨待得月同行。"]},{"t":"正月九日微雪二首 其二","f":"七言绝句","c":["小雨因风冻作花，冰梢争竞出槎牙。","携筇偶作巡檐去，徙倚微吟低帽纱。"]},{"t":"正月九日微雪二首 其一","f":"七言绝句","c":["霰雪纤纤晚倍寒，梅花清瘦不禁看。","小园准拟寻诗去，少待侵苔屐齿乾。"]},{"t":"正月二十二日晚过袁父","f":"七言绝句","c":["篱落桃花小破红，野田细雨又微风。","莫嗤款段行难进，正要寻诗漠漠中。"]},{"t":"永丰尉治神祠前梅已成阴忽著花七出而无鄂色又正白众咸异之尉上蔡谢君子畅有诗蕃次韵","f":"七言绝句","c":["谢君为吏清如水，神吐祠前不鄂花。","我欲将诗道其事，却防流咏入京华。"]},{"t":"永和道中怀成父","f":"七言绝句","c":["风帆十幅空百滩，布衾高卧宁知寒。","连明风雨晓增剧，叹我山行逢路难。"]},{"t":"玉山久旱七月一日雨作望者云从常山来时赵吏部赴福州适入境已闻境上大雨取书邦人欢喜之词为口号二首呈之 其二","f":"七言绝句","c":["父老争迎旧使君，使君何以为吾民。","要须一举为霖手，快泻天瓢洗旱尘。"]},{"t":"玉山久旱七月一日雨作望者云从常山来时赵吏部赴福州适入境已闻境上大雨取书邦人欢喜之词为口号二首呈之 其一","f":"七言绝句","c":["一雨胡为限古城，定应留逐使君行。","前驱尚远毋庸遽，已见萧萧破久晴。"]},{"t":"玉聚","f":"七言绝句","c":["介然谁主复谁宾，风月婆娑却自亲。","留得清名传野史，未妨白眼向时人。"]},{"t":"生米矶之至德观余旧游也尝有题钓矶胡柏七言二绝句庚子夏五月八日再来道士复向余乞赋仙洲平远濯风涌月四题因各与一首 其三","f":"七言绝句","c":["往游故喜秋无暑，今至还欣夏有凉。","褦襶不能来热客，泠然听我梦还乡。"]},{"t":"生米矶之至德观余旧游也尝有题钓矶胡柏七言二绝句庚子夏五月八日再来道士复向余乞赋仙洲平远濯风涌月四题因各与一首 其二","f":"七言绝句","c":["旧闻但觉生米矶，新游更见黄连石。","石边矶上有轩窗，万里一时来咫尺。"]},{"t":"生米矶之至德观余旧游也尝有题钓矶胡柏七言二绝句庚子夏五月八日再来道士复向余乞赋仙洲平远濯风涌月四题因各与一首 其四","f":"七言绝句","c":["团团政尔来天下，皎皎何从堕水中。","剩欲学为牛渚咏，只愁笑杀绮裘翁。"]},{"t":"生米矶之至德观余旧游也尝有题钓矶胡柏七言二绝句庚子夏五月八日再来道士复向余乞赋仙洲平远濯风涌月四题因各与一首 其一","f":"七言绝句","c":["此地传为天宝门，政由渔叟话桃源。","阁中名字谁为立，知是君平几世孙。"]},{"t":"用一代不数人百年能几见为韵诗赋十章呈陈君举 其五","f":"五言绝句","c":["云物瞻闽峤，风声望海滨。","如何一年内，顿得见斯人。"]},{"t":"用一代不数人百年能几见为韵诗赋十章呈陈君举 其二","f":"五言绝句","c":["公乎不为文，为必行于代。","诵习孰其人，儿童兼老辈。"]},{"t":"用一代不数人百年能几见为韵诗赋十章呈陈君举 其七","f":"五言绝句","c":["山色仍前日，梅花又一年。","休为招屈些，好泛渡湘船。"]},{"t":"用一代不数人百年能几见为韵诗赋十章呈陈君举 其一","f":"五言绝句","c":["东南固多贤，莫与永嘉匹。","王郑已骑鲸，辈流公第一。"]},{"t":"用一代不数人百年能几见为韵诗赋十章呈陈君举 其八","f":"五言绝句","c":["少小耽文字，初非哲匠能。","空令为己学，老矣见何曾。"]},{"t":"用洪觉范诗为首作四绝 其二","f":"七言绝句","c":["钓舟无事白鸥閒，自是江湖境界宽。","我欲汎然随所往，竹君谁与报平安。"]},{"t":"用洪觉范诗为首作四绝 其三","f":"七言绝句","c":["个中著我添图画，能画今谁如辋川。","但写一蓑仍一笠，不须羽服记蹁跹。"]},{"t":"用洪觉范诗为首作四绝 其四","f":"七言绝句","c":["便似华亭落照湾，要人弹压愧诗孱。","馀霞散尽空无绮，新月初升势已弯。"]},{"t":"田家即事八首 其八","f":"五言绝句","c":["田夫荷锸去，乘水护田缺。","田妇贳酒归，相与慰勤力。"]},{"t":"田家即事八首 其七","f":"五言绝句","c":["下田已鸥没，上田更龟坼。","欲知雨未已，看取云泼墨。"]},{"t":"田家即事八首 其六","f":"五言绝句","c":["老屋愁风破，空林过雨乾。","飘零黄叶满，寂寞野香残。"]},{"t":"田家即事八首 其五","f":"五言绝句","c":["行役渠怜我，生涯我羡渠。","太平今有象，随寓即吾庐。"]},{"t":"田家即事八首 其四","f":"五言绝句","c":["波静童闲笛，舟横翁卖鱼。","村村皆乐业，处处尽安居。"]},{"t":"田家即事八首 其三","f":"五言绝句","c":["社鼓村村急，春流岸岸高。","双分待鱼鹭，红认隔溪桃。"]},{"t":"田家即事八首 其二","f":"五言绝句","c":["十载溪山梦，一川桃李花。","春深犹是客，几日定还家。"]},{"t":"田家即事八首 其一","f":"五言绝句","c":["水汎将晴雾，山行欲雨云。","鸥翻随渚见，鸡近隔林闻。"]},{"t":"白水寺","f":"七言绝句","c":["雾合深林晓到迟，树摇宿雨讶晴曦。","不知客里何迁次，一似山中初起时。"]},{"t":"白发三首 其三","f":"七言绝句","c":["少年志愿立修名，隐显悠悠略未成。","倚赖少陵诗不误，白间会有黑丝生。"]},{"t":"白发三首 其二","f":"七言绝句","c":["叶落归根莫漫悲，春风解发次年枝。","人如草木空多智，一老宁闻再少时。"]},{"t":"白发三首 其一","f":"七言绝句","c":["忆昨鬓毛殊未白，斑斑已复见于诗。","天公嫌汝底相耗，故遣齐生不待衰。"]},{"t":"白雾溪","f":"五言绝句","c":["雾雨犹疑合，槎头不可窥。","凶年走牲酒，平旦但茅茨。"]},{"t":"石门坞","f":"五言绝句","c":["溪已曲更曲，坞仍深更深。","端居与奚自，出处各何心。"]},{"t":"石井有感","f":"五言绝句","c":["岁月不可玩，变迁何所无。","青衫今白发，泉谷乃官途。"]},{"t":"示梅山宁老二首 其二","f":"七言绝句","c":["八年再到仍冲暑，长愧堂中结夏僧。","我欲松间借馀地，听风听雨发鬅鬙。"]},{"t":"示梅山宁老二首 其一","f":"七言绝句","c":["梅山不见梅夫子，宗派仍亡宗上人。","梅句不刊宗有集，山应生喜亦生嗔。"]},{"t":"示曾耆英并其侄","f":"七言绝句","c":["伴我山行陈与吴，曾家父子更怜渠。","武山碾得雪相似，来酌观山冰不如。"]},{"t":"立春 其二","f":"七言绝句","c":["昨日元正今日春，佳辰并作一番新。","试看柳色遽如许，无耐梅花憔悴人。"]},{"t":"立春 其三","f":"七言绝句","c":["春日每颁宽大诏，天公意与圣人同。","故于半载焦枯后，一雨聊资土脉通。"]},{"t":"立春 其一","f":"七言绝句","c":["腊中要雪逢三白，春日还沾雨似膏。","天意于农亦良厚，何须耒耜我家操。"]},{"t":"立春日小饮","f":"五言绝句","c":["今日青春立，今年白发多。","酒杯欺我老，梅朵奈渠何。"]},{"t":"仲春杂书二首 其二","f":"五言绝句","c":["二月倏已尽，一春馀几多。","不知花过矣，谁问病如何。"]},{"t":"仲春杂书二首 其一","f":"五言绝句","c":["社公能作雨，社子复成晴。","日薄风仍薄，花明柳亦明。"]},{"t":"全真以斯远所寄文卷后夜赋两绝句元韵作诗寄斯远蕃同之 其一","f":"七言绝句","c":["甘林彼美露初团，纵小犹堪白玉盘。","叹息菊黄虽可待，孤根失所漫荒寒。"]},{"t":"全真以斯远所寄文卷后夜赋两绝句元韵作诗寄斯远蕃同之 其二","f":"七言绝句","c":["行时取别太匆匆，别后经怀数载中。","赖有书函与文卷，不然何地可闻风。"]},{"t":"再来江下示成父","f":"七言绝句","c":["七郎堂下渡船开，岂料今晨又再来。","吴水越山看未足，未妨兄弟与衔杯。"]},{"t":"再蒙签判丈惠示惜花三绝句因次韵 其二","f":"七言绝句","c":["佛屋支撑仅可间，过门无客客非残。","公能有意重来否，竹涧松门暖不寒。"]},{"t":"再蒙签判丈惠示惜花三绝句因次韵 其三","f":"七言绝句","c":["兰馨岂亦竞春狂，不为无人废不芳。","长使幽居在空谷，也胜半额趁时妆。"]},{"t":"再蒙签判丈惠示惜花三绝句因次韵 其一","f":"七言绝句","c":["花飞忽忽减芳菲，欺我新来诗思迟。","笔底羡君能捷敏，好词频许坐中披。"]},{"t":"再赠","f":"七言绝句","c":["众醉纷纷忌独醒，也思放意遣沈冥。","斗牛用事无庸问，为问何年用酒星。"]},{"t":"冲雨投宿石佛院次季承留题韵二首 其二","f":"七言绝句","c":["石佛如今安在哉，至人无往亦无来。","山僧顾欲谈遗迹，说道空岩闭不开。"]},{"t":"冲雨投宿石佛院次季承留题韵二首 其一","f":"七言绝句","c":["尘埃彷佛前朝寺，客子今缘避雨来。","欲访当时漫亡得，绿丛蕉并野花开。"]},{"t":"同何叔信赴在伯之集醉甚既归得二绝句并呈 其二","f":"七言绝句","c":["已向剡溪冲夜雪，要从东阁问官梅。","气豪湖海宁辞醉，老怯风霜祇自哀。"]},{"t":"同何叔信赴在伯之集醉甚既归得二绝句并呈 其一","f":"七言绝句","c":["醉里狂歌君不嗔，知予嗜酒见天真。","还家径卧寒窗底，要暖编麻更■薪。"]},{"t":"同徐斯远看王远父所藏僧圆契梅二首 其二","f":"七言绝句","c":["炎天梅蕊简斋诗，坐胜山村雨雪时。","闵雨正歌云汉句，忽来为我起凉思。"]},{"t":"同徐斯远看王远父所藏僧圆契梅二首 其一","f":"七言绝句","c":["西轩宜热竹能藏，雨落何方此自凉。","已对西湖冰雪句，一时顿有更徐王。"]},{"t":"回憩芙蓉寺偶题","f":"七言绝句","c":["太华难攀十丈花，白莲零落远公家。","此中那得嘉名占，绿水绕除山四遮。"]},{"t":"因汤莘夫行寄欧阳伯威","f":"七言绝句","c":["传得新诗过半年，故应松柏尚苍然。","要持尊酒为君寿，邂逅门前有过船。"]},{"t":"因翟子固行送酒杨谨仲","f":"七言绝句","c":["君行为觅清江宅，水竹依依自作邻。","问字未能从好事，一壶聊为乞诗陈。"]},{"t":"在伯考试未归有怀 其二","f":"七言绝句","c":["相逢共问别来诗，作计君能似我痴。","佳月中秋已无及，菊花十月未为迟。"]},{"t":"在伯考试未归有怀 其三","f":"七言绝句","c":["行路悠悠自有诗，君行况乃暮秋时。","复萌鄙吝疏黄宪，都尽利名亲紫芝。"]},{"t":"在伯教授为考试之行不知其地漫成五诗送之 其四","f":"七言绝句","c":["平生未识荆州牧，诗卷记评王进之。","铃阁纵谈询保社，幸无过语恐遭嗤。"]},{"t":"在伯教授为考试之行不知其地漫成五诗送之 其三","f":"七言绝句","c":["君行不到武昌下，别驾西京刘更生。","但想新知作倾倒，莫闻高论吐峥嵘。"]},{"t":"在伯教授为考试之行不知其地漫成五诗送之 其二","f":"七言绝句","c":["已孤万古中秋月，为约黄花九日杯。","但得交情常旧雨，不辞尊酒理新醅。"]},{"t":"在伯教授为考试之行不知其地漫成五诗送之 其五","f":"七言绝句","c":["峡州使君我所亲，书去犹新报未闻。","此士如今为第一，见之烦为致慇勤。"]},{"t":"在伯教授为考试之行不知其地漫成五诗送之 其一","f":"七言绝句","c":["雨后翛然遂欲秋，登临正尔要诗流。","君行端复何所往，但道东之一舸游。"]},{"t":"孙季章无愧郑季奕徐斯远以仆留智门载酒见过坐中雪作三诗 其一","f":"七言绝句","c":["出山已与晓寒冲，下马频欣束缊逢。","已见南山行更钝，到时山寺已昏钟。"]},{"t":"孙季章无愧郑季奕徐斯远以仆留智门载酒见过坐中雪作三诗 其三","f":"七言绝句","c":["黄公亭上雪飞时，去岁相同此赋诗。","邂逅出山还雪作，端如来赴去年期。"]},{"t":"孙季章无愧郑季奕徐斯远以仆留智门载酒见过坐中雪作三诗 其二","f":"七言绝句","c":["明知喜我出山来，占此僧窗共酒杯。","重愧子云孤好事，绝胜安道不空回。"]},{"t":"安仁舣舟作","f":"七言绝句","c":["客路不知时节移，忽逢柳色已依依。","无悰却数离家日，腊尽春回方始归。"]},{"t":"安福道中见牛行陇亩间龁草而不食禾问之皆云谷成实则牛不复食矣","f":"七言绝句","c":["种得离离职尔劬，朝塍暮陇只生刍。","丝毫无补家先实，愧杀纷纷小丈夫。"]},{"t":"戏呈卢老","f":"七言绝句","c":["晓起题诗砚欲冰，折梅还却步凌兢。","不如纳被蒙头坐，坐到斋鱼始一兴。"]},{"t":"成父居于普宁寺钟楼之下辟以为斋旧名坎止近易榜曰发深省衡州舅氏书之仆为赋四小诗以发深省斋为韵 其四","f":"五言绝句","c":["我有嗜睡癖，衾枕长与偕。","晨昏要无失，曷日住君斋。"]},{"t":"成父期以十八日至已而爽约","f":"七言绝句","c":["已是跫然误足音，更堪疏雨过平林。","呼灯自举一卮酒，颠倒海涛寻破衾。"]},{"t":"扬步","f":"五言绝句","c":["竟日人行绝，惟闻鸟语多。","忽逢樵妇斧，更听牧儿歌。"]},{"t":"早饭龙堂寺","f":"七言绝句","c":["榉藤束缚竹为舆，野饭来寻僧所庐。","茅屋正逢飞卷破，夜来风雨问何如。"]},{"t":"早晴闻啼鸟作","f":"七言绝句","c":["侧岭横峰面面同，雾空烟扫鸟声中。","丁宁不用忧泥滑，珍重提壶屡劝翁。"]},{"t":"早题","f":"五言绝句","c":["欲雨雨似止，为霜霜不成。","山云解衣带，晓日挂铜钲。"]},{"t":"曲江道中二首 其二","f":"七言绝句","c":["晓甑初炊早稻鲜，传呼与觅卖鱼船。","可怜弹铗竟成恨，空对筠篮翠柳穿。"]},{"t":"曲江道中二首 其一","f":"七言绝句","c":["舟下丰城十里馀，树烟鸥泊尽人居。","是间欲画已不得，况有乱舟来捕鱼。"]},{"t":"有怀成父","f":"七言绝句","c":["雪里同登我有诗，可怜同去阻同归。","扶疏夏木浑如许，还想吾庐昼掩扉。"]},{"t":"有怀施文叔寄之","f":"七言绝句","c":["超果寺前江抱村，数株乔木拥山门。","先生得酒日成醉，不负春风野外昏。"]},{"t":"有闻若管吹者意儿童为之问之乃鸟有名竹管者其声政如是云作三绝 其一","f":"七言绝句","c":["细听非笛复非芦，绝讶儿童底所呼。","邂逅因之问何似，鸟鸣竹管自乌乌。"]},{"t":"有闻若管吹者意儿童为之问之乃鸟有名竹管者其声政如是云作三绝 其二","f":"七言绝句","c":["尽日閒窗运秃翁，自怜虚出管城封。","不知尔更何为者，初听犹疑似足蛩。"]},{"t":"有闻若管吹者意儿童为之问之乃鸟有名竹管者其声政如是云作三绝 其三","f":"七言绝句","c":["蚕丝百箔旧曾闻，未说新丝价尔分。","卒岁我无裘褐计，早知劝尔勿多云。"]},{"t":"朱村道中","f":"七言绝句","c":["绿竹人家近小塘，暮秋村酿熟村场。","我行甚亟忘休歇，孤负木犀来往香。"]},{"t":"次王照邻韵二首 其二","f":"七言绝句","c":["虚憍徒恃井陉归，空壁争趋汉鼓旗。","少不如人当自笑，况于心在力疲时。"]},{"t":"次王照邻韵二首 其一","f":"七言绝句","c":["长年未省厌长病，一暑方憎又一春。","把卷颇思亲玉雪，出门无那苦埃尘。"]},{"t":"次张汉卿次房","f":"七言绝句","c":["平生几读右丞诗，未见贤孙归去迟。","邂逅虽欣适吾愿，欲嗟人事好乖离。"]},{"t":"次韵元衡两绝句 其一","f":"七言绝句","c":["倦游如此不嗟穷，醉眼犹能远送鸿。","笑我老无湖海气，但思疆理事南东。"]},{"t":"次韵元衡两绝句 其二","f":"七言绝句","c":["旧说诗坛不可攀，岂期于此得窥斑。","茫茫世事催人别，数见犹期数日閒。"]},{"t":"次韵见可书示二绝并以送行 其二","f":"七言绝句","c":["诗材画笔本同姿，造物嗔人可怨饥。","行橐君无叹悬磬，褐衣我亦欠絇丝。"]},{"t":"次韵见可书示二绝并以送行 其一","f":"七言绝句","c":["鹭立长滩本为饥，水深鱼没定奚为。","何如烟雨青林畔，漠漠冥冥纵所之。"]},{"t":"次韵刘子道机宜送酒","f":"七言绝句","c":["穷居谁肯念穷愁，况复凄凉雨似秋。","疾置送诗仍饷酒，唤回落日在帘钩。"]},{"t":"次韵刘寺簿二首 其二","f":"七言绝句","c":["草树扶疏书满斋，放窗灯火酒尊开。","知公善诱盖前辈，不以见闻嗔去来。"]},{"t":"次韵刘寺簿二首 其一","f":"七言绝句","c":["山寺方同祭祀斋，忽惊茧纸一诗开。","从今傥使亲馀论，愿戒应门许数来。"]},{"t":"次韵孙温叟求芍药二首 其二","f":"七言绝句","c":["送花政自从人乞，名品安能择是非。","风雨连朝更工厄，便应红尽绿垂衣。"]},{"t":"次韵孙温叟求芍药二首 其一","f":"七言绝句","c":["邦人竞说江都胜，一朵千金尚恐非。","自笑寒厅何自得，但馀阶砌长苔衣。"]},{"t":"次韵成父二首 其二","f":"七言绝句","c":["苦爱香醪似蜜甜，旧如杜老意拳拳。","而今已作渊明止，别意欲醺醒重怜。"]},{"t":"次韵成父二首 其一","f":"七言绝句","c":["离居想见泊无娱，肯惮尻为上下舆。","一见故怜无可语，要知终胜百函书。"]},{"t":"次韵伯元季奕送成父因以见寄五绝句 其一","f":"七言绝句","c":["几欲因人与问安，南来不见信州船。","细思人世孰为别，明月相望同一天。"]},{"t":"次韵伯元季奕送成父因以见寄五绝句 其五","f":"七言绝句","c":["秋之为气已堪悲，那对掺掺旧补衣。","为报君家小儿子，见时苍白莫言非。"]},{"t":"次韵伯元季奕送成父因以见寄五绝句 其三","f":"七言绝句","c":["轻薄纷纷覆手空，两家交契百年中。","要折青兰为远赠，同心更助服之衷。"]},{"t":"次韵伯元季奕送成父因以见寄五绝句 其二","f":"七言绝句","c":["句里兴怀快阁晴，独登长是费幽吟。","有兴能来故差易，真愁回棹似山阴。"]},{"t":"次韵伯元季奕送成父因以见寄五绝句 其四","f":"七言绝句","c":["懒性作书非所便，忆君回首漫悠然。","如闻有弟忽相觅，复道诗简见附船。"]},{"t":"次韵李袁州绝句七首 其七","f":"七言绝句","c":["传闻起柂祇数日，引领白云犹在天。","试问今谁满台阁，顾令是老落林泉。"]},{"t":"次韵李袁州绝句七首 其六","f":"七言绝句","c":["先生对宅投金濑，林壑要从东野分。","便觅馀閒访吾舅，郊居赋就比凌云。"]},{"t":"次韵李袁州绝句七首 其五","f":"七言绝句","c":["崧庵视我亦诸孙，已矣无从作九原。","每听先生谈旧事，恍如秉烛对羌村。"]},{"t":"次韵李袁州绝句七首 其四","f":"七言绝句","c":["先生句法从江夏，今代词人孰比肩。","戏出小诗还会否，要收万斛作泓泉。"]},{"t":"次韵李袁州绝句七首 其三","f":"七言绝句","c":["山僧见客苦多惊，问我何时复此行。","笑指壁间旧留句，继题曾辱老先生。"]},{"t":"次韵李袁州绝句七首 其二","f":"七言绝句","c":["路从迫窄因山转，喜见临歧释子庵。","野茗柏香俱不恶，老松高竹更相参。"]},{"t":"次韵李袁州绝句七首 其一","f":"七言绝句","c":["深林尽处背浮图，却悔舆篮不跨驴。","珍重病僧留别语，晦庵去后亦来无。"]},{"t":"次韵杨廷秀太和万安道中所寄七首 其七","f":"七言绝句","c":["莫为趋朝亟载脂，小令羸瘠长肤肌。","帝城书疏旧不入，何有画图传荔枝。"]},{"t":"次韵杨廷秀太和万安道中所寄七首 其六","f":"七言绝句","c":["几为年华叹物华，只今结束定还家。","且看垂发江边树，未问长安一日花。"]},{"t":"次韵杨廷秀太和万安道中所寄七首 其五","f":"七言绝句","c":["先生力学自诚明，忠信今知蛮貊行。","忆昔韩苏两仙伯，海成冬市况融晴。"]},{"t":"次韵杨廷秀太和万安道中所寄七首 其四","f":"七言绝句","c":["几欲裁诗托便风，苦惭别后欠新功。","何时寄我广南作，压倒蕉黄荔子红。"]},{"t":"次韵杨廷秀太和万安道中所寄七首 其三","f":"七言绝句","c":["旧说洛阳天地中，遂令北客病南风。","只今政教通南粤，亦有大寒桑树红。"]},{"t":"次韵杨廷秀太和万安道中所寄七首 其二","f":"七言绝句","c":["爱竹知人忆故山，食贫过午尚悬箪。","长篇乞与小诗并，要似韩豪东野寒。"]},{"t":"次韵杨廷秀太和万安道中所寄七首 其一","f":"七言绝句","c":["记得诗来半说花，不言长道苦风沙。","知公不薄峤南使，政似昔人何以家。"]},{"t":"次韵季承闻田歌","f":"七言绝句","c":["布谷收声老尽秧，直缘避潦有今忙。","歌呼嘹亮相欢杂，肯愧悠悠道上商。"]},{"t":"次韵审知十三日四绝 其一","f":"七言绝句","c":["起看山月堕金盆，不料阴晴忽异门。","我亦忍饥无复睡，绝怜甑倒又空樽。"]},{"t":"次韵审知十三日四绝 其四","f":"七言绝句","c":["连朝风雨已如秋，颇念林园柿栗收。","谩说为生鄙计算，迩来盐米屡关忧。"]},{"t":"次韵审知十三日四绝 其二","f":"七言绝句","c":["咫尺相望得步过，忽然一雨阻山河。","兴来径欲寻君去，数问溪流退几多。"]},{"t":"次韵审知十三日四绝 其三","f":"七言绝句","c":["尺水真成起丈波，水南水北断经过。","几思落笔题观涨，却恨诗材本不多。"]},{"t":"次韵明叔送梅","f":"七言绝句","c":["长条忍使就斩伐，未信园翁珍此花。","不然造物故料理，宜使飘零到我家。"]},{"t":"次韵秉文初九日过先垄 其二","f":"七言绝句","c":["耕道十年无九秋，无田长抱老农愁。","因君动我束书感，君子恶居惟下流。"]},{"t":"次韵秉文初九日过先垄 其一","f":"七言绝句","c":["剥啄敲门走梦周，夜来一雨润方收。","徐郎示我郊行作，亟起讽之天定秋。"]},{"t":"次韵唐与文驿驰代简二绝句 其一","f":"七言绝句","c":["西去曾悲鸟道沿，东来又骇畏途鞭。","如何一舸西江上，放溜乘风不用牵。"]},{"t":"次韵唐与文驿驰代简二绝句 其二","f":"七言绝句","c":["别日常多见愈亲，立谈已觉浣车尘。","诗成两地嗟何及，明月相同影伴身。"]},{"t":"次韵斯远二十六日三绝 其一","f":"七言绝句","c":["几欲收声效不鸣，恶同鸠辈管阴晴。","有时触拨无穷景，又遣新诗取次成。"]},{"t":"次韵斯远二十六日三绝 其三","f":"七言绝句","c":["春风去我孰能留，寒疾闻君顿已瘳。","示以斜斜并整整，故知莫莫复休休。"]},{"t":"次韵斯远十六日见简","f":"七言绝句","c":["忽来叩户新诗句，谓我将行可自疏。","暂向沅湘采兰芷，扶疏终亦爱吾庐。"]},{"t":"次韵斯远见过三首 其三","f":"七言绝句","c":["四山一夜雨连明，岂料新晴顿得成。","还往自兹宁可计，要须留句当题名。"]},{"t":"次韵斯远见过三首 其二","f":"七言绝句","c":["语到蝉连自不休，吾曹岂亦固相求。","望穷云谷云深处，共约骖羸向晚秋。"]},{"t":"次韵斯远见过三首 其一","f":"七言绝句","c":["形影相随一病身，穷愁忽忽又经春。","为传车辙来何自，知是君存寂寞滨。"]},{"t":"次韵斯远去秋八月十三日午睡既醒登山远望见怀 其二","f":"七言绝句","c":["数行书里两章诗，坐诵行哦昼屡移。","赋当疏雨梧桐日，题就扶疏夏木时。"]},{"t":"次韵斯远去秋八月十三日午睡既醒登山远望见怀 其一","f":"七言绝句","c":["驱去复来仍此都，岂惟人诮鬼揶揄。","顾防未免罹矰缴，却使高人赋雁奴。"]},{"t":"次韵斯远雨过彦章并属彦章二首 其二","f":"七言绝句","c":["老去篇章耻未穷，力耕岂谓岁能逢。","切磋政尔须公等，户牖多开恐妄从。"]},{"t":"次韵斯远雨过彦章并属彦章二首 其一","f":"七言绝句","c":["闻君访隐晓冲泥，竹尽林峦入稻畦。","我亦有怀思并辙，不堪驴蹇更牛罢。"]},{"t":"次韵衡州先生岁除前三日席上两绝句 其一","f":"七言绝句","c":["青山著雪倍增妍，青草掀泥浩莫边。","便觉欣荣似春日，不知凋落是残年。"]},{"t":"次韵衡州先生岁除前三日席上两绝句 其二","f":"七言绝句","c":["非无旷野堪犁具，亦有清江可钓丝。","为底崎岖衡岳路，良由寐寤竹斋时。"]},{"t":"次韵衡州先生除夕绝句","f":"七言绝句","c":["怀抱因公得好开，鬓须嗟我怕年来。","敲门既辱频传句，守岁仍呼共引杯。"]},{"t":"江天暮雪","f":"五言绝句","c":["超绝柳州句，粗疏郑谷诗。","扁舟钓台下，曾见雪初时。"]},{"t":"老卿携诗三篇来复答一首","f":"七言绝句","c":["闭门两日病不出，得句谁能就我哦。","贫家尊酒可怜许，饮君宁得到无何。"]},{"t":"自安仁至豫章途中杂兴十九首 其十一","f":"七言绝句","c":["平生食肉吾无相，雨甲烟苗足慰贫。","几日山行更无此，况堪拈米恶于尘。"]},{"t":"自安仁至豫章途中杂兴十九首 其十五","f":"七言绝句","c":["已是酴醾堕玉尘，尚馀芍药殿残春。","山行寂寞那逢此，喜向僧房见斩新。"]},{"t":"自安仁至豫章途中杂兴十九首 其四","f":"七言绝句","c":["几日舟行罢作诗，直缘山水剩含辉。","今朝眼界荒凉甚，却遣毫端为解围。"]},{"t":"自安仁至豫章途中杂兴十九首 其九","f":"七言绝句","c":["积潦当涂三尺强，笋舆那得代浮梁。","脱靴直厉成孤笑，赤脚踏冰思旧狂。"]},{"t":"自安仁至豫章途中杂兴十九首 其十三","f":"七言绝句","c":["参天落落复青青，风过笙竽得细听。","睡思莫将茶料理，只须卧此片时醒。"]},{"t":"自安仁至豫章途中杂兴十九首 其十二","f":"七言绝句","c":["提封俱是太平人，尔辈何缘独苦辛。","见说穷南有蛮蜑，直疑于此是比邻。"]},{"t":"自安仁至豫章途中杂兴十九首 其十八","f":"七言绝句","c":["时雨催农不厌多，客行无奈路长何。","怨咨何与天公事，慷慨聊为劳者歌。"]},{"t":"自安仁至豫章途中杂兴十九首 其六","f":"七言绝句","c":["小立溪头唤野航，雨馀林木倍森凉。","少焉步到临流寺，鹳鹤飞鸣满夕阳。"]},{"t":"自安仁至豫章途中杂兴十九首 其十九","f":"七言绝句","c":["农事催人未遽央，种秧未了插秧忙。","田家作苦吾常逸，所愧饥寒趋路旁。"]},{"t":"自安仁至豫章途中杂兴十九首 其十四","f":"七言绝句","c":["虬龙夭矫已分形，想象灵根长茯苓。","安得一椽风雨庇，要思服食制颓龄。"]},{"t":"自安仁至豫章途中杂兴十九首 其二","f":"七言绝句","c":["漠漠平芜远际天，青山若个暗霾烟。","行人更说桥新断，试遣招呼与借船。"]},{"t":"自安仁至豫章途中杂兴十九首 其五","f":"七言绝句","c":["快雨悬知亦快晴，解包何惜片时程。","须臾雨止晴能好，一道云山泼眼明。"]},{"t":"自安仁至豫章途中杂兴十九首 其十六","f":"七言绝句","c":["晓雨犹偷客枕安，重烦啼鸟报艰难。","整车欲去还休歇，云合忘踪山四攒。"]},{"t":"自安仁至豫章途中杂兴十九首 其一","f":"七言绝句","c":["野市穿残路接溪，败船糜索两相依。","居人欲渡频回首，客子将行屡揽衣。"]},{"t":"自安仁至豫章途中杂兴十九首 其八","f":"七言绝句","c":["郡邑贪残固合诛，衅端繇尔复何如。","官军可怖无轻敌，直恐微躯不足锄。"]},{"t":"自桃川至辰州绝句四十有二 其三十二","f":"七言绝句","c":["一春多雨夏当悭，今岁还防似去年。","玉历检来知小满，又愁阴久碍蚕眠。"]},{"t":"自桃川至辰州绝句四十有二 其二十二","f":"七言绝句","c":["滩里惊涛怖杀人，潭中净绿数浮鳞。","如何咫尺能悬隔，物外区中信莫伦。"]},{"t":"自桃川至辰州绝句四十有二 其二十八","f":"七言绝句","c":["新绿深深嫩更黄，非花非草定何香。","故山草木皆余爱，最爱抽梢竹过墙。"]},{"t":"自桃川至辰州绝句四十有二 其六","f":"七言绝句","c":["夷望山前几钓篷，不惟能雨又能风。","吾身故作魏王瓠，爱此沿洄敏似鸿。"]},{"t":"自桃川至辰州绝句四十有二 其三","f":"七言绝句","c":["上得矶来势已危，忽然缆断不能支。","惊心钓渚河边石，值尔应当应手糜。"]},{"t":"自桃川至辰州绝句四十有二 其十六","f":"七言绝句","c":["风头日日望西南，雨脚悬知不与参。","昨夜北风今日冷，又惊数点落毵毵。"]},{"t":"自桃川至辰州绝句四十有二 其二十四","f":"七言绝句","c":["脱粟粗供朝暮餐，也求鱼菜强充盘。","鱼今绝市菜无有，欲问居人啖马兰。"]},{"t":"自桃川至辰州绝句四十有二 其十一","f":"七言绝句","c":["滟滪瞿唐昔未行，狼头鹿角旧闻名。","辰州瓮子滩头路，夷险不知谁弟兄。"]},{"t":"自桃川至辰州绝句四十有二 其二十七","f":"七言绝句","c":["一月山行意未厌，晚晴仍对雨纤纤。","回思浪涌涛翻际，宁有于今安且恬。"]},{"t":"自桃川至辰州绝句四十有二 其三十八","f":"七言绝句","c":["江涨皆云牵路漫，又云江涨苦无滩。","割晴耕雨难均得，造物于兹良亦难。"]},{"t":"自桃川至辰州绝句四十有二 其十二","f":"七言绝句","c":["明月山前明月池，两崖壁立类磨治。","浯溪未识应相似，好刻中兴第二碑。"]},{"t":"自桃川至辰州绝句四十有二 其三十五","f":"七言绝句","c":["咫尺青山晓未分，旋开还吐尚纷纷。","烟云变态有如此，安得斯奇付大文。"]},{"t":"自桃川至辰州绝句四十有二 其八","f":"七言绝句","c":["水势才收一丈馀，晓来雷雨又何如。","天民天恤应堪恃，我自多忧雪满梳。"]},{"t":"自桃川至辰州绝句四十有二 其四十二","f":"七言绝句","c":["牂牁何处莫穷源，万折千矶剧迅奔。","寸寸上来良亦苦，不知断却几番魂。"]},{"t":"自桃川至辰州绝句四十有二 其三十九","f":"七言绝句","c":["安流倏忽起奔湍，非雨非风势使然。","尽道川流能险恶，不知世有险于川。"]},{"t":"自桃川至辰州绝句四十有二 其二","f":"七言绝句","c":["过了矶头尚有湋，长江万里此为稀。","怅予何可数乘此，宜尔山禽频劝归。"]},{"t":"自桃川至辰州绝句四十有二 其七","f":"七言绝句","c":["晓雨濛濛山欲空，少晴还觉练摇风。","扁舟十日夫何事，只有看山不负公。"]},{"t":"自桃川至辰州绝句四十有二 其十","f":"七言绝句","c":["试手滩头水乱流，铁鎗崖下晚维舟。","两阶舞羽方閒暇，何事兹名有佩牛。"]},{"t":"自桃川至辰州绝句四十有二 其十七","f":"七言绝句","c":["患难嗟予已素行，今朝滩里挽仍撑。","心乎讵敢怀尤怨，命尔何能计死生。"]},{"t":"自桃川至辰州绝句四十有二 其三十七","f":"七言绝句","c":["坐对苍然暮色侵，忽惊萤烛度枝深。","少年嗜学犹馀志，安得茅檐把卷临。"]},{"t":"自桃川至辰州绝句四十有二 其三十六","f":"七言绝句","c":["昨日江清可濯缨，今朝潢潦忽能盈。","发洪想有山崩处，一雨安能作许生。"]},{"t":"自桃川至辰州绝句四十有二 其十八","f":"七言绝句","c":["无策资身每自嗤，始谋不善悔何追。","行乎患难宁今日，何暇更论淹速期。"]},{"t":"自桃川至辰州绝句四十有二 其十九","f":"七言绝句","c":["飞流溅沫瀑争砻，电击雷惊江落洪。","尽日喧喧不能息，诵书妨我课儿童。"]},{"t":"自桃川至辰州绝句四十有二 其四","f":"七言绝句","c":["钓石疑为借石低，月岩穿石两空梯。","逃虚尚说闻人喜，况此依然面目迷。"]},{"t":"自桃川至辰州绝句四十有二 其九","f":"七言绝句","c":["山鸟初鸣麂度滩，少焉还叫火炎山。","仆来告我为晴候，穴雨巢风不可删。"]},{"t":"自桃川至辰州绝句四十有二 其二十三","f":"七言绝句","c":["雨堕初看珠颗圆，风来忽散縠丝牵。","青山四合江如泻，忆著桐江江上船。"]},{"t":"自桃川至辰州绝句四十有二 其二十","f":"七言绝句","c":["望极千山不见村，忽逢三两仅崖根。","几年生聚才如此，信是荒寒不足论。"]},{"t":"自桃川至辰州绝句四十有二 其三十","f":"七言绝句","c":["细雨冥冥梅欲黄，故怜时节似江乡。","有书不读高成束，蒸败蠹侵谁与防。"]},{"t":"自桃川至辰州绝句四十有二 其四十一","f":"七言绝句","c":["大麦虽黄草与长，趁春只用野生桑。","为生可叹微如是，应坐人稀地力荒。"]},{"t":"自桃川至辰州绝句四十有二 其五","f":"七言绝句","c":["草屋竹门江岸旁，三三两两竞携将。","尔曹应念宦游好，不念西来道阻长。"]},{"t":"自桃川至辰州绝句四十有二 其二十五","f":"七言绝句","c":["摘得青梅江岸边，儿童竞食也堪怜。","山青指问红何样，说是石榴花欲然。"]},{"t":"自桃川至辰州绝句四十有二 其十四","f":"七言绝句","c":["一篙真可百滩空，赣水辰溪大略同。","我乃涨馀方逆上，终朝歌笑愧篙工。"]},{"t":"自桃川至辰州绝句四十有二 其三十四","f":"七言绝句","c":["前有天随后老坡，杞粮仍欲寿西河。","吾今何意更思此，但喜杯羹风味多。"]},{"t":"自桃川至辰州绝句四十有二 其二十六","f":"七言绝句","c":["不但投林雀闹枝，沙禽水宿亦争涯。","不然故欲相呼唤，恨我形单影自随。"]},{"t":"自桃川至辰州绝句四十有二 其二十一","f":"七言绝句","c":["美玉曾闻种得生，精金此地亦陶成。","不知造物须生此，何似嘉禾令土平。"]},{"t":"自桃川至辰州绝句四十有二 其四十","f":"七言绝句","c":["反照入江雷殷然，直疑飞雨堕谈间。","不知吹落何方去，突兀犹馀云涌山。"]},{"t":"自桃川至辰州绝句四十有二 其三十一","f":"七言绝句","c":["雨来山色暗成愁，雨后波光翠欲浮。","山色水光元自好，宦情羁思苦悠悠。"]},{"t":"自桃川至辰州绝句四十有二 其十五","f":"七言绝句","c":["谁道蛮州异故园，夏来草木亦苍然。","扶疏绕屋平生句，有愧青山啼杜鹃。"]},{"t":"自桃川至辰州绝句四十有二 其二十九","f":"七言绝句","c":["性有耽山且画看，阴晴朝暮若能殚。","天公似病诗才窄，乞与西来眼界宽。"]},{"t":"自造口放舟至道林院偶题","f":"七言绝句","c":["晓起乘舟江上凉，昼携蕲竹卧僧房。","隐雷骤作分龙雨，限我潇潇幽梦长。"]},{"t":"至日雪后简在伯二首 其二","f":"五言绝句","c":["灰里拨阴何，思君欲就哦。","还忧好时节，来搅或遭呵。"]},{"t":"至日雪后简在伯二首 其一","f":"五言绝句","c":["一雪顿能晴，江山万里明。","故胜茅屋底，空听滴檐声。"]},{"t":"至邑有感二首 其二","f":"七言绝句","c":["老稚欢呼南北街，争看前日令君来。","看花不比玄都观，尽是当时手自栽。"]},{"t":"至邑有感二首 其一","f":"七言绝句","c":["朱弦昔日被歌声，岁月频更感易生。","唯有锦江桥下水，相逢不改旧时清。"]},{"t":"舟中二首 其二","f":"七言绝句","c":["岁月侵人去若奔，雪消归水不留痕。","诗情本自无多子，深谢江山稍见存。"]},{"t":"舟中二首 其一","f":"七言绝句","c":["频岁崎岖道路劳，江山妙处属吾曹。","欲将一笼盛归去，安得并州快剪刀。"]},{"t":"舟中雨","f":"七言绝句","c":["秋草犹青可放牛，雨林如豁更鸣鸠。","荒鸡渺渺三家墅，白鸟悠悠数里洲。"]},{"t":"舟中独饮","f":"七言绝句","c":["已是支离百不禁，况堪多病苦相侵。","村沽纵薄可不醉，梅半落时天政阴。"]},{"t":"舟中晚作二绝 其二","f":"七言绝句","c":["严婺江山天下奇，经行凡作几篇诗。","何当便毕尚平趣，占断清波垂钓丝。"]},{"t":"舟中晚作二绝 其一","f":"七言绝句","c":["天如悭此好江山，故遣风帆送我还。","日暮白鸥犹未宿，冲烟时复度前湾。"]},{"t":"舟中清明","f":"七言绝句","c":["三日舟行风打头，春愁那更值羁愁。","一年谁似清明节，忍向天涯除破休。"]},{"t":"舟行遇雪二首 其二","f":"七言绝句","c":["沙嘴萦分直更纡，望中不尽渺愁予。","晚来一雨便成雪，翠巘修林同一如。"]},{"t":"舟行遇雪二首 其一","f":"七言绝句","c":["老树槎牙冻不枯，雪花初集更敷腴。","悬崖斗峻人踪绝，漠漠荒祠落社乌。"]},{"t":"西轩杂题三首 其三","f":"七言绝句","c":["卧看修筠不见梢，所欣轩户绿阴交。","蝉吟鸟语尽堪喜，不用先生自解嘲。"]},{"t":"西轩杂题三首 其二","f":"七言绝句","c":["早风蓬勃不能凉，独卧幽轩日日长。","赖有图书慰岑寂，左抽右取略无妨。"]},{"t":"西轩杂题三首 其一","f":"七言绝句","c":["晓起看山谓得真，突然山外见嶙峋。","须臾释屩浑无迹，绝倒山灵解戏人。"]},{"t":"西湖雪后","f":"七言绝句","c":["行到湖边却笋舆，眼中浑似画屏纡。","梅花又作临风笑，亦有高人似旧无。"]},{"t":"观吴兴俞君新之作画于瑞竹俞君索诗漫兴四绝句 其二","f":"五言绝句","c":["平生苕霅舟，略计忘几历。","诗里不能收，付君医画癖。"]},{"t":"观吴兴俞君新之作画于瑞竹俞君索诗漫兴四绝句 其一","f":"五言绝句","c":["我无岩壑姿，空有山林想。","看君落笔时，形滞心已往。"]},{"t":"观吴兴俞君新之作画于瑞竹俞君索诗漫兴四绝句 其四","f":"五言绝句","c":["烦君索我诗，我诗老不支。","因君为作气，竟亦不能奇。"]},{"t":"观吴兴俞君新之作画于瑞竹俞君索诗漫兴四绝句 其三","f":"五言绝句","c":["作画与作诗，妙处元同科。","苟无自得处，当复奈渠何。"]},{"t":"观祝少林所藏画三首 其三 李龙眠画","f":"七言绝句","c":["吾祖曾为沙苑牧，有孙穷相合骑驴。","朝来忽起驰驱兴，为见龙眠十马图。"]},{"t":"观祝少林所藏画三首 其二 百牛图","f":"七言绝句","c":["沈牛二可归耕去，百尾言之无乃多。","安得神仙张果老，为君叱起满池阿。"]},{"t":"观祝少林所藏画三首 其一 米元晖画","f":"七言绝句","c":["萧寺相从三十日，知君有画未曾窥。","烟云过眼还收去，恰似凭栏立久时。"]},{"t":"观徐复州家书画七首 其七","f":"七言绝句","c":["并竹作门亭得山，我来还值雪消残。","江梅未有腊梅破，丈室不须香屈盘。"]},{"t":"观徐复州家书画七首 其六","f":"七言绝句","c":["误笔犹能作牸牛，信知书画本同流。","不惟下笔苏仙似，更似斯人不可求。"]},{"t":"观徐复州家书画七首 其五","f":"七言绝句","c":["万竹阴中屋数间，几回剥啄叩柴关。","忽开短纸霜雪干，如对照人冰玉颜。"]},{"t":"观徐复州家书画七首 其四","f":"七言绝句","c":["旷怀谁不作山游，谁似柳州谈永州。","何能乞我一片石，刻此数纸俱传流。"]},{"t":"观徐复州家书画七首 其三","f":"七言绝句","c":["世人竞写襄阳字，政似云师太白诗。","才匪若人宁躐等，自颠自醉祇成痴。"]},{"t":"观徐复州家书画七首 其二","f":"七言绝句","c":["苏公书法自颜行，犹谓蔡公居第一。","我穷颇亦类贾胡，笔势翩翩疑可识。"]},{"t":"观徐复州家书画七首 其一","f":"七言绝句","c":["草衣旧识牡丹碑，字字腾拿更倔奇。","我亦参军成潦倒，愧无笔力欠渠诗。"]},{"t":"观曾文清诗刻","f":"七言绝句","c":["我访茶山公已仙，向人惟有竹苍然。","摩挲欲问当时事，竹不能言风为传。"]},{"t":"过王宗臣允元园庐三首 其三","f":"七言绝句","c":["拟欲过君非一日，哭妻值我买船东。","人事好乖有如此，转头今忽两春风。"]},{"t":"过王宗臣允元园庐三首 其二","f":"七言绝句","c":["不但栽梅如昔人，诗名籍籍旧传闻。","我来岂直为花设，倾倒相期出近文。"]},{"t":"过王宗臣允元园庐三首 其一","f":"七言绝句","c":["大梁城里王居士，园有江南数种梅。","乱后只疑随劫火，那知移向此间来。"]},{"t":"过生米市舣舟求浴望山巅有屋岿然至石岸数步宛转荒级榜曰钓矶入门古坛对江上则有独柏馀屋悉具体问之云施肩吾尝垂纶于此柏则唐胡天师所植他无碑记惟华邦直则留题一诗有石刻因用其韵题钓矶又复用小阁壁间韵留题胡柏并书柱间浴罢理棹而去 其二","f":"七言绝句","c":["荒坛有柏翠参天，尽道栽从五代前。","仙事茫茫真是否，试当风月听跫然。"]},{"t":"过生米市舣舟求浴望山巅有屋岿然至石岸数步宛转荒级榜曰钓矶入门古坛对江上则有独柏馀屋悉具体问之云施肩吾尝垂纶于此柏则唐胡天师所植他无碑记惟华邦直则留题一诗有石刻因用其韵题钓矶又复用小阁壁间韵留题胡柏并书柱间浴罢理棹而去 其一","f":"七言绝句","c":["枕水危矶峙不流，是谁曾此被羊裘。","遗踪几觅无从问，落日清风过树头。"]},{"t":"过邻家看菊乞之以归","f":"七言绝句","c":["径荒空道菊犹存，岂不怀归病苦昏。","乞得邻花有根拨，带泥栽著定州盆。"]},{"t":"过饮毕叔文家题其壁","f":"七言绝句","c":["拟过君家看牡丹，数枝才及海棠看。","百年旧事谁从说，杯酒相逢强自宽。"]},{"t":"过叔异曲江矶叔异已赴官矣题其壁","f":"七言绝句","c":["故人去适梅花外，客子来哦桂树秋。","欲寄一行无雁过，漫题数字答蛩幽。"]},{"t":"过雨市二首 其二","f":"七言绝句","c":["晴里看山故自佳，雨边益觉兴无涯。","我家正在千山底，每一看山还自嗟。"]},{"t":"过雨市二首 其一","f":"七言绝句","c":["卢溪溪水接宣风，四面青山图画中。","尽日苦吟吟不足，始知才尽景无穷。"]},{"t":"过祝氏南山","f":"五言绝句","c":["梦寐南山久，今朝始一来。","主人虽不在，亦许步崔嵬。"]},{"t":"过旁罗见灵山","f":"七言绝句","c":["过得旁罗上下滩，望中青出是灵山。","三年此地四来往，老矣向渠成厚颜。"]},{"t":"过湖","f":"五言绝句","c":["杯珓吉难同，开船得转风。","无云仗神道，人厄匪天穷。"]},{"t":"过湖偶题书于邬子之津","f":"七言绝句","c":["洞庭厥大九州间，此地吞潴未觉悭。","一抹远青为四望，亦云髣髴似君山。"]},{"t":"过湖得便风舟甚驶","f":"七言绝句","c":["鸟飞不尽水黏天，隐隐青山若个边。","六幅蒲帆去如箭，江神有意特相怜。"]},{"t":"严从礼求先照轩诗","f":"五言绝句","c":["日上照万物，心明观一身。","为光讵资火，在我不关人。"]},{"t":"严先辈送鲤鱼","f":"七言绝句","c":["严郎得鱼不敢食，走送茅斋嫌步迟。","却愧家贫惯粗粝，无人为我脍银丝。"]},{"t":"伯山因其侄来惠书报以二绝 其二","f":"七言绝句","c":["蕙亩兰开梅吐枝，近来凡有几篇诗。","已令经纪江头竹，早晚为君修短篱。"]},{"t":"伯山因其侄来惠书报以二绝 其一","f":"七言绝句","c":["昔日穷岗今竹溪，更生臣向复奚疑。","此中安否渠能说，懒复作书聊寄诗。"]},{"t":"馀干登眺有怀 其二","f":"七言绝句","c":["溪山虽好政须人，终日伥伥此水滨。","试并栏干一回首，祇馀鸥鸟似相亲。"]},{"t":"馀干登眺有怀 其一","f":"七言绝句","c":["溪山得意竟忘归，岁月飘零两鬓稀。","祇有裴回与搜句，老无笔力愧传衣。"]},{"t":"余客长沙寒热骤作其證未分理掾次律张君为致医王生述治之药与病合两日愈作七言二韵诗二首赠之 其二","f":"词","c":["频能通汗信柴胡，亦是于君想报珠。","传闻治?更多活，岂止飘零一老夫。"]},{"t":"余客长沙寒热骤作其證未分理掾次律张君为致医王生述治之药与病合两日愈作七言二韵诗二首赠之 其一","f":"七言绝句","c":["士不知闻未易轻，问医谁复话君名。","殷勤多谢长沙掾，为我致之分死生。"]},{"t":"初九日 其一","f":"七言绝句","c":["一片花飞春未知，杜陵野客已深悲。","况堪昨夜狂风雨，吹折东家桃树枝。"]},{"t":"初九日 其二","f":"七言绝句","c":["日日题诗待海棠，要从地主借绳床。","偶因风雨愆期至，已是飘零学退妆。"]},{"t":"初八日微雨明日犹有赐意作两绝句 其二","f":"七言绝句","c":["不堪积暑滞烦疴，幸甚新凉脱网罗。","闻道重阳更逢闰，今年节意属秋多。"]},{"t":"初八日微雨明日犹有赐意作两绝句 其一","f":"七言绝句","c":["小雨那能救旱禾，定催粟玉放庭柯。","一从赋罢横斜影，谁复风流似汝多。"]},{"t":"初寒无衾买纸被以纾急作四绝 其四","f":"七言绝句","c":["识字谁令胜烂奚，自应无褐更无衣。","宵安亦念明朝计，儿报屋檐生早晖。"]},{"t":"初寒无衾买纸被以纾急作四绝 其二","f":"七言绝句","c":["瑟缩从渠体尚生，不妨攲拥度天明。","书生活计能消底，太息牛衣王仲卿。"]},{"t":"初寒无衾买纸被以纾急作四绝 其三","f":"七言绝句","c":["度夕阴风吹扊扅，布衾如铁念娇儿。","夜来例拜奇温赐，但觉安眠晓不知。"]},{"t":"初寒无衾买纸被以纾急作四绝 其一","f":"七言绝句","c":["平生结得楮生缘，觅句抄书日费捐。","只有夜窗宜暂舍，也须包裹伴幽眠。"]},{"t":"即事呈斯远三首 其三","f":"七言绝句","c":["一花固觉有馀香，况此寒梢数尺长。","怪底诗来总清绝，始知逸韵与相当。"]},{"t":"即事呈斯远三首 其二","f":"七言绝句","c":["去却蔫花意转新，是知疏密总宜人。","正由秽去清虚集，不碍萧然冠与巾。"]},{"t":"即事呈斯远三首 其一","f":"七言绝句","c":["并湖微径曲通村，步步看梅遂款门。","犬似不能知客意，苦相唐突吠篱根。"]},{"t":"听雨堂二首 其二","f":"七言绝句","c":["曾见宋公及可公，自应诗句有家风。","不因避疾小盘礴，那得清谈半日同。"]},{"t":"听雨堂二首 其一","f":"七言绝句","c":["竹径参差人不知，窈然终日坐题诗。","我来欲去仍遗恨，不见萧萧风雨时。"]},{"t":"呈子肃三首 其三","f":"七言绝句","c":["牢落空房我挂包，忆君过我夜推敲。","东南大半行将遍，应有新诗许借钞。"]},{"t":"呈子肃三首 其二","f":"七言绝句","c":["忆过君家黄堰居，春风杨柳政扶疏。","人生离合自多感，邂逅更当摇落馀。"]},{"t":"呈子肃三首 其一","f":"七言绝句","c":["坊静行人昼成绝，柳吹黄叶落毵毵。","知君不作官居看，陋巷旧谙人不堪。"]},{"t":"呈折子明丈十首 其十","f":"七言绝句","c":["道山峻峙不容攀，咫尺今遭风引还。","闻道公曾踞其上，莫憎官府久人间。"]},{"t":"呈折子明丈十首 其九","f":"七言绝句","c":["客舍潭州又一春，花时风雨困频频。","欲知夏木扶疏处，好挂陶翁洒酒巾。"]},{"t":"呈折子明丈十首 其八","f":"七言绝句","c":["如闻欲印葆真诗，我亦犹多未见之。","副本傥蒙轻乞与，真成暴富诧穷儿。"]},{"t":"呈折子明丈十首 其七","f":"七言绝句","c":["旧有园林新近开，凿池培址遂成台。","台颠纵有蒙笼处，不碍遥山次第来。"]},{"t":"呈折子明丈十首 其六","f":"七言绝句","c":["相逢几说李端公，未报舒州谢表通。","要识淮南佳绝地，灊山皖水莫之同。"]},{"t":"呈折子明丈十首 其五","f":"七言绝句","c":["曾门昔作广文官，先正曾同苜蓿盘。","交道不惟当日见，遗风更俾后人看。"]},{"t":"呈折子明丈十首 其四","f":"七言绝句","c":["不惟句律有家风，笔阵仍推大令工。","兹道祗今殊寂寞，求公须向古人中。"]},{"t":"呈折子明丈十首 其三","f":"七言绝句","c":["故家人物几沈沦，公独风流似昔人。","不但金声吐佳句，尚馀玉立耸长身。"]},{"t":"呈折子明丈十首 其二","f":"七言绝句","c":["朝廷经略在中原，西北人才要讨论。","节传曾闻付吾属，潇湘可俾卧林园。"]},{"t":"呈折子明丈十首 其一","f":"七言绝句","c":["儿时已见葆真诗，写诵抄藏不惮疲。","白首始游衡岳寺，扶藜处处读苔碑。"]},{"t":"呈杨谨仲二首 其二","f":"七言绝句","c":["南浦相逢使蜀船，为余高举送行篇。","我行纵有荣枯异，可乏新诗处处传。"]},{"t":"呈杨谨仲二首 其一","f":"七言绝句","c":["清江郭内千竿竹，爱此浑如屋上乌。","我亦山中富此物，若何奔走为饥驱。"]},{"t":"呈宜之兄八首 其六","f":"五言绝句","c":["书中道何似，诗有林霏寄。","怪其句律工，定自工夫至。"]},{"t":"呈宜之兄八首 其二","f":"五言绝句","c":["别来才一书，似若向兄疏。","逢人问江右，说兄不敢虚。"]},{"t":"呈明叔七首 其七","f":"七言绝句","c":["伯威虽拙诗故巧，我拙似渠诗欠工。","竹溪想见梅花发，问讯穷冈今不穷。"]},{"t":"呈明叔七首 其六","f":"七言绝句","c":["岁寒谁觅此穷交，只有梅花发故梢。","我坐多言得穷祟，不应于汝更轻嘲。"]},{"t":"呈明叔七首 其五","f":"七言绝句","c":["手种竹边梅一株，地幽终觉病而癯。","不然我尔要相似，异日重看瘠解腴。"]},{"t":"呈明叔七首 其四","f":"七言绝句","c":["一枝自可不须多，少已难知多奈何。","汉殿纷纷锵剑佩，桐江但有一渔蓑。"]},{"t":"呈明叔七首 其三","f":"七言绝句","c":["屋角梅开才一枝，道人眼净得先窥。","寒厅政尔犹官舍，不似茅檐见汝时。"]},{"t":"呈明叔七首 其二","f":"七言绝句","c":["今年梅愈去年多，我亦催行奈汝何。","此树与君同所植，交情要保岁寒柯。"]},{"t":"呈明叔七首 其一","f":"七言绝句","c":["近郭梅开应已多，几思扶策奈慵何。","兴来起觅墙阴树，点检无花除病柯。"]},{"t":"呈愚卿昆仲二首 其二","f":"七言绝句","c":["忆过君家梅半开，梅花未落我重来。","寻常一饭履迹扫，独向君家不记回。"]},{"t":"呈愚卿昆仲二首 其一","f":"七言绝句","c":["百个脩篁一树梅，蕙盆兰斛共相陪。","客来不但翻书帖，兴至更能传酒杯。"]},{"t":"呈潘潭州十首 其十","f":"七言绝句","c":["臂膝真成具老形，每逢趋走叹伶仃。","故园松菊幸亡恙，何日扶藜得屡经。"]},{"t":"呈潘潭州十首 其九","f":"七言绝句","c":["满城游女竞纷纷，柳岸桃蹊昼复曛。","不道贫家有机杼，夜窗灯火尚加勤。"]},{"t":"呈潘潭州十首 其八","f":"七言绝句","c":["少陵已入严公幕，徐孺还为仲举宾。","自愧无诗复非隐，况堪谋食更忧贫。"]},{"t":"呈潘潭州十首 其七","f":"七言绝句","c":["昔者湘西借榻眠，自嗟老眼负青编。","虽然旧识山中趣，绝爱松风泻百泉。"]},{"t":"呈潘潭州十首 其六","f":"七言绝句","c":["犯雪渠乘访戴舟，不逢安道便归休。","我今一月春风里，纵复回舟匪浪游。"]},{"t":"呈潘潭州十首 其五","f":"七言绝句","c":["微官本欲救饥寒，欲逭啼号政尔难。","不是贤侯任吾耻，未容陋巷乐瓢箪。"]},{"t":"呈潘潭州十首 其四","f":"七言绝句","c":["楚国固多兰与荃，长林野水若何边。","樵夫政自不知贵，采卖何曾直一钱。"]},{"t":"呈潘潭州十首 其三","f":"七言绝句","c":["梅花初出炯如冰，未许馀花似我能。","太息天公不加意，放教风雨苦侵陵。"]},{"t":"呈潘潭州十首 其二","f":"七言绝句","c":["江边石上白皑皑，远对难分李与梅。","因是欲占春早晚，桃花一树有新开。"]},{"t":"呈潘潭州十首 其一","f":"七言绝句","c":["西江亭上东风客，鸥鸟重来似亦驯。","买得小舟连夜发，不知肯别定留人。"]},{"t":"妙香院僧堂后路直临溪石台古松蟠其上松之下有足迹及石穴三十馀浅容杯水问僧云自昔葛洪鍊丹种桃于此穴乃丹灶其数三十有二适与龟峰相应亦谓足迹为仙人迹又有云日光照石壁隐若青红盖桃影云作两绝 其一","f":"七言绝句","c":["台高十丈独株松，下有仙人旧履踪。","三十二窠丹灶在，亦云数目应龟峰。"]},{"t":"妙香院僧堂后路直临溪石台古松蟠其上松之下有足迹及石穴三十馀浅容杯水问僧云自昔葛洪鍊丹种桃于此穴乃丹灶其数三十有二适与龟峰相应亦谓足迹为仙人迹又有云日光照石壁隐若青红盖桃影云作两绝 其二","f":"七言绝句","c":["壁间石色隐青红，指似夭夭即此中。","金石著文犹叵信，况堪传者自渔翁。"]},{"t":"孝扬成父约须晴见过二首 其二","f":"七言绝句","c":["雨来喜逭车田苦，晴至欣成穫稻忙。","协趣终焉在农舍，倦游不拟老官仓。"]},{"t":"孝扬成父约须晴见过二首 其一","f":"七言绝句","c":["积雨能凉故自佳，候当秋早欲收畬。","频宵佳月连朝雾，雾破山空日已斜。"]},{"t":"张帅置酒环波觞孙会之签判严造道主簿及蕃作绝句呈二君","f":"七言绝句","c":["炎蒸三伏有无中，十里荷花四面风。","严濑苏门两奇侣，一尊共德使君公。"]},{"t":"张伯永折梅走笔谢之","f":"七言绝句","c":["岁晚梅花未经眼，自嗟枉作近南官。","忽来数朵惊初识，已是先生觅句残。"]},{"t":"张伯永和诗以仆送笋减于常年复用韵以调一笑 其二","f":"七言绝句","c":["八珍既饱思持去，借问何如一脔尝。","笋例减常犹费说，可堪馀事极更张。"]},{"t":"张伯永和诗以仆送笋减于常年复用韵以调一笑 其一","f":"七言绝句","c":["竹薄方思渐补锄，笋时可得尽驱除。","此生已负管城债，计且不悛真个疏。"]},{"t":"怀玉山旧游寄王彦博徐审知 其一","f":"七言绝句","c":["南山白塔高何许，弄日摩穹相与曾。","放歌直下清溪去，落日半衔渔木灯。"]},{"t":"怀玉山旧游寄王彦博徐审知 其二","f":"七言绝句","c":["何人作亭山半道，颇解发舒山掩藏。","几度携筇挽君去，月高人寂尚绳床。"]},{"t":"怀玉山旧游寄王彦博徐审知 其四","f":"七言绝句","c":["王郎家近石田溪，溪上行人古路迷。","王郎家苦了无事，自沟溪水灌蔬畦。"]},{"t":"怀玉山旧游寄王彦博徐审知 其三","f":"七言绝句","c":["下湖堤上青青柳，曾为行人系马鞍。","落魄还成一春事，料应飞絮也漫漫。"]},{"t":"怀远父斯远成父 其二","f":"七言绝句","c":["春风吹雨昼成昏，萧寺萧条早闭门。","坐久行人更萧瑟，定倾老酒向何村。"]},{"t":"怀远父斯远成父 其一","f":"七言绝句","c":["徐郎已渡浙江潮，王子还从折简招。","平日往还惟二士，去余何以慰亡聊。"]},{"t":"怀明叔","f":"七言绝句","c":["江天买得总输君，我亦当年作记人。","珍重平生一杯酒，又孤洲渚绿生春。"]},{"t":"怀祖印","f":"七言绝句","c":["古寺僧容客寓居，客行仍许借藏书。","老无眼力书慵看，忆著竹根泉漱渠。"]},{"t":"怀梅花及斯远","f":"七言绝句","c":["几思载酒更携筇，一访梅花山崦中。","忽念去君三十里，怅然将复与谁同。"]},{"t":"投王饶州日勤四首 其四","f":"七言绝句","c":["使君本是经邦手，聊为疲民滞一方。","直道正声谁可拟，百年文正故堂堂。"]},{"t":"投王饶州日勤四首 其三","f":"七言绝句","c":["为政悬知如治疾，岂求汤砭一时功。","但今安养无遗策，肤革充盈由本丰。"]},{"t":"投王饶州日勤四首 其二","f":"七言绝句","c":["我行三日鄱阳路，每向居民说岁年。","荞麦吐花胜宿麦，山田小旱熟湖田。"]},{"t":"投王饶州日勤四首 其一","f":"七言绝句","c":["福星谁遣出虚危，帝念鄱人因数饥。","试问公来若为政，皆言吏瘠与民肥。"]},{"t":"投曾秀州逢四首 其四","f":"七言绝句","c":["请到江西得正宗，后来曾吕出群雄。","大阳遗履归何处，端欲从公一破聋。"]},{"t":"投曾秀州逢四首 其三","f":"七言绝句","c":["有蟹无监乃乐邦，人生如意信难双。","公才自是明堂用，寄语蚍蜉盍少降。"]},{"t":"投曾秀州逢四首 其二","f":"七言绝句","c":["人物如公乃作州，不知谁合致公侯。","清名不与官称等，颇解天公用意不。"]},{"t":"投曾秀州逢四首 其一","f":"七言绝句","c":["我向茶山得屡行，至今人说老先生。","九原不作吾安仰，宗武宗文贤弟兄。"]},{"t":"折梅赠答二首 其二","f":"七言绝句","c":["昔人行役功名误，嗟我何为久未回。","落尽繁花有青子，期君烟雨上池台。"]},{"t":"折梅赠答二首 其一","f":"七言绝句","c":["送君祇数梅花节，开到岭梅君不回。","折得花来有重出，妾惟孤影愧妆台。"]},{"t":"报谒徐大雅仁因以题赠三首 其三","f":"七言绝句","c":["兰芽紫坼映青盆，杏蕊红深供佛瓶。","何独春能归草木，看君已老鬓重青。"]},{"t":"报谒徐大雅仁因以题赠三首 其二","f":"七言绝句","c":["我住东郊祇树园，无人肯顾席为门。","多君用意非流俗，忙里偷閒每见存。"]},{"t":"报谒徐大雅仁因以题赠三首 其一","f":"七言绝句","c":["好在东都孺子孙，壮年曾谒舍人门。","祇今此道同终少，君独深藏耻自论。"]},{"t":"杨知录送千叶白莲","f":"七言绝句","c":["几思载酒问扬雄，不但尊空囊亦空。","枉道荷花有新发，又闻能白胜能红。"]},{"t":"步北园示沈四弟","f":"七言绝句","c":["得趣堂到蓬荟深，主人何惜费千金。","我行旬月当重到，要见梅花出树林。"]},{"t":"步溪头 其二","f":"七言绝句","c":["浴凫拍拍已春声，相趁双飞属玉明。","更待前山一犁足，断槎号濑总波平。"]},{"t":"步溪头 其三","f":"七言绝句","c":["草软沙平路不泥，岸巾扶策步循堤。","江南春事信能早，正月已闻林鸟啼。"]},{"t":"步溪头 其一","f":"七言绝句","c":["溪头弱柳已丝垂，那得江南尚好枝。","从此春风日亡赖，与须排写付新诗。"]},{"t":"沅陵见招赏海棠病不能往辄尔言谢三首 其三","f":"七言绝句","c":["二月已尽三月来，计君行日已相催。","奈何病著不能往，岂但看花仍把杯。"]},{"t":"沅陵见招赏海棠病不能往辄尔言谢三首 其二","f":"七言绝句","c":["四海知名蜀海棠，是邦元与蜀同方。","少陵当日犹无语，而我何人敢漫狂。"]},{"t":"沅陵见招赏海棠病不能往辄尔言谢三首 其一","f":"七言绝句","c":["去年已负海棠期，今岁还当卧病时。","造物小儿应见相，恐余无此看花时。"]},{"t":"沅陵契丈用蕃将至辰州寄在伯兄韵作诗见属用韵奉答二首 其二","f":"七言绝句","c":["能事岂工刀与笔，閒情聊付咏而觞。","生前忧累须陶写，身后声名尽在亡。"]},{"t":"沅陵契丈用蕃将至辰州寄在伯兄韵作诗见属用韵奉答二首 其一","f":"七言绝句","c":["往日交游才著我，近来酬唱喜添君。","请君立拜诗坛将，容我閒寻茗椀勋。"]},{"t":"灵鹫道间","f":"七言绝句","c":["霏霏小雨湿松株，疑是初成道士图。","我亦搜诗要穷底，此时幽思不枝梧。"]},{"t":"社日醉起","f":"七言绝句","c":["醉状初如春水船，梦成蝴蝶更翩翩。","觉来已是情无奈，那更急风吹雨颠。"]},{"t":"花屿","f":"五言绝句","c":["杨垂空寄恨，草碧会添愁。","祇有花无数，春风醉不休。"]},{"t":"花屏","f":"五言绝句","c":["阴能间其疏，竹可扶其弱。","点缀自天然，讵须金孔雀。"]},{"t":"赤岸道中呈斯远","f":"五言绝句","c":["小雨洗红叶，青山舒白云。","秋风有奇处，我友得平分。"]},{"t":"还家二绝 其一","f":"七言绝句","c":["小出端如远客归，仆迎儿候犬循衣。","家人不问城中事，但道雨多蔬茹肥。"]},{"t":"还家二绝 其二","f":"七言绝句","c":["竹因易叶听风吹，入屋穿窗纵所之。","我亦闭斋愆扫溉，渠因投隙遂纷披。"]},{"t":"连日得顺风","f":"七言绝句","c":["上水深虞费挽牵，顺风似得江神怜。","云山好处留不得，纵望令人空惘然。"]},{"t":"连雪不已复作绝句咏之及六而止殆未免不愁冻杀之诮也 其四","f":"五言绝句","c":["不假丹青手，居成水墨图。","莫嗟玄尚白，靡叹粪难污。"]},{"t":"连雪不已复作绝句咏之及六而止殆未免不愁冻杀之诮也 其二","f":"五言绝句","c":["对岸初封屋，临流已蔽汀。","长江停衮衮，去鸟失冥冥。"]},{"t":"连雪不已复作绝句咏之及六而止殆未免不愁冻杀之诮也 其六","f":"五言绝句","c":["背荫常先积，当明竟早消。","草衰犹秀色，柳悴亦长条。"]},{"t":"连雪不已复作绝句咏之及六而止殆未免不愁冻杀之诮也 其三","f":"五言绝句","c":["勿谓虚明质，能成积厌威。","由轻终及重，至著本从微。"]},{"t":"连雪不已复作绝句咏之及六而止殆未免不愁冻杀之诮也 其一","f":"五言绝句","c":["粲粲初投米，飘飘旋落花。","巷深迷吠犬，林合误归鸦。"]},{"t":"闷坐 其一","f":"七言绝句","c":["天气欲阴还欲晴，病多愁绝两关情。","梅花已是飘零尽，底事春风恨未平。"]},{"t":"闷坐 其二","f":"七言绝句","c":["天气欲晴还欲阴，强扶头起更岑岑。","睡魔欲遣茶料理，政恐蔬肠不易禁。"]},{"t":"冽泉","f":"五言绝句","c":["名士每名泉，一瓢宁取贤。","道行期及物，为涧定为川。"]},{"t":"到江口寺","f":"五言绝句","c":["已绝朱林渡，还瞻白塔擎。","欲从微径陟，复命小舟横。"]},{"t":"卓文君","f":"七言绝句","c":["成都共逸为琴心，岂不尝闻赋丽淫。","重聘茂陵今已晚，不须多赋白头吟。"]},{"t":"夜过王兆明","f":"七言绝句","c":["门外春风吹倒人，过门宁惜滞车轮。","君能劝我杯中物，我亦挥君壁上尘。"]},{"t":"夜作绝句三首 其三","f":"七言绝句","c":["高下钟声一听闻，林梢落月乱纷纷。","忽来眼底诗无数，颇念高人与细分。"]},{"t":"夜作绝句三首 其二","f":"七言绝句","c":["月明入户白于霜，林影当檐耸若翔。","睡味不应如许好，不来吟咏答寒螀。"]},{"t":"夜作绝句三首 其一","f":"七言绝句","c":["秋入吟窗夜气清，旧书虽老眼犹明。","悠悠行李空长铗，落落功名负短檠。"]},{"t":"夜坐读书闻瓶梅之香口占五绝 其一","f":"七言绝句","c":["客去门扃未作眠，续灯添火了残编。","此时孤绝谁相与，能送幽香亦可怜。"]},{"t":"夜坐读书闻瓶梅之香口占五绝 其二","f":"七言绝句","c":["非风非月自腾香，我亦何心适与当。","此味绝佳谁得解，顾须攀折走林塘。"]},{"t":"夜坐读书闻瓶梅之香口占五绝 其四","f":"七言绝句","c":["身落江南不自悲，正欣梅也可供诗。","纷纷桃李胡为者，政似当年蔡克儿。"]},{"t":"夜坐读书闻瓶梅之香口占五绝 其三","f":"七言绝句","c":["旧说春寒花较迟，况今冰雪已逾时。","一枝借得书窗暖，未许游蜂戏蝶知。"]},{"t":"夜坐读书闻瓶梅之香口占五绝 其五","f":"七言绝句","c":["一从丛桂落秋风，佳处长孤阿堵中。","及至梅花又冰雪，一枝虽少与多同。"]},{"t":"夜赋","f":"七言绝句","c":["雨挟松声落枕边，道人巾屦极萧然。","忽思旧宿庐山寺，曾听悬崖瀑布泉。"]},{"t":"奉呈何叔信魏昭甫三首 其三","f":"七言绝句","c":["春风大属野樱朱，树树相望绮不如。","却忆山家篱堑畔，十分春日付谁渠。"]},{"t":"奉呈何叔信魏昭甫三首 其二","f":"七言绝句","c":["梅花寂寞已飞仙，一夜春催杏欲然。","老眼看花愁欲眩，却怜草色静芊芊。"]},{"t":"奉呈何叔信魏昭甫三首 其一","f":"七言绝句","c":["寒厅寂寞不知春，登眺招要藉所亲。","始谓姑倾一杯酒，已焉颠倒白纶巾。"]},{"t":"奉寄斯远兼属文鼎处州子永提属五首 其五","f":"七言绝句","c":["闻道当年五色裘，飘然又入帝王州。","烦君一为问行李，早晚遣诗相报投。"]},{"t":"奉寄斯远兼属文鼎处州子永提属五首 其四","f":"七言绝句","c":["几向馀干觅介庵，骑鲸已去不容骖。","流风付与南池主，何日约君相就谈。"]},{"t":"奉寄斯远兼属文鼎处州子永提属五首 其三","f":"七言绝句","c":["两贤堂下竹参天，雨后涓涓陆子泉。","耆书难忘是曾吕，逸遗更取孟郊篇。"]},{"t":"奉寄斯远兼属文鼎处州子永提属五首 其二","f":"七言绝句","c":["水南佳处说吾州，塔庙相高竹树幽。","落尽梅花雨方暗，垫巾无藉一来游。"]},{"t":"奉寄斯远兼属文鼎处州子永提属五首 其一","f":"七言绝句","c":["吟诗日日数梅花，梅向飘零我返家。","尚有北枝堪点检，君舟已泊岸头沙。"]},{"t":"奉简在伯四首 其四","f":"七言绝句","c":["落日馀霞已自奇，况于人静月明时。","重城著我非无意，前遣先生独赋诗。"]},{"t":"奉简在伯四首 其三","f":"七言绝句","c":["书中旧学来禽帖，今日蛮州得饫尝。","要与先生共咀嚼，更将煮蜜助甘香。"]},{"t":"奉简在伯四首 其二","f":"七言绝句","c":["先生自合饮官壶，野老端宜满眼酤。","白酒酿成聊送汝，未知湿沫与江湖。"]},{"t":"奉简在伯四首 其一","f":"七言绝句","c":["渊明种秫有公田，郑老时时得酒钱。","笑我作官浑乏此，自炊斗酒慰馋涎。"]},{"t":"奉简钦止兼忆斯远 其一","f":"七言绝句","c":["前日丛篁苦蔽溪，祇今檐与四山齐。","裴回有句不能吐，要与乘凉一杖藜。"]},{"t":"奉简钦止兼忆斯远 其二","f":"七言绝句","c":["阿连闻说有归期，准拟俱来赋此诗。","已是欲行还小住，纵令频合故伤离。"]},{"t":"姑苏道中","f":"七言绝句","c":["麦浪摇波柳映津，吴乡春色见今晨。","欲将何以慰无赖，一酌浊醪如有神。"]},{"t":"季永和诗索酒用韵送酒二首 其二","f":"七言绝句","c":["我贫无酒为君欢，渴梦相从碾凤团。","薄暮白衣才有馈，试令分减愧酸寒。"]},{"t":"季永和诗索酒用韵送酒二首 其一","f":"七言绝句","c":["珍重平生书五车，不妨有子更持家。","小閒便欲巾车去，只欲论文非看花。"]},{"t":"孤雁三首 其三","f":"七言绝句","c":["孤雁哀哀叫晚洲，水长山远政悠悠。","凶年未必稻粱足，巧中更防罹缴忧。"]},{"t":"孤雁三首 其二","f":"七言绝句","c":["孤雁哀哀叫晚云，半年为客叹离群。","丁东幽佩别来久，断续清砧远不闻。"]},{"t":"孤雁三首 其一","f":"七言绝句","c":["孤雁哀哀叫晓霜，客衾如水待天光。","不缘杜宇催归去，未信寒猿解断肠。"]},{"t":"宜春道中赠邢公昭二首 其二","f":"七言绝句","c":["问君家在离骚国，句里应含兰芷香。","邂逅宜春须小住，要期倾倒锦为囊。"]},{"t":"宜春道中赠邢公昭二首 其一","f":"七言绝句","c":["清江台上读君诗，颇欲相从慰所思。","何意昌山夜止宿，忽成风雨对床期。"]},{"t":"宝气亭三首 其三","f":"七言绝句","c":["徐家笔力见南唐，今代更推江夏黄。","屹立二碑端不朽，未输滕阁擅三王。"]},{"t":"宝气亭三首 其二","f":"七言绝句","c":["谁道剑池今已荒，有时光怪此何祥。","平生自省惭多识，曷日乞灵亲炷香。"]},{"t":"宝气亭三首 其一","f":"七言绝句","c":["西下扁舟浩所经，暂梯堤石上津亭。","偶从长老询遗迹，说道神游尚炳灵。"]},{"t":"实相书院","f":"七言绝句","c":["已矣骑鲸去不回，怅然犹咏早归来。","空馀旧日读书地，水绕山围似钓台。"]},{"t":"帖永新韩主簿","f":"七言绝句","c":["韩君惠我涪翁帖，三世风流不在兹。","诸老当年会临汝，更须多有未传诗。"]},{"t":"帖俞王诸君求笔","f":"七言绝句","c":["颜公笔法有家法，豪锥料得皆千金。","闻道分张遍亲友，可能乞我助呻吟。"]},{"t":"帖耆英","f":"七言绝句","c":["朝来霰雪遽如许，忍冻髯曾应屡哦。","急送饼芽并致炭，助君灰里拨阴何。"]},{"t":"往时","f":"七言绝句","c":["往时听说严州水，试向经行觅旧痕。","尚有浮槎栖古木，可怜万壑势并吞。"]},{"t":"招仲威不至反辱惠梨","f":"七言绝句","c":["屡废招呼定可人，岂嫌昏暮叩门频。","不来醉我倾家酿，反更分渠饤坐珍。"]},{"t":"招在伯","f":"七言绝句","c":["忽忽重阳今一月，菊花数朵见城根。","前诗有约能从否，不厌张罗幸过门。"]},{"t":"孙子进惠笔乃周寿玉簪样试用其一已作秃翁犹耐驱使成绝句二首异日当寄子进昆仲 其一","f":"七言绝句","c":["遂初赋就笔馀铓，赠我蒙探古锦囊。","耐久固殊流俗败，含情浑似故人长。"]},{"t":"松原山行七绝 其一","f":"七言绝句","c":["雨势崩腾略未休，涧冲溪恶使人愁。","那知今日松原路，拄杖挑包得自由。"]},{"t":"松原山行七绝 其七","f":"七言绝句","c":["一日周遭度九溪，快侬双脚净无泥。","真同落落石为枕，宁愧区区沙筑堤。"]},{"t":"松原山行七绝 其四","f":"七言绝句","c":["雨后浮云更拥山，须臾已作太空还。","了然悟得渊明意，投绂归来径掩关。"]},{"t":"松原山行七绝 其二","f":"七言绝句","c":["莫道松原路不通，担肩樵斧往来同。","老夫自是山中友，要涉崎岖尽日中。"]},{"t":"松原山行七绝 其三","f":"七言绝句","c":["乌噪猿号古树丛，乱青参倚更撑空。","悠然到处皆诗本，须信山行不负公。"]},{"t":"松原山行七绝 其六","f":"七言绝句","c":["涉水穿云殊好在，自知元是个中人。","何时粗毕尚平志，衡岳匡庐收此身。"]},{"t":"松原山行七绝 其五","f":"七言绝句","c":["电激雷奔是处闻，绿周青绕四无分。","哦诗几侧风前帽，纵目閒看雨后云。"]},{"t":"枕上","f":"七言绝句","c":["道人急打五更钟，窗外悲风正吼松。","归梦不须惊久客，骤寒便欲作初冬。"]},{"t":"林湘乡出其先人诗卷题其后二首 其二","f":"七言绝句","c":["松陵我亦屡曾经，几欲张帆过洞庭。","愿借此诗传善本，教儿诵读醉时听。"]},{"t":"林湘乡出其先人诗卷题其后二首 其一","f":"七言绝句","c":["知公苦急簿书仍，留我閒窗语夜灯。","更出此诗令细读，今宵有梦到松陵。"]},{"t":"泊舟西村见居民云数里间有梅访之殊未花","f":"七言绝句","c":["漠漠烟村四五家，水清霜落路平沙。","我来欲问梅消息，地冷年年未放花。"]},{"t":"知府提举访求前守凌公遗迹忽于庭庑雨压复壁中得公所题诗赋六绝句 其一","f":"七言绝句","c":["辰人只识凌刑部，不识尚书晚岁官。","晚岁功名益堪纪，辰人不识坐荒寒。"]},{"t":"知府提举访求前守凌公遗迹忽于庭庑雨压复壁中得公所题诗赋六绝句 其二","f":"七言绝句","c":["使君剖竹继先贤，四十于今又六年。","每恨无从考遗事，但凭亭槛览山川。"]},{"t":"知府提举访求前守凌公遗迹忽于庭庑雨压复壁中得公所题诗赋六绝句 其五","f":"七言绝句","c":["檐浅终防剥蚀灾，好移深奥示将来。","更须刻石行于世，公道只今方大开。"]},{"t":"知府提举访求前守凌公遗迹忽于庭庑雨压复壁中得公所题诗赋六绝句 其四","f":"七言绝句","c":["故相曾兴告讦风，一时多坐语言中。","乃知复壁遮防意，是谓知公亦爱公。"]},{"t":"知府提举访求前守凌公遗迹忽于庭庑雨压复壁中得公所题诗赋六绝句 其六","f":"七言绝句","c":["郡斋新刻总珍藏，得此遗踪益有光。","再拜从公乞馀本，归赍不复恨空囊。"]},{"t":"八月八日发潭州后得绝句四十首 其四十","f":"七言绝句","c":["终朝未厌哭滩声，归近何妨细作程。","送尽鹅湖青一带，灵山已复远相迎。"]},{"t":"经旬不作诗今日霜晴可喜问梅沈园得两绝句此坡所谓痼疾逢虾蟹也 其一","f":"七言绝句","c":["自从篱菊报香衰，便说南枝与北枝。","底事频来问消息，山翁近日绝无诗。"]},{"t":"经旬不作诗今日霜晴可喜问梅沈园得两绝句此坡所谓痼疾逢虾蟹也 其二","f":"七言绝句","c":["莫问今年与去年，祇应贫病两依然。","故人满眼今谁在，且赋梅花第一篇。"]},{"t":"经孺子亭观龙井","f":"七言绝句","c":["寒泉百尺几秋春，祠祷流传信若神。","何事古先殊昧此，为霖顾取筑岩人。"]},{"t":"范参政自建康得资政宫祠六诗寄呈 其六","f":"七言绝句","c":["我梦石湖堂上书，烟云鸥鸟不关渠。","奥篇隐帙诚难了，辞愿一鸱开锁鱼。"]},{"t":"范参政自建康得资政宫祠六诗寄呈 其一","f":"七言绝句","c":["闻道石湖天下奇，城南未数阆州稀。","江山胜处世或有，祗欠若人相发挥。"]},{"t":"范参政自建康得资政宫祠六诗寄呈 其三","f":"七言绝句","c":["出处如公亦甚都，不携西子不思鲈。","三高异日当为四，不见方严与范俱。"]},{"t":"范参政自建康得资政宫祠六诗寄呈 其四","f":"七言绝句","c":["一再将书托置邮，渺然殊未亦湛浮。","平生愿识才能见，别去于今岁又周。"]},{"t":"范参政自建康得资政宫祠六诗寄呈 其五","f":"七言绝句","c":["风月沧浪自逐臣，烟波甫里亦遗民。","未闻官号大学士，辞逊雍容得退身。"]},{"t":"范参政自建康得资政宫祠六诗寄呈 其二","f":"七言绝句","c":["细思不是乞身难，政为贫贤不放閒。","奏疏比闻频叩阙，诏恩今见许还山。"]},{"t":"诗一首","f":"七言绝句","c":["学语浑似学参禅，要保心传与耳传。","秋菊春兰宁易地，清风明月本同天。"]},{"t":"郊居晚行呈章令四首 其四","f":"七言绝句","c":["渊明薪水忧儿子，玉川送米烦邻僧。","我今穷状不可道，减忧得米忧年登。"]},{"t":"郊居晚行呈章令四首 其三","f":"七言绝句","c":["人言乐岁好催科，吾今方知自拊摩。","要识田家略无事，杀鸡为黍自相过。"]},{"t":"郊居晚行呈章令四首 其二","f":"七言绝句","c":["早禾打谷归高廪，槁秸堆场尚若云。","目见田庐无此比，劝耕知自令君勤。"]},{"t":"郊居晚行呈章令四首 其一","f":"七言绝句","c":["斜阳渺渺下前陂，牛自安眠儿得嬉。","行过中林却回顾，眼边依约有新诗。"]},{"t":"郑仲理送行六首 其六","f":"七言绝句","c":["病著形骸冷更慵，短檠宁复有新工。","异时邂逅相逢处，应叹依然旧阿蒙。"]},{"t":"郑仲理送行六首 其五","f":"七言绝句","c":["渺然一棹去何之，满目新诗与旧诗。","细读赠章多好语，顾怜追和却无奇。"]},{"t":"郑仲理送行六首 其四","f":"七言绝句","c":["溪山廓廓眼增明，鸥鹭依依旧有盟。","所恨登高临赋处，却嗟我友不同行。"]},{"t":"郑仲理送行六首 其三","f":"七言绝句","c":["坐上每怀歌慷慨，杯行岂复计寻常。","我知不隔清风面，君想未忘明月章。"]},{"t":"郑仲理送行六首 其二","f":"七言绝句","c":["几度拿舟湘水西，风雩亭下咏而归。","驩然诸友相忘意，不叩仙坛与佛扉。"]},{"t":"郑仲理送行六首 其一","f":"七言绝句","c":["周郎三复似南容，君亦因之师友同。","岂待湖南始相识，闻风元自大江东。"]},{"t":"金凤花","f":"五言绝句","c":["既知梧留凤，宁令凤在笯。","胡为五色羽，散作一庭花。"]},{"t":"钓矶 其二","f":"五言绝句","c":["乐是烟波好，宁须竿线劳。","功高殊钓渭，意适似游濠。"]},{"t":"雨中","f":"七言绝句","c":["四月梅黄雨易成，夜来犹是十分晴。","吴山越岭浑遮尽，惟见江流面面平。"]},{"t":"雨中同曹尉王儦岩二首 其二","f":"七言绝句","c":["骤雨翻空何自来，飞流溅沫洗崔嵬。","要题短句书奇事，付与曹郎八斗才。"]},{"t":"雨中同曹尉王儦岩二首 其一","f":"七言绝句","c":["旧说吾邦岩谷多，历观无愈此嵯峨。","今朝唤渡仍冲雨，惭愧溪神不我诃。"]},{"t":"雨中夜归闻两儿诵书偶成二绝幸明叔先生同赋以示之 其一","f":"七言绝句","c":["檐雨浪浪欲二更，短檠明火读书声。","忆如汝大政如汝，一事无成今老生。"]},{"t":"雨中夜归闻两儿诵书偶成二绝幸明叔先生同赋以示之 其二","f":"七言绝句","c":["家世无田事笔耕，五车精熟是收成。","穷通有命吾何与，若若多惭短褐荣。"]},{"t":"雨后二绝句 其一","f":"七言绝句","c":["疾风吹雨过前溪，留得馀凉在竹扉。","为我拂床仍置席，今朝梦稳故山归。"]},{"t":"雨后二绝句 其二","f":"七言绝句","c":["竹树翛然亦雨馀，便疑秋已到林居。","恨无新月当霄挂，空遣清风为扫除。"]},{"t":"雨后口占简在伯二首 其二","f":"七言绝句","c":["蕉心待雨慵能展，柳叶非秋间自零。","觅句政资闲草木，荒凉于此只空庭。"]},{"t":"雨后口占简在伯二首 其一","f":"七言绝句","c":["雨小宁论旱可濡，凉生但喜病微苏。","归云返照当年句，落在君家我所无。"]},{"t":"雨后晨起怀斯远 其二","f":"七言绝句","c":["百鸟喧嘲工败眠，静听黄鸟独清圆。","何云丝竹不如肉，佳处政因出自然。"]},{"t":"雨后晨起怀斯远 其一","f":"七言绝句","c":["梦过百花蝴蝶飞，可堪朝暮子规啼。","山中有屋不归去，想见当门碧草齐。"]},{"t":"雨过知津酒正潘元寿皆留饮漫兴绝句","f":"七言绝句","c":["杨柳依依洲渚深，驾言聊尔纵幽寻。","不虞为子登临费，但约新诗好处吟。"]},{"t":"雨游青原山二首 其二","f":"五言绝句","c":["要作山中宿，怅无林下期。","摩挲鲁公字，咀嚼豫章诗。"]},{"t":"雨游青原山二首 其一","f":"五言绝句","c":["松竹青原刹，香灯七祖签。","穷通非所问，风雨暂成淹。"]},{"t":"亭午欲过意复凄然偶引杯酒而沅陵丈送诗适至因走笔成两绝并呈教授兄 其二","f":"七言绝句","c":["寒厅冷日不能暄，杯酒时须手自温。","赖有好诗频送我，能教病眼洗眵昏。"]},{"t":"亭午欲过意复凄然偶引杯酒而沅陵丈送诗适至因走笔成两绝并呈教授兄 其一","f":"七言绝句","c":["梅花玉立知何许，回首江东日暮云。","白发萧萧不归去，顾徵蛮语作参军。"]},{"t":"哀文鼎 其二","f":"七言绝句","c":["海内忘形独汉中，几回日暮忆江东。","不惟吾子伤形影，我亦交游不太穷。"]},{"t":"哀文鼎 其三","f":"七言绝句","c":["频年哭友不胜哀，不待年侵老自来。","未保此身长健在，与君茅屋卧苍苔。"]},{"t":"城下道中二首 其二","f":"七言绝句","c":["溪上桥危亭亦高，柳阴直下有鱼舠。","夜来雨足洪初涨，突岸冲矶声怒号。"]},{"t":"城下道中二首 其一","f":"七言绝句","c":["瓦室人家茅屋边，瓦囷亦与草囷连。","池塘过雨尚浮浊，杨柳新栽已带烟。"]},{"t":"复游东湖题卢石","f":"七言绝句","c":["云中不改苍苍色，春后宁同濯濯姿。","欲为渠侬下转语，笔无潮力强题诗。"]},{"t":"将至辰州走笔寄在伯教授二首 其二","f":"七言绝句","c":["庭前甘菊都开否，记得去年同把觞。","相逢劳苦定愁绝，我哭途穷君悼亡。"]},{"t":"将至辰州走笔寄在伯教授二首 其一","f":"七言绝句","c":["去年十月君行此，今岁兹时我继君。","黄花赤叶虽如昨，所恨诗坛欠策勋。"]},{"t":"将至信州呈季承","f":"七言绝句","c":["行役将穷兴未穷，百篇酬唱与君同。","人间此乐胡能再，何处江西更古融。"]},{"t":"将至溧阳示宗父","f":"七言绝句","c":["玉聚梅花殊未开，不妨烟雨雪飞来。","仆夫怪我行何速，要趁佳时同一杯。"]},{"t":"将谒延庐州行至板桥忽病而止复还建康以五诗寄之 其二","f":"七言绝句","c":["数载炎州不惯寒，并江已怯瘦栾栾。","旧识淮南今更老，绝知于此亦良难。"]},{"t":"将谒延庐州行至板桥忽病而止复还建康以五诗寄之 其一","f":"七言绝句","c":["驱车晓蹋板桥霜，头为岑岑势莫当。","颇念索衣为禦具，可怜行李祇空囊。"]},{"t":"将谒延庐州行至板桥忽病而止复还建康以五诗寄之 其五","f":"七言绝句","c":["甑倒悬知解死饥，故殊道路永为嗤。","我今恃有彭州牧，二柄宁当复误疑。"]},{"t":"将谒延庐州行至板桥忽病而止复还建康以五诗寄之 其四","f":"七言绝句","c":["袖诗已失天津面，路返新林病岂期。","一见可能难若此，定繇或使岂人为。"]},{"t":"将谒延庐州行至板桥忽病而止复还建康以五诗寄之 其三","f":"七言绝句","c":["欲前复却路成迷，冷日悲风为惨悽。","以口语心千万种，可能一一见书题。"]},{"t":"幽兰坡","f":"五言绝句","c":["斗坡能曲折，乱石故峥嵘。","篁竹几成蔽，幽兰何处生。"]},{"t":"彦博周伯休来","f":"七言绝句","c":["剥啄能来两玉人，饭蔬糜粟共吾贫。","更欣两子知人意，为作萧萧破暑新。"]},{"t":"待斯远不至","f":"七言绝句","c":["灵溪寺下灵溪渡，跋马欲前还又回。","准拟故人能会宿，不知何事不成来。"]},{"t":"拜朱仲卿墓","f":"七言绝句","c":["西都何啻万公卿，纸上空能阅姓名。","桐乡啬夫少吏尔，墓木梢云独未平。"]},{"t":"春日杂言十一首 其十一","f":"七言绝句","c":["渺渺春山啼杜鹃，开花解使碧山然。","韩诗李赋纷难考，犹喜知名向谪仙。"]},{"t":"春日杂言十一首 其十","f":"七言绝句","c":["燕子日长宜读书，若为病思每欺余。","形骸筋力今如此，惭愧丁年不荷锄。"]},{"t":"春日杂言十一首 其九","f":"七言绝句","c":["春风吹绿绿成阴，新有黄鹂度好音。","我政卷书成坐睡，恍然疑是拂瑶琴。"]},{"t":"春日杂言十一首 其七","f":"七言绝句","c":["落叶疏疏似雨鸣，莫疑春晚有秋声。","抽条易叶年年事，看取一番新绿成。"]},{"t":"春日杂言十一首 其六","f":"七言绝句","c":["旧时曾咏木兰幽，旧藁飘零莫自收。","老境不妨花固发，人今白尽十分头。"]},{"t":"春日杂言十一首 其五","f":"七言绝句","c":["买得荒园近坞居，但供樵牧废犁锄。","漫营篱落今将合，犹恨人工乏剩馀。"]},{"t":"春日杂言十一首 其四","f":"七言绝句","c":["晚欣斜日照茅檐，意谓新晴已可占。","雨脚晓收云更合，阳乌将出尚窥觇。"]},{"t":"春日杂言十一首 其三","f":"七言绝句","c":["寒多草亦未抽芽，漫说春今一半加。","试向小园閒点检，忽逢一树木瓜花。"]},{"t":"春日杂言十一首 其二","f":"七言绝句","c":["山寒花事自迟迟，归至况当梅谢时。","祇有山樱能照眼，属遭风雨又离披。"]},{"t":"春日杂言十一首 其一","f":"七言绝句","c":["兰也结根幽且深，若为容易出山林。","定知亦以香为累，不尔人于何处寻。"]},{"t":"春日杂言十一首 其八","f":"七言绝句","c":["山中寂寞少花枝，过尽春风病不知。","未分春归便无迹，陶瓶聊复浸酴醾。"]},{"t":"昨日","f":"七言绝句","c":["昨日张帆著翼飞，今朝风送蹇驴骑。","吴淞山水夙所爱，得意还教多赋诗。"]},{"t":"昭礼在虞山与予分路昭礼举王光远在庐山别周元翁明朝山北山南路各自逢人说胜游之句昭礼用此意作诗因亦次韵二首 其二","f":"七言绝句","c":["人物君非第一流，周南底事叹淹留。","清名所得盖多矣，骑鹤扬州有是不。"]},{"t":"昭礼在虞山与予分路昭礼举王光远在庐山别周元翁明朝山北山南路各自逢人说胜游之句昭礼用此意作诗因亦次韵二首 其一","f":"七言绝句","c":["昔年挂席过江州，曾为庐山尽日留。","断句得君相举似，夜窗应复梦成游。"]},{"t":"是夕有怀斯远二首 其二","f":"七言绝句","c":["塞郭衣冠匪乏人，步能送我独情真。","几思觅句相料理，风月溪山不易亲。"]},{"t":"是夕有怀斯远二首 其一","f":"七言绝句","c":["沙如星射水流光，忆著南山步石梁。","秋兴日来知几首，可无南落雁成行。"]},{"t":"是日雨阴殊甚咫尺如隔然","f":"七言绝句","c":["青山咫尺不容看，岂是山灵意有难。","定自知侬坐诗瘦，故令空雾作漫漫。"]},{"t":"柳","f":"七言绝句","c":["松菊犹存岁晚期，五株柳树复奚为。","风流不在春风日，要看秋风摇落时。"]},{"t":"残梅","f":"七言绝句","c":["片片乾飞已足悲，况堪风雨横相欺。","卒然此恨何由释，倚赖重开有背枝。"]},{"t":"段元衡出示与晦翁九日登紫霄峰诗及手帖并及贾八十兄诗既敬读之得三绝句 其三","f":"七言绝句","c":["季承新寄峤南诗，君亦南游吊楚累。","冰水玉山元自好，蛮烟蜑雨只生悲。"]},{"t":"段元衡出示与晦翁九日登紫霄峰诗及手帖并及贾八十兄诗既敬读之得三绝句 其二","f":"七言绝句","c":["文章定价如金玉，入手可知高与低。","今代师儒晦庵老，许君先达并江西。"]},{"t":"段元衡出示与晦翁九日登紫霄峰诗及手帖并及贾八十兄诗既敬读之得三绝句 其一","f":"七言绝句","c":["紫霄峰上登高节，想见笑谈宾主间。","我亦于今有遗恨，不随巾屦上南山。"]},{"t":"独行 其三","f":"七言绝句","c":["登山临水送将归，揽涕无从日向微。","水远山高动千里，春风浩浩客吹衣。"]},{"t":"独行 其二","f":"七言绝句","c":["春风浩浩水横波，水远滩长可奈何。","送尽碧云人不见，折兰采若自行歌。"]},{"t":"独行 其一","f":"七言绝句","c":["独行曼曼绕江湄，正是春风日暮时。","折得芳馨无所遗，寄怀空诵碧云诗。"]},{"t":"独行五首 其一","f":"五言绝句","c":["所思终不见，渺渺政愁余。","试向江头钓，怕逢双鲤鱼。"]},{"t":"独树","f":"七言绝句","c":["独树幽花明屋角，顿惊门户有光辉。","向来荒草几埋径，今日行人欲叩扉。"]},{"t":"祝君适中折所居南山岩花二种曰玉梅曰含笑者为况名乃适中自制人鲜知之题五绝以广焉 其一","f":"七言绝句","c":["柯茎全与腊梅同，色洁香幽梅亦通。","以玉谥之真不僣，何须汉赋楚骚中。"]},{"t":"祝君适中折所居南山岩花二种曰玉梅曰含笑者为况名乃适中自制人鲜知之题五绝以广焉 其三","f":"七言绝句","c":["大笑能株小作丛，吐香全似酒微中。","旧观但比山茶白，无此枝头破颗红。"]},{"t":"祝君适中折所居南山岩花二种曰玉梅曰含笑者为况名乃适中自制人鲜知之题五绝以广焉 其五","f":"七言绝句","c":["蜡梅当日过苏黄，名压西川旧海棠。","太息此花终未遇，而余与子漫平章。"]},{"t":"祝君适中折所居南山岩花二种曰玉梅曰含笑者为况名乃适中自制人鲜知之题五绝以广焉 其四","f":"七言绝句","c":["含笑初无巧笑容，未知名字复谁从。","尔今顾有嫣然状，不笑春风却笑冬。"]},{"t":"祝君适中折所居南山岩花二种曰玉梅曰含笑者为况名乃适中自制人鲜知之题五绝以广焉 其二","f":"七言绝句","c":["南山含壁尽阳冈，草木朝朝被宠光。","梅事已居桃李上，尔于梅也更前行。"]},{"t":"祝游子泉刘叔通二家孤寡","f":"五言绝句","c":["贫贱可余置，死生无彼抛。","遗书曾不博，斗粟与枝巢。"]},{"t":"种菊","f":"五言绝句","c":["甘菊移时晚，少陵曾有诗。","落英胡可待，已分阻长饥。"]},{"t":"舣舟龙游","f":"七言绝句","c":["縠波亭下一维舟，小对秋风梳白头。","欲赋新诗欠时体，江河万古叹风流。"]},{"t":"送刘克昌文显二首 其二","f":"七言绝句","c":["柳暗知津君送我，江临快阁我辞君。","君行过我南山塔，为道长怀日暮云。"]},{"t":"送刘克昌文显二首 其一","f":"七言绝句","c":["驿使相看合寄梅，日边消息几时回。","平生所积故已厚，九万不须风更培。"]},{"t":"送芍药与周子开","f":"七言绝句","c":["涉春风雨见花稀，红药开时春已非。","病夫何与知许事，送与缓歌金缕衣。"]},{"t":"送何叔信三首 其三","f":"七言绝句","c":["贵溪亦复谓三山，去我冰溪一水间。","舴艋篷笼不难买，有时乘兴泊鸥湾。"]},{"t":"送何叔信三首 其二","f":"七言绝句","c":["情均骨肉谓尧民，我辈相仍敢不敦。","越人可笑盟车笠，四海要知皆弟昆。"]},{"t":"送何叔信三首 其一","f":"七言绝句","c":["几年惆怅荔枝红，妇荐孙擎寿媪翁。","我亦得归无此乐，弟兄相对小灯笼。"]},{"t":"送陈庆伯三首 其三","f":"七言绝句","c":["君到江南梅正开，折梅称寿亦佳哉。","平安傥遇重湖便，为把新诗写寄来。"]},{"t":"送陈庆伯三首 其二","f":"七言绝句","c":["闻道君行欲转江，江行此路不胜长。","虽然不患无归遗，收拾江山一锦囊。"]},{"t":"送陈庆伯三首 其一","f":"七言绝句","c":["衢信相望百里间，从来疏阔若为颜。","与君既亲亦有故，他日当期数往还。"]},{"t":"送前始兴谢令二首 其二","f":"七言绝句","c":["江南梅事已吹残，想见岭南青作团。","邂逅诗成肯相寄，憧憧驿使入长安。"]},{"t":"送前始兴谢令二首 其一","f":"七言绝句","c":["维舟畴昔见南昌，杯酒还能共宝坊。","我自解君庾岭意，清朝使者得梁扬。"]},{"t":"送笋与胡仲威","f":"五言绝句","c":["掘我窗前笋，与君充煮煨。","槎牙勿多弃，聊用敌崔嵬。"]},{"t":"送智门祥师便呈斯远兄","f":"七言绝句","c":["寺后溪亭我所开，春风应已长莓苔。","南州高士如临赋，为把新诗写寄来。"]},{"t":"送曾季永赴道州永明尉三首 其三","f":"七言绝句","c":["忆昔曾闻谪道州，每于文字见曾游。","白鹅寺近永明县，试觅记碑还在不。"]},{"t":"送曾季永赴道州永明尉三首 其二","f":"七言绝句","c":["去年洞贼惊郴道，闻说居民甚可悲。","太守只今谁漫叟，舂陵示吏两篇诗。"]},{"t":"送曾季永赴道州永明尉三首 其一","f":"七言绝句","c":["西昌阀阅推曾氏，夫子家居仍旧溪。","我政结亭临水际，君行谁与共攀跻。"]},{"t":"送曾耆英持胡端殿书谒张袁州四首 其四","f":"七言绝句","c":["我闻诸侯一朝享，可作寒士终年储。","张家衣被及四海，不但一州歌裤襦。"]},{"t":"送曾耆英持胡端殿书谒张袁州四首 其三","f":"七言绝句","c":["袁州张侯吾所闻，政事不减大冯君。","如云已召符节令，行矣君其无惮勤。"]},{"t":"送曾耆英持胡端殿书谒张袁州四首 其二","f":"七言绝句","c":["君知龙门不易陟，颇欲乞书南郡胡。","一幅斜行半年得，费君趼足几工夫。"]},{"t":"送曾耆英持胡端殿书谒张袁州四首 其一","f":"七言绝句","c":["是家风节在峨岷，仍见诸孙文字贫。","闻道江南有蜀士，不辞奔走犯萧晨。"]},{"t":"送新茶与俞尉","f":"七言绝句","c":["山居每啜社前香，及是清明茶政尝。","叹我白头无母遗，一杯持与供高堂。"]},{"t":"送蕨与成父","f":"七言绝句","c":["道人惠我南山蕨，颇带斋厨法酱香。","闻道城中少蔬供，急令健步走倾筐。"]},{"t":"重午日摘枇杷荐酒因成两绝句 其一","f":"五言绝句","c":["已载相如赋，还披杜老诗。","团团自长叶，佳实欠累累。"]},{"t":"重午日摘枇杷荐酒因成两绝句 其二","f":"五言绝句","c":["蜀酒能袪虑，昌阳解引年。","楚君为楚节，湘客念湘船。"]},{"t":"重过东湖二首 其二","f":"七言绝句","c":["敝车羸服豫章城，几向东湖得细行。","不但屡来人似识，白鸥相惯亦忘惊。"]},{"t":"重过东湖二首 其一","f":"七言绝句","c":["忆昨追凉孺子亭，再来荷柳竞凋零。","试当止水凭栏看，我亦疏髯白数茎。"]},{"t":"重阳甫近菊殊未花而木犀再开遂成一绝","f":"七言绝句","c":["今年为况添萧瑟，无菊能酬九日杯。","天意似怜愁欲绝，故令岩桂为重开。"]},{"t":"重送处州斯远三首 其三","f":"七言绝句","c":["文字投盟不计官，古人能尔在今难。","使君于此自为德，我辈因留后代看。"]},{"t":"重送处州斯远三首 其二","f":"七言绝句","c":["万木苍苍古钓台，白云楼观隔溪开。","赋成赤壁后无对，好与驱从笔下来。"]},{"t":"重送处州斯远三首 其一","f":"七言绝句","c":["登临长病独成吟，连壁相依照映深。","寄谢青山无偃蹇，好听绝唱乱清音。"]},{"t":"闺怨四首 其一","f":"五言绝句","c":["辞少不尽意，辞多还尽纸。","纸尽意无穷，相思似流水。"]},{"t":"闻杜鹘","f":"七言绝句","c":["山禽劝我不如归，知我西游有定期。","若使藜羹足供给，衡门之乐肯轻辞。"]},{"t":"闻曾裘父丈亡追用前韵寄审知二首 其二","f":"七言绝句","c":["钓船颇欲佐涪翁，当世知余莫取容。","谁料传亡终欠识，但同物论惜元龙。"]},{"t":"闻曾裘父丈亡追用前韵寄审知二首 其一","f":"七言绝句","c":["凉风不审意如何，逝日能言客有过。","师友渊源说宗派，要君文字饱研磨。"]},{"t":"闻禽","f":"七言绝句","c":["天公端以鸟鸣春，百族喧喧晓更频。","最是客中贪听尔，弄晴忧湿似关人。"]},{"t":"闻蛙","f":"五言绝句","c":["惊蛰已数日，闻蛙初此时。","能知喜风月，不必问官私。"]},{"t":"食枸杞","f":"七言绝句","c":["谁道春风未发生，杞苗试摘已堪羹。","莫将口腹为人累，竹瘦殊胜豕腹亨。"]},{"t":"倪秀才惠橄榄二首 其二","f":"七言绝句","c":["直道堪嗟故不容，更持谏味欲谁从。","昏昏度日惟贪睡，茗椀聊充午后供。"]},{"t":"倪秀才惠橄榄二首 其一","f":"七言绝句","c":["故怜枉作近南官，南果何曾上客盘。","橄榄忽来蕉作裹，欣然却作近乡看。"]},{"t":"唐兴寺怀孟东野","f":"七言绝句","c":["蔷薇虽是后人栽，一度春风一度开。","绝怜东野归何处，无复花前把酒来。"]},{"t":"徐君季纯常德教授廨中名一室曰如舟取东坡为宛丘诗而云也过之欲为赋诗意到辄书故不免杂出君居龙游故有盈川之句诗臞云者盖初未识而为簿公曾元之所言也凡五首 其五","f":"七言绝句","c":["满面风埃霜鬓须，何如相识谓诗臞。","君行学省得佳士，我乃烟波称钓徒。"]},{"t":"徐君季纯常德教授廨中名一室曰如舟取东坡为宛丘诗而云也过之欲为赋诗意到辄书故不免杂出君居龙游故有盈川之句诗臞云者盖初未识而为簿公曾元之所言也凡五首 其四","f":"七言绝句","c":["欲为如舟一赋诗，如舟无楫更无维。","泛乎不系知何处，当有长风破浪时。"]},{"t":"徐君季纯常德教授廨中名一室曰如舟取东坡为宛丘诗而云也过之欲为赋诗意到辄书故不免杂出君居龙游故有盈川之句诗臞云者盖初未识而为簿公曾元之所言也凡五首 其三","f":"七言绝句","c":["莫嫌学舍小如舟，容得平南酒拍浮。","试问梦为蝴蝶去，何如万里没轻鸥。"]},{"t":"徐君季纯常德教授廨中名一室曰如舟取东坡为宛丘诗而云也过之欲为赋诗意到辄书故不免杂出君居龙游故有盈川之句诗臞云者盖初未识而为簿公曾元之所言也凡五首 其二","f":"七言绝句","c":["我本江湖一钓竿，直钩不幸得鱼难。","虽然尚有扁舟念，一到君斋作是观。"]},{"t":"徐君季纯常德教授廨中名一室曰如舟取东坡为宛丘诗而云也过之欲为赋诗意到辄书故不免杂出君居龙游故有盈川之句诗臞云者盖初未识而为簿公曾元之所言也凡五首 其一","f":"七言绝句","c":["知君雅趣在沧洲，游戏名斋亦以舟。","旧识盈川川上路，几时乘月下严州。"]},{"t":"晏斋余自名也故常以榜自随乃以名厅事之东偏厅之后旧有一室面对竹余山居富此物亦以竹隐名对此竹而有思于山中故以思隐名之思隐之东又辟屋丈许连以为斋乞名于张君伯永为名曰容斋并作三绝志其事焉 其一","f":"七言绝句","c":["以晏名斋惧不安，居閒从仕莫殊看。","葱羹麦饭自可饱，惟去不须如井丹。"]},{"t":"晏斋余自名也故常以榜自随乃以名厅事之东偏厅之后旧有一室面对竹余山居富此物亦以竹隐名对此竹而有思于山中故以思隐名之思隐之东又辟屋丈许连以为斋乞名于张君伯永为名曰容斋并作三绝志其事焉 其三","f":"七言绝句","c":["容膝徒知取易安，容君数百又何宽。","若人问我名斋义，两语从渠作么看。"]},{"t":"晏斋余自名也故常以榜自随乃以名厅事之东偏厅之后旧有一室面对竹余山居富此物亦以竹隐名对此竹而有思于山中故以思隐名之思隐之东又辟屋丈许连以为斋乞名于张君伯永为名曰容斋并作三绝志其事焉 其二","f":"七言绝句","c":["此地何因著此君，藉之除扫簿书纷。","山中为尔曾成隐，回首悠悠空暮云。"]},{"t":"晒蓑亭 其三","f":"七言绝句","c":["爱竹旧时王子猷，造门忘主见风流。","如君不但无锁钥，更向山阴具小舟。"]},{"t":"晒蓑亭 其二","f":"七言绝句","c":["冰玉溪山近与邻，我舟来往故成频。","眼边风物浑如旧，只欠行吟采若人。"]},{"t":"晒蓑亭 其一","f":"七言绝句","c":["欲买宽闲结钓庵，一竿投老寄江南。","是州亦在经营里，先手落君无可谈。"]},{"t":"晓登快阁 其一","f":"七言绝句","c":["庭中但觉木摇落，江上始知秋气高。","不待月明飞镜夜，此时自可数秋毫。"]},{"t":"晓登快阁 其二","f":"七言绝句","c":["木落千山秋又深，病无眼力怕登临。","所须一雨添清涨，送我归舟返故林。"]},{"t":"涂中每息必索砚笔抄诗作廿八字","f":"七言绝句","c":["望望青山乱作堆，行行身到白云隈。","偶逢道店聊休歇，又被匆匆诗债催。"]},{"t":"涧铺岭道中四首 其四","f":"五言绝句","c":["钜竹差差合，青杉袅袅长。","人多表池槛，此乃亘山冈。"]},{"t":"涧铺岭道中四首 其三","f":"五言绝句","c":["芋亩疑如蜀，山田更似闽。","祇看无废地，宁复有閒民。"]},{"t":"涧铺岭道中四首 其二","f":"五言绝句","c":["岭路萦纡合，泉流诘曲通。","田毛无岁旱，山课与耕同。"]},{"t":"涧铺岭道中四首 其一","f":"五言绝句","c":["近岫披晴雾，遥山纵雨云。","皑皑疑雪积，莽莽若江分。"]},{"t":"瓶梅","f":"七言绝句","c":["纸窗见月影横斜，不是桃花与李花。","一夜清吟忘客睡，祇愁到晓鬓双华。"]},{"t":"病中","f":"七言绝句","c":["风树萧萧雨若筛，间飘黄叶挂蛛丝。","虫号亡赖更满耳，况是病夫新起时。"]},{"t":"离家","f":"七言绝句","c":["饥来驱我去何之，束担垂行却住时。","幼女亦知离别感，挽衣端欲问归期。"]},{"t":"荼蘼洞","f":"五言绝句","c":["春花苦无阴，况与花俱秀。","好在月明中，仰攀仍落嗅。"]},{"t":"蚕妇","f":"七言绝句","c":["火蚕较早冷蚕迟，晏饭忘眠敢叹疲。","缲车响罢促机杼，盖体到头无一丝。"]},{"t":"读二传作","f":"七言绝句","c":["长卿召问自拘监，子云待诏因王音。","得官甚薄不救辱，作赋可怜空苦心。"]},{"t":"读介庵集题其上","f":"七言绝句","c":["风前旧揖青绮帔，老去今披古锦囊。","千古未忘图像拜，也知风骨类文章。"]},{"t":"读公择箧中徐季益孙子进昆仲诗有怀其人因以题赠四首 其四","f":"七言绝句","c":["我贫犹说在有贫，羁旅如君更感人。","强道诗工能泣鬼，未如钱夥可通神。"]},{"t":"读公择箧中徐季益孙子进昆仲诗有怀其人因以题赠四首 其三","f":"七言绝句","c":["囊有清诗无一钱，夜窗翻倒谩妨眠。","荆溪溪上长回首，不见音书已二年。"]},{"t":"读公择箧中徐季益孙子进昆仲诗有怀其人因以题赠四首 其二","f":"七言绝句","c":["怪渠诗律自江西，曾把文章谒紫微。","今日凄凉亦何甚，异方流转未能归。"]},{"t":"读公择箧中徐季益孙子进昆仲诗有怀其人因以题赠四首 其一","f":"七言绝句","c":["几年禅月閟灵栖，石磴崩摧仅可梯。","谁遣诗人来借住，自应无饭只羹藜。"]},{"t":"读朱先生云谷诗","f":"五言绝句","c":["昔在龙门胜，祇今云谷居。","吾州端不远，曷日从篮舆。"]},{"t":"读谢幼槃集 其一","f":"七言绝句","c":["茗椀不能驱睡魔，漫携诗册向庭柯。","世人祇爱高官职，孰与公家兄弟过。"]},{"t":"读谢幼槃集 其二","f":"七言绝句","c":["自汲清泉除砚垢，树阴微息晚凉初。","个中得意谁知我，笔下忘言我羡渠。"]},{"t":"途中杂题六首 其六","f":"五言绝句","c":["异俗吁成怕，吾身行若何。","略人仍负担，祭鬼更鸣锣。"]},{"t":"途中杂题六首 其五","f":"五言绝句","c":["树合猿啼远，崖荒虎迹新。","寻常惯居者，辛苦恐行人。"]},{"t":"途中杂题六首 其四","f":"五言绝句","c":["下壑疑无地，高崖恐接天。","端殊益州驭，敢尽祖生鞭。"]},{"t":"途中杂题六首 其三","f":"五言绝句","c":["山果秋皆实，山花晚更馨。","鸟飞时暗落，风静或微听。"]},{"t":"途中杂题六首 其二","f":"五言绝句","c":["石有千年藓，崖悬百尺藤。","祗疑云尚合，忽见日初升。"]},{"t":"途中杂题六首 其一","f":"五言绝句","c":["人疲故思息，马倦亦成嘘。","彼政嗟吾役，吾宁陋彼居。"]},{"t":"途中呈明叔","f":"七言绝句","c":["相逢何必道寒温，所过江山合细论。","四体不佳谈舌强，不妨展卷有诗存。"]},{"t":"途中阅曾运使所况文清集得四绝句寄之 其二","f":"七言绝句","c":["旧抄题作茶山集，每恨不多看易穷。","全编敢意落吾手，何自得之从长公。"]},{"t":"途中阅曾运使所况文清集得四绝句寄之 其四","f":"七言绝句","c":["桃源梅岭几成游，天欲昌诗不自由。","一代如公才得此，五溪著我更何尤。"]},{"t":"途中阅曾运使所况文清集得四绝句寄之 其一","f":"七言绝句","c":["玉山冰水是吾家，城郭屡过三姓茶。","满庭修绿谁人种，高节岁寒仍有加。"]},{"t":"途中阅曾运使所况文清集得四绝句寄之 其三","f":"七言绝句","c":["两贤堂下千竿竹，萧散风流政昔时。","何妨乞我一洒扫，不用文移只付诗。"]},{"t":"铁笛亭","f":"五言绝句","c":["怅彼荆榛合，欣公杖履开。","倘非人隐异，何许笛飞来。"]},{"t":"阅韩伯修集示其子二首 其二","f":"七言绝句","c":["诗篇圆熟无凝滞，四六雍容有典型。","请君持上图书府，要与紫微俱杀青。"]},{"t":"阅韩伯修集示其子二首 其一","f":"七言绝句","c":["吏部名高世所尊，一传曾说误金根。","陵阳父子风流胜，政似苏家擅蜀门。"]},{"t":"验漆","f":"五言绝句","c":["好漆清如镜，悬丝似钓钩。","撼动虎斑色，打著有浮沤。"]},{"t":"偶书道店之壁","f":"七言绝句","c":["愁边得酒宁论味，马上成诗不计篇。","不是行人那识此，知音应为一悠然。"]},{"t":"宿竹瓦铺二首 其二","f":"五言绝句","c":["连根煮菜种，带叶■生薪。","琐琐无庸叹，区区愧此身。"]},{"t":"宿竹瓦铺二首 其一","f":"五言绝句","c":["投鞍才近午，置榻已成曛。","岂乏道旁店，恐逢梁上君。"]},{"t":"宿应庵次季承韵","f":"七言绝句","c":["祇思借榻寻僧屋，不悟山行亦已深。","异日重来应记路，断塍穷处转松林。"]},{"t":"宿桐溪湾","f":"七言绝句","c":["近山惨澹连深坞，远水苍茫接暮云。","语似篙师徐系缆，莫教惊动白鸥群。"]},{"t":"寄文叔且问畏知近讯五首 其五","f":"七言绝句","c":["近来周子绝无书，目断西江双鲤鱼。","出处不应违素志，君如得来我归欤。"]},{"t":"寄文叔且问畏知近讯五首 其四","f":"七言绝句","c":["去年犯雪到西湖，眼见梅花玉立孤。","今岁定无牢落叹，君诗清绝似林逋。"]},{"t":"寄文叔且问畏知近讯五首 其三","f":"七言绝句","c":["醉里挥毫君不嗔，平生嗜酒见天真。","离觞曾为黄花满，别日行看梅又新。"]},{"t":"寄文叔且问畏知近讯五首 其二","f":"七言绝句","c":["左手持螯快引杯，诵诗屑屑吐琼瑰。","清游晚上仙林阁，平揖森檐玉万堆。"]},{"t":"寄文叔且问畏知近讯五首 其一","f":"七言绝句","c":["胸中何止五车书，记诵张巡恐不如。","有意词科不难中，掖垣谏省政须渠。"]},{"t":"寄毛伯明李叔器及康叔临二首 其二","f":"七言绝句","c":["忆泛扁舟过洞庭，自嗟垂老见飘零。","只今说著非无为，曾与荀陈聚德星。"]},{"t":"寄毛伯明李叔器及康叔临二首 其一","f":"七言绝句","c":["日日江头闻鼓声，问船云作岳州行。","如闻风便一日尔，我乃终年怀友生。"]},{"t":"寄白云觅茶","f":"七言绝句","c":["忆别白云笋渐长，而今想见出梢墙。","道人寄我不忘我，盍寄茶瓯洗睡肓。"]},{"t":"寄刘凝远峦四首 其四","f":"七言绝句","c":["一生已分阻长饥，轻薄羞随造化儿。","远寄微言作君寿，无盐何敢突西施。"]},{"t":"寄刘凝远峦四首 其三","f":"七言绝句","c":["少陵衣钵在涪翁，传述东莱得正宗。","闻道曾经亲授记，不求印可谁更从。"]},{"t":"寄刘凝远峦四首 其二","f":"七言绝句","c":["曾因下座识元龙，深觊归途得款从。","顾我殊非黄叔度，多君不愧郭林宗。"]},{"t":"寄刘凝远峦四首 其一","f":"七言绝句","c":["旧来人物数诸刘，公更诗名盖几州。","新贵祇今多故旧，先生宁久滞瓜丘。"]},{"t":"寄向伯休且约他日道为芗林之游二首 其二","f":"七言绝句","c":["平生芗林五十咏，何意扁舟其下过。","王郎逸兴非余有，不问主人防怒诃。"]},{"t":"寄向伯休且约他日道为芗林之游二首 其一","f":"七言绝句","c":["东郭竹溪君所庐，我家此物也扶疏。","何时归去数来往，不似而今空寄书。"]},{"t":"寄毕叔文二首 其二","f":"七言绝句","c":["闷甚长须酒破除，酒能作病又何如。","故人欲问春来趣，多病还于酒盏疏。"]},{"t":"寄毕叔文二首 其一","f":"七言绝句","c":["小园春物比如何，想见花稠草作窠。","老去不能知许事，顾怀修碧可磨挲。"]},{"t":"寄怀","f":"五言绝句","c":["雨足新晴后，凉生静夜时。","支筇谁得见，惟有鹭鸥知。"]},{"t":"寄怀二十首 其二十","f":"七言绝句","c":["早起阴晴殊未分，杜鹃何许叫深云。","眼中忽尔生新句，何异风行水面纹。"]},{"t":"寄怀二十首 其十九","f":"七言绝句","c":["剩水残山觉范诗，汎然孤棹去何之。","倚樯吟啸元无忤，谁信今朝无早炊。"]},{"t":"寄怀二十首 其十八","f":"七言绝句","c":["忽忽离家且一年，春风又是海棠天。","还家何以遗妻子，倾倒囊诗近百篇。"]},{"t":"寄怀二十首 其十七","f":"七言绝句","c":["祝融香火我亡缘，还上江头上水船。","赖得江山旧相识，登临到处一悠然。"]},{"t":"寄怀二十首 其十六","f":"七言绝句","c":["下水乘舟恨少滩，溯流翻恨溯滩难。","人生淹速祇如此，何必区区千万端。"]},{"t":"寄怀二十首 其十五","f":"七言绝句","c":["雪没东园一径深，频惊饥雀落空林。","疏明自喜山房小，更听哀弦空外音。"]},{"t":"寄怀二十首 其十四","f":"七言绝句","c":["终日搜诗思不枯，坐间失喜折冰须。","寒窗雪满无人到，伴我一枝梅更孤。"]},{"t":"寄怀二十首 其十三","f":"七言绝句","c":["破屋支撑风雨馀，世间种种不关渠。","忍饥要惯无他术，过午未炊犹读书。"]},{"t":"寄怀二十首 其十二","f":"七言绝句","c":["秋风常恐到无期，一雨便兴摇落悲。","疾病相攻今转甚，囊空何以致高医。"]},{"t":"寄怀二十首 其十一","f":"七言绝句","c":["春今五日如京兆，风雨更堪携折之。","我病不能知许事，饭馀扪腹细哦诗。"]},{"t":"寄怀二十首 其十","f":"七言绝句","c":["楝树层层细著花，日薰香暖蜜蜂衙。","客来傥有论文兴，活火风炉自煮茶。"]},{"t":"寄怀二十首 其九","f":"七言绝句","c":["扶疏夏木已来禽，安石榴花出树深。","六尺纸窗明棐几，迸阶閒笋欲成阴。"]},{"t":"寄怀二十首 其八","f":"七言绝句","c":["早禾栖陇待晴收，雨欲为霖势可忧。","似觉朝来乌鹊喜，便携童稚过西畴。"]},{"t":"寄怀二十首 其七","f":"七言绝句","c":["县官宽灭去年租，癃老扶携听诏书。","和气定能消冷气，未知天意又何如。"]},{"t":"寄怀二十首 其六","f":"七言绝句","c":["读书万卷不充饥，枵腹吟哦大似痴。","不是邻僧能送米，囊空何以续晨炊。"]},{"t":"寄怀二十首 其五","f":"七言绝句","c":["春风底事苦欺梅，旧雪未乾新雪催。","元自不侪桃与李，何须著意苦相摧。"]},{"t":"寄怀二十首 其四","f":"七言绝句","c":["正月山园未有花，梅花落尽亦堪嗟。","瑞香莫与兰争长，独立风前自一家。"]},{"t":"寄怀二十首 其三","f":"七言绝句","c":["阴晴竟日漫难分，远岫犹藏欲雨云。","叹息无言桃与李，一年踪迹又纷纷。"]},{"t":"寄怀二十首 其二","f":"七言绝句","c":["旱风吹野未成阴，空喜孤云出寸岑。","饱食便知难自必，茶瓯小注莫令深。"]},{"t":"寄怀二十首 其一","f":"七言绝句","c":["晏斋生理比何如，破砚今来亦已枯。","珍重此君为耐久，澹然相对祗清癯。"]},{"t":"寄李叔器兼寄毛伯明张王臣康叔临三首 其三","f":"七言绝句","c":["向来相别恨匆匆，别复长思讲学功。","江水无由致双鲤，春风又是起归鸿。"]},{"t":"寄李叔器兼寄毛伯明张王臣康叔临三首 其二","f":"七言绝句","c":["洞庭拍拍浸君山，亭对君山君闭关。","胜日想多文会友，定应怜我在荆蛮。"]},{"t":"寄李叔器兼寄毛伯明张王臣康叔临三首 其一","f":"七言绝句","c":["春水满时春草生，春风日日上江亭。","蘋花采得从谁寄，空送沅湘入洞庭。"]},{"t":"寄李商叟二首 其二","f":"七言绝句","c":["卿来我已后诸公，颇愿相从缯简中。","岂若吾身得亲见，怪君风味莫之同。"]},{"t":"寄李商叟二首 其一","f":"七言绝句","c":["笋茁桐敷又一时，想君日日有新诗。","诗成寄我何其晚，要与羊何共和之。"]},{"t":"寄周愚卿","f":"七言绝句","c":["买得武夷毛竹杖，忽思江外友于人。","青原若访常荷屋，助尔扶携觅句新。"]},{"t":"寄周愚卿兄弟","f":"七言绝句","c":["渚花飘锦已残春，几对江山思故人。","邂逅欲书书不得，醒狂于此见天真。"]},{"t":"寄审知","f":"五言绝句","c":["枫赤芦花白，扁舟夜泊时。","平生故人梦，细雨说相思。"]},{"t":"寄居邠","f":"七言绝句","c":["黄溪茶种有闽风，忆昨缄封自赞公。","筠焙久空青箬里，纸囊盍寄白云中。"]},{"t":"寄林敏夫二首 其二","f":"七言绝句","c":["吴江应已落丹枫，况说枫桥半夜钟。","想见归心成日日，暮云如我忆江东。"]},{"t":"寄林敏夫二首 其一","f":"七言绝句","c":["闻说君家家具区，秋风应熟季鹰鲈。","虽云祸福有倚伏，要是知几失早图。"]},{"t":"寄莫万安升之二首 其二","f":"七言绝句","c":["身在江西尽处山，江东家住几时还。","苦吟更与风光别，一夜并成双鬓斑。"]},{"t":"寄莫万安升之二首 其一","f":"七言绝句","c":["我坐移官不作忧，得君为主见风流。","移官得此天如恶，遣落江西尽处头。"]},{"t":"寄逸","f":"七言绝句","c":["思隐今年竹几竿，因人略不报平安。","门东叫认真痴绝，但有书来说饱餐。"]},{"t":"寄蒋攸县砺二首 其二","f":"七言绝句","c":["湘山越岭纵怀归，可废当年靡盐诗。","府主甚贤宾得士，岂忧磨磷涅能缁。"]},{"t":"寄蒋攸县砺二首 其一","f":"七言绝句","c":["君家三径开来久，不待弦歌始得资。","傥欲赋归归便得，湘山越岭匪逶迟。"]},{"t":"寄谢周子开","f":"七言绝句","c":["四益堂中四益碑，南轩文字述家规。","殷勤打寄非无益，从此折肱当得医。"]},{"t":"寄韩仲止主簿 其三","f":"七言绝句","c":["介室于余亦外家，二年朝夕向长沙。","闻君往会临川葬，我不及前空叹嗟。"]},{"t":"寄韩仲止主簿 其二","f":"七言绝句","c":["海内知名长少公，在今谁复可同风。","可怜籍湜今头白，空复挂名家集中。"]},{"t":"寄韩仲止主簿 其四","f":"七言绝句","c":["病卧凄然寂寞滨，既亲且故几何人。","如君父子风流似，宁复可疏当可亲。"]},{"t":"寄韩仲止主簿 其一","f":"七言绝句","c":["旧来绝叹茶山竹，今日重悲南涧泉。","儒雅风流真不愧，两贤真可作三贤。"]},{"t":"寄愚卿二首 其二","f":"七言绝句","c":["马甘荐秣自投鞿，巧弹何曾射倦飞。","风急正看蛛去网，雨酣还见蚁争围。"]},{"t":"寄愚卿二首 其一","f":"七言绝句","c":["江边栏槛竹中斋，缘我频能扫又开。","茅屋苍苔唤归去，来禽青李待书来。"]},{"t":"寄简欧阳伯威刘伯山","f":"七言绝句","c":["问讯穷冈病主人，若为买得竹溪邻。","是中剩有堪诗处，恨不与之相主宾。"]},{"t":"寄潘恭叔曾幼度三首 其三","f":"七言绝句","c":["天将绝境付奇才，万里飘零莫自哀。","不尔如何吾幼度，郁孤台又粤王台。"]},{"t":"寄潘恭叔曾幼度三首 其二","f":"七言绝句","c":["去岁附书并附诗，自吴适粤至何时。","殷勤再觅铜鱼使，傥不沉浮敢恨迟。"]},{"t":"寄潘恭叔曾幼度三首 其一","f":"七言绝句","c":["一冬风雪苦多寒，春至冰霜更积攒。","咫尺端如隔千里，况于楚粤路漫漫。"]},{"t":"常山道中 其一","f":"七言绝句","c":["桃李成阴麦有花，笋舆咿哑我还家。","谬恭莫望临邛令，雨后东陵宜种瓜。"]},{"t":"常山道中 其二","f":"七言绝句","c":["烟雨濛濛鸡犬声，道长人寂掩柴荆。","漫山桃李浑无数，归近何妨细作程。"]},{"t":"悠然亭","f":"五言绝句","c":["亭能招南山，径亦栽黄菊。","我乃愿师陶，过公期托宿。"]},{"t":"探梅","f":"七言绝句","c":["石上生梅老未枯，著花虽少更敷腴。","要须邻老深调护，莫遣儿童纵牧刍。"]},{"t":"晚书二首 其二","f":"五言绝句","c":["何处黄鹂语，玲珑芳树间。","可怜求友意，飞去又飞还。"]},{"t":"晚书二首 其一","f":"五言绝句","c":["春晚苦多风，花残不见红。","问花宁自觉，愁杀白头翁。"]},{"t":"晚行见梅","f":"七言绝句","c":["玉立空林一树梅，向人脉脉似怜才。","微波托使为媒去，一被晚风吹又回。"]},{"t":"晚行田间书事三首 其三","f":"七言绝句","c":["我生饱识田家趣，只坐无田归计迟。","纵是无田慵可得，莫将画饼欲充饥。"]},{"t":"晚行田间书事三首 其二","f":"七言绝句","c":["郎罢肩犁稚子前，牛行熟路不须牵。","归来饭倒羹初糁，洗脚还将草履穿。"]},{"t":"晚行田间书事三首 其一","f":"七言绝句","c":["青裙汲水过前溪，白发应门儿戏啼。","试问主人何所在，为言南亩正扶犁。"]},{"t":"晚过刘伯山","f":"七言绝句","c":["晚向穷冈访竹亭，竹间忽有打禾声。","凶年独使诗人饱，可见天公非世情。"]},{"t":"晚过彦真山亭并呈允升季仪兼属照邻二首 其二","f":"七言绝句","c":["寤寐诗名岁月过，日来方喜和羊何。","秋风奈我当归去，湘水湘山馀恨多。"]},{"t":"晚过彦真山亭并呈允升季仪兼属照邻二首 其一","f":"七言绝句","c":["隔岸看山自足佳，背山仍有碧云遮。","我来政值崚嶒际，却恨林端已暮鸦。"]},{"t":"晚作","f":"七言绝句","c":["古屋黄昏蝙蝠飞，尔飞干我竟何为。","但愁蚊子且生翼，饱尔亦当侵我肌。"]},{"t":"晚卧二首 其二","f":"七言绝句","c":["戏学韩公盆作池，雨来亦解起风漪。","蛙鸣莫作鼓吹想，更问属官仍属私。"]},{"t":"晚卧二首 其一","f":"七言绝句","c":["轩小才堪置竹床，晚来新浴快初凉。","扫除诸妄归真想，薝卜林中闻妙香。"]},{"t":"晚秋郊居八首 其八","f":"七言绝句","c":["邻父疑为三径孙，一生辛苦在田园。","近来交友谁相顾，渠独频沾菜把恩。"]},{"t":"晚秋郊居八首 其七","f":"七言绝句","c":["蔓草依依网作窠，荒庭寂寂蚓能歌。","人言病久须閒默，习气相攻未易诃。"]},{"t":"晚秋郊居八首 其六","f":"七言绝句","c":["霜天柿叶须收拾，咫尺山园底去迟。","不是功名羁绊得，病来筋力费扶持。"]},{"t":"晚秋郊居八首 其五","f":"七言绝句","c":["病夫慵出长蓬蒿，但见刍薪价益高。","积雨了知寒在候，我方随事典衣袍。"]},{"t":"晚秋郊居八首 其四","f":"七言绝句","c":["九日黄花信昔谈，是身何自见江南。","故今开晚方为贵，失所胡为浪不堪。"]},{"t":"晚秋郊居八首 其三","f":"七言绝句","c":["病橘萧萧祇古枝，二三酸子间虫丝。","人言社酒堪医此，太息于今已后时。"]},{"t":"晚秋郊居八首 其二","f":"七言绝句","c":["宋玉悲秋殆我欺，江南摇落定何时。","不因枫树颜如渥，松柏连林漫莫知。"]},{"t":"晚秋郊居八首 其一","f":"七言绝句","c":["梨枣熟时须一雨，江南底忽类中州。","南人不识北人事，懔懔已怀禾黑忧。"]},{"t":"晚晴二首 其二","f":"七言绝句","c":["空山草木固能长，迩日曾经剪伐荒。","一笑为渠成解说，政防妨我步斜阳。"]},{"t":"晚晴二首 其一","f":"七言绝句","c":["山中岑郁倍怀人，况是春来阴雨频。","到得小晴堪细履，又嗟落莫与谁亲。"]},{"t":"晚登邬子亭用壁间韵四首 其四","f":"七言绝句","c":["何处鸣桹歌浊清，鹭飞鸥舞惯忘惊。","卒逢已觉翩然逝，犹欲因之问水程。"]},{"t":"晚登邬子亭用壁间韵四首 其三","f":"七言绝句","c":["中流掀簸势难停，望断龙祠与戍亭。","胡不少留风止去，塔铃昨者故丁宁。"]},{"t":"晚登邬子亭用壁间韵四首 其二","f":"七言绝句","c":["朝行忽尔逆风颠，已到津头尚耸然。","不似渔翁易夷险，雨蓑晴笠住忘年。"]},{"t":"晚登邬子亭用壁间韵四首 其一","f":"七言绝句","c":["秋入江湖事事幽，未妨著我咏洪流。","水居三两似相识，苦问来船仍去舟。"]},{"t":"晚歇溪上","f":"五言绝句","c":["爱此沧浪水，临流坐写诗。","赋诗元未就，藉水发幽姿。"]},{"t":"晚霁","f":"七言绝句","c":["雨歇蝉声抱木悲，茅檐独立看云移。","一阴十日不见月，想见清光分外奇。"]},{"t":"望金华山绝句四首 其四","f":"七言绝句","c":["九陌纷纷翳吾目，是间冰熨一尘无。","十日五日一水石，造次著诗那得摹。"]},{"t":"望金华山绝句四首 其三","f":"七言绝句","c":["一溪屈曲几弯环，赢得金华四面看。","雨黛欲收晴翠滴，忽然云起又漫漫。"]},{"t":"望金华山绝句四首 其二","f":"七言绝句","c":["云蔽云开山祇然，画无能事著诗传。","扁舟尽日无多厌，信手拈来亦漫编。"]},{"t":"望金华山绝句四首 其一","f":"七言绝句","c":["山青云白晚能佳，中有仙人旧隐家。","弹压政须烦健笔，颉颃谁与佩飞霞。"]},{"t":"梅花十绝句 其八","f":"七言绝句","c":["十里荆溪溪上梅，故人几日寄诗来。","相应载酒裴回次，忆我去年同此杯。"]},{"t":"梅花十绝句 其七","f":"七言绝句","c":["雨薄梅花似有情，定应怜我太饥生。","不同玉屑和朝露，且效夕餐收落英。"]},{"t":"梅花十绝句 其三","f":"七言绝句","c":["断崖脩竹是吾庐，亦有梅花手自锄。","岁晚平安久无报，不知春到又何如。"]},{"t":"梅花十绝句 其二","f":"七言绝句","c":["寒雀萧萧冻不喧，背人缘底过颓垣。","似矜玉粒堪充饱，啄破霜包无乃冤。"]},{"t":"梅花十绝句 其六","f":"七言绝句","c":["江上人家烟雨间，意行曾忆犯榛菅。","祇今冷落人谁问，输与白鸥相对閒。"]},{"t":"梅花十绝句 其四","f":"七言绝句","c":["风月悬知非俗物，与梅相对却成三。","是中故有无穷意，曲几团蒲须细参。"]},{"t":"梅花十绝句 其九","f":"七言绝句","c":["梅花佳处是孤影，月落参横真见之。","几欲烦我为摹写，却愁才尽不能支。"]},{"t":"梅花十绝句 其十","f":"七言绝句","c":["松风亭下盛开时，曾辱苏仙与赋诗。","今日折花怀此老，端如嗅菊念东篱。"]},{"t":"梅花十绝句 其五","f":"七言绝句","c":["桃李纷纷倚市门，岂知幽谷有佳人。","莫嗟玉粒终无偶，人物谁知温太真。"]},{"t":"梅花十绝句 其一","f":"七言绝句","c":["疏篱半倒竹脩脩，下有冰泉断复流。","此地著梅故差胜，杖藜何惜屡经丘。"]},{"t":"梅花绝句五首要明叔仲威同作 其一","f":"七言绝句","c":["起步寒梢百尺长，骤惊触目尽琳琅。","直疑霜月能为幻，作意槛之还有香。"]},{"t":"梅花绝句五首要明叔仲威同作 其四","f":"七言绝句","c":["傍观怪我底多病，不奈俗尘来败人。","故人寄我山中信，竹故岁寒梅告春。"]},{"t":"梅花绝句五首要明叔仲威同作 其三","f":"七言绝句","c":["木犀犹假菊为裳，兰也仍须紫作章。","不似梅花最高洁，温然全是玉之良。"]},{"t":"梅林渡怀惠卿","f":"七言绝句","c":["近城亦复多渔户，作吏聊须似马曹。","更想周家江上屋，竹林梅树出檐高。"]},{"t":"梅落二首 其二","f":"七言绝句","c":["春风次第归桃李，催得梅花一夜飞。","时序匆匆几回首，即看红绽雨添肥。"]},{"t":"梅落二首 其一","f":"七言绝句","c":["春风可是独嗔梅，不待飘零著雨催。","我欲挽留无上策，戏拈落蕊荐芳醅。"]},{"t":"渔父诗四首 其四","f":"七言绝句","c":["早悟君王物色求，子陵应已弃羊裘。","绝知至德终难掩，女子亦称韩伯休。"]},{"t":"渔父诗四首 其三","f":"七言绝句","c":["风色披披手欲龟，日光飐飐鬓成丝。","只今网罟无穷利，乐在竿纶顾未知。"]},{"t":"渔父诗四首 其二","f":"七言绝句","c":["泛宅浮家一叶间，长年绿水又青山。","若为不使兼能赋，始信天公到此悭。"]},{"t":"渔父诗四首 其一","f":"七言绝句","c":["掉船晨出暮知归，举网惊呼鱼定肥。","倾倒得钱何用许，江头取醉暮相违。"]},{"t":"渔村落照","f":"五言绝句","c":["落日千山赤，平林一带青。","翁方卖鱼去，孤楫自横汀。"]},{"t":"章少隐尝有逸句云片片梅花随雨脱浑疑春雪堕林梢今日雪后梅已有落者偶与公择清坐举似此诗欣然联成一绝","f":"七言绝句","c":["片片梅花脱雨轻，半飞欲坠更多情。","浑疑春雪林梢堕，输与诗翁照眼明。"]},{"t":"谒仰山寺","f":"七言绝句","c":["欲知正直不余欺，请祷应闻韩退之。","旱昔不灾今病雨，我虽非职敢陈诗。"]},{"t":"谒雷潭寺韩文公祠","f":"七言绝句","c":["使君令尹各能文，政亦及民俱好春。","考废祠贤端有以，后人当复嗣前尘。"]},{"t":"谒颜范祠 其二","f":"七言绝句","c":["义气常于翰墨看，凛然今日拜衣冠。","去年已失临川郡，及尔能来愧始安。"]},{"t":"谒颜范祠 其三","f":"七言绝句","c":["为政当知政所先，政先孰愈祀先贤。","可怜颜范祠堂下，草蔓不锄阶甃穿。"]},{"t":"谒颜范祠 其一","f":"七言绝句","c":["处士当年配水仙，范公亦俨客星悬。","谁知旧日番君国，飒爽英姿盖九贤。"]},{"t":"逸再为婺女之行既别出郭矣夜不能寐成六绝句追送 其五","f":"七言绝句","c":["我归犹尔未还家，送汝令人重叹嗟。","送汝叹嗟犹自可，最思阿庆语咿哑。"]},{"t":"逸再为婺女之行既别出郭矣夜不能寐成六绝句追送 其三","f":"七言绝句","c":["兹行为谢时衡岳，并与传声吕法曹。","汝解事贤其自勉，我因求友不妨高。"]},{"t":"逸再为婺女之行既别出郭矣夜不能寐成六绝句追送 其一","f":"七言绝句","c":["正学堂堂吕紫微，有孙端的为传衣。","祇今一派金华是，戴路年来汝所依。"]},{"t":"逸再为婺女之行既别出郭矣夜不能寐成六绝句追送 其二","f":"七言绝句","c":["体能中格号时文，能料科场可策勋。","此外更资为学在，木须根立乃凌云。"]},{"t":"逸再为婺女之行既别出郭矣夜不能寐成六绝句追送 其四","f":"七言绝句","c":["去岁诸公祖敬之，我曾同席共委蛇。","相逢傥复蒙相问，为道东归鬓益丝。"]},{"t":"逸再为婺女之行既别出郭矣夜不能寐成六绝句追送 其六","f":"七言绝句","c":["岁事将穷老所悲，念将留汝亦奚为。","新年事业能增进，绝胜衰残守旧诗。"]},{"t":"野花 其二","f":"七言绝句","c":["野花无数不知名，白白红红俱赋情。","纵使不蒙姚魏赏，雨开风落亦何争。"]},{"t":"阎伯善以孟东野集见惠二首 其二","f":"七言绝句","c":["几度相从酌酒深，向来相识未如今。","临分念我亦穷者，乞与郊诗俾细吟。"]},{"t":"阎伯善以孟东野集见惠二首 其一","f":"七言绝句","c":["文字何关达与穷，怅君一尉已龙钟。","过君旧邑求君集，行橐萧然足慰侬。"]},{"t":"雪中三忆三首 其二","f":"五言绝句","c":["忆我园中菜，栽迟科未敷。","哀哉被摧压，端亦似人癯。"]},{"t":"雪观","f":"五言绝句","c":["冷语可销暑，昔人曾咏之。","我来登雪观，政值绿阴时。"]},{"t":"雪浪阁二首 其二","f":"七言绝句","c":["雪浪轩窗由块石，未知栏槛倚江边。","故人曾为炰烹怖，一看姓名增惘然。"]},{"t":"雪浪阁二首 其一","f":"七言绝句","c":["木末阑干渺未平，泊舟石径得深行。","舟行不见江流阔，一上凭高觉快生。"]},{"t":"黄白菊","f":"七言绝句","c":["白菊攲倾拥玉钿，黄花零乱委金钱。","饥寒未免交为累，金玉繇来枉现前。"]},{"t":"凿磨岭","f":"七言绝句","c":["复岭重冈向背迷，瘦筇深与病夫宜。","早禾未割尤艰食，过午人家犹未炊。"]},{"t":"喜雨投詹信州口号六首 其六","f":"七言绝句","c":["久晴政为收蚕麦，好雨从今及稻禾。","试向诸生选何武，要歌乐职颂中和。"]},{"t":"喜雨投詹信州口号六首 其五","f":"七言绝句","c":["使君笑别赤城仙，来结山中大士缘。","仙佛将何佐佳政，但当惠我以丰年。"]},{"t":"喜雨投詹信州口号六首 其四","f":"七言绝句","c":["开藩甫及四十日，籍甚治声过所闻。","吏畏神明简朱墨，民怀清净乐耕耘。"]},{"t":"喜雨投詹信州口号六首 其三","f":"七言绝句","c":["昔在乌台誉已休，旋分符竹政仍优。","论思未即归清禁，历试何妨又一州。"]},{"t":"喜雨投詹信州口号六首 其二","f":"七言绝句","c":["使君自是为霖手，要雨雨来何旱忧。","报尔田家但勤力，今年定有十分秋。"]},{"t":"喜雨投詹信州口号六首 其一","f":"七言绝句","c":["插秧未了早愁乾，民不知由作屡叹。","天欲明吾使君政，故令一雨示艰难。"]},{"t":"喜晴 其三","f":"七言绝句","c":["扫除诗癖未能空，从使人讥手病风。","事业深虞一无就，壮颜都有几时红。"]},{"t":"喜晴 其二","f":"七言绝句","c":["梅花已逐冻泥空，留得馀香傲晚风。","春事十分财入手，只愁病眼眩青红。"]},{"t":"喜晴 其四","f":"七言绝句","c":["两公贤比道州阳，总为勤民鬓已苍。","喜雨喜晴俱有赋，乐忧宁止为诗昌。"]},{"t":"喜晴 其一","f":"七言绝句","c":["雨脚昏昏扫不空，柴门未觉有春风。","晚晴骤喜窗明处，犹倚蒲团附火红。"]},{"t":"斯远兄入城见使君郎中且谒尚书韩先生提属李丈题诗以赠四首 其四","f":"七言绝句","c":["上饶耆旧无曾吕，月旦多称李德翁。","闻道二难真顿有，盖公堂下求盍通。"]},{"t":"斯远兄入城见使君郎中且谒尚书韩先生提属李丈题诗以赠四首 其三","f":"七言绝句","c":["永嘉别驾从渠说，为说钱晁好夙通。","聊以吾云卜吾子，傥贤吾亦出蒿蓬。"]},{"t":"斯远兄入城见使君郎中且谒尚书韩先生提属李丈题诗以赠四首 其二","f":"七言绝句","c":["南涧先生归几时，南溪如泛未传诗。","君行为我殷勤录，并问茶山僧乞碑。"]},{"t":"斯远兄入城见使君郎中且谒尚书韩先生提属李丈题诗以赠四首 其一","f":"七言绝句","c":["雨后乘流绝快哉，眼中无适不诗材。","诗成去觅骑鲸李，衔袖探将一笑开。"]},{"t":"智门寺后梅开丛竹间斯远举坡公春来幽谷之句因成二绝 其二","f":"七言绝句","c":["朋游落寞每形悲，喜甚归来慰所思。","况在水滨山崦里，两筇相对索梅诗。"]},{"t":"智门寺后梅开丛竹间斯远举坡公春来幽谷之句因成二绝 其一","f":"七言绝句","c":["花开的皪固难知，旧识黄州副使诗。","政使尽开能尔盛，孰知将吐乃为奇。"]},{"t":"曾秀才送茶","f":"七言绝句","c":["正尔耽诗不耐閒，镜中频觉瘦栾栾。","曾郎惠我尽清供，椀把春风香并兰。"]},{"t":"曾相士约过意钓答以绝句","f":"七言绝句","c":["为竹作亭还斫竹，取诗名榜更题诗。","归来十日未一往，聊待萧然雨后时。"]},{"t":"曾裘父寄二绝并呈审知一再次韵前以寄曾后寄审知四首 其四","f":"七言绝句","c":["南丰鬓发已如翁，子盖他时冰雪容。","长少结交端有道，我凡何处滥登龙。"]},{"t":"曾裘父寄二绝并呈审知一再次韵前以寄曾后寄审知四首 其三","f":"七言绝句","c":["安否别来端若何，尺书可是雁无过。","南丰惠我新诗什，亦复怀君旧琢磨。"]},{"t":"曾裘父寄二绝并呈审知一再次韵前以寄曾后寄审知四首 其二","f":"七言绝句","c":["纷纷竞说杜陵翁，此老真能数百容。","我亦几同叶公好，骇然今日见真龙。"]},{"t":"曾裘父寄二绝并呈审知一再次韵前以寄曾后寄审知四首 其一","f":"七言绝句","c":["向来共和有羊何，今见公才十倍过。","可念此身如垢镜，要须著手为揩磨。"]},{"t":"游叫岩用范元卿自普康归日留题韵","f":"七言绝句","c":["溪行又作叫岩登，凉冷端如快踏冰。","所过有山成一访，是知我亦在家僧。"]},{"t":"游仰山欲游兰若不果怀混融二首 其二","f":"七言绝句","c":["欲寻兰若尉知名，獭径桥头水乱鸣。","引领白云人甚远，纵游谁解饮渊明。"]},{"t":"游仰山欲游兰若不果怀混融二首 其一","f":"七言绝句","c":["冒雨来看大仰山，不惟泉石意相关。","混融时事谁能说，稍向诗碑见一班。"]},{"t":"游思庵","f":"七言绝句","c":["路落林湾得小庵，轩窗都在万松间。","兹游不为寻僧至，更拟缘云度一山。"]},{"t":"湖州舟中","f":"七言绝句","c":["平生苕霅又扁舟，尚喜深盟不负鸥。","忆昔诗篇浑漫兴，祇今翻觉费冥搜。"]},{"t":"琛卿为梅置酒用前韵","f":"七言绝句","c":["背荫初疑星未融，细看真有映玲珑。","兴深且约诸君往，明日当愁著土中。"]},{"t":"琛卿论诗用前韵示之","f":"七言绝句","c":["活法端知自结融，可须琢刻见玲珑。","涪翁不作东莱死，安得斯文日再中。"]},{"t":"登安仁云锦驿后挹仙亭三首 其三","f":"七言绝句","c":["对面雨来山欲移，援毫我亦赋新诗。","扁舟纵是促行去，不废小亭筇一枝。"]},{"t":"登安仁云锦驿后挹仙亭三首 其二","f":"七言绝句","c":["未解桃源果有无，树林楼阁世行图。","此亭纵说空无物，犹有仙山来坐隅。"]},{"t":"登安仁云锦驿后挹仙亭三首 其一","f":"七言绝句","c":["古木阴中屋数椽，下临萦折几山川。","晚来快雨仍新浴，端觉飘飘意欲仙。"]},{"t":"登县楼有感二首 其二","f":"七言绝句","c":["见说南楼秋气多，夜凉槐竹影婆娑。","满楼风月成辜负，奈此青州从事何。"]},{"t":"登县楼有感二首 其一","f":"七言绝句","c":["一水中分南北市，插天蒙末有佳山。","太平官府元无事，聊放衰翁一日閒。"]},{"t":"登岳阳楼 其四","f":"七言绝句","c":["晚风何许递参差，南望令人思九疑。","渺渺烟波莫能极，谁云一苇可杭之。"]},{"t":"登岳阳楼 其三","f":"七言绝句","c":["几思假日赋登楼，风雨连连不肯休。","待得晴时又成去，再三举手谢沙鸥。"]},{"t":"登岳阳楼 其二","f":"七言绝句","c":["自昔骚人半此州，不因放逐即淹留。","我今毋负仍非客，何事汎然还一游。"]},{"t":"登岳阳楼 其一","f":"七言绝句","c":["太史南游上会稽，爱奇端欲助文辞。","萧骚白发离骚国，不到巴陵终欠诗。"]},{"t":"登清虚亭","f":"七言绝句","c":["步上危亭欲细看，忽惊风雨暗江干。","此身不作蛮州鬼，犹拟扶筇再倚栏。"]},{"t":"答施荣甫","f":"七言绝句","c":["昨韵村中好客稀，今吟临水送将归。","笑谈未了风吹断，何日重来款竹扉。"]},{"t":"答简审知","f":"七言绝句","c":["早起难胜上水寒，为君还复念湖滩。","泥滑蹇驴难跨去，七言聊遣问平安。"]},{"t":"腊月十九日饮于周氏无尽藏雪作","f":"七言绝句","c":["卯饮君家江上楼，坐中风雪暗前洲。","世间矰缴无空巧，我自归心没白鸥。"]},{"t":"舒村","f":"七言绝句","c":["有竹如椽故可佳，况于竹外隐鸥沙。","不嫌官道多车马，此地端宜著钓车。"]},{"t":"落叶","f":"五言绝句","c":["捲捲从何起，多因为晚风。","飘飘久不下，还复反荒丛。"]},{"t":"谢人送水仙","f":"七言绝句","c":["珍重江南好事家，老将种莳作生涯。","似怜寂寞书斋里，折赠盈篮栗玉花。"]},{"t":"谢莫升之惠茶","f":"七言绝句","c":["双罂稍辍焙中茶，好卧黄紬稳听衙。","禦雨况闻当用瓦，固知不怕落檐花。"]},{"t":"谢彭沅陵送猫","f":"七言绝句","c":["怪来米尽鼠忘迁，嚼齧侵寻到简编。","珍重令君怜此意，不劳鱼聘乞衔蝉。"]},{"t":"谢答严用韵送绿萼梅","f":"七言绝句","c":["两咏君家两样梅，清愁已瘦一分肌。","春风咫尺花无数，更合安排几首诗。"]},{"t":"赋刘子澄墨庄","f":"五言绝句","c":["勤力汉疏傅，遗安庞德公。","公家业异此，衰盛国应同。"]},{"t":"赋道傍菊 其六","f":"七言绝句","c":["黄菊花中黄蝶飞，似怜节晚怅馀晖。","春风桃李明年事，十月清霜何处归。"]},{"t":"赋道傍菊 其五","f":"七言绝句","c":["日和犹有采花蜂，日冷凄然难为容。","不以无人废芳事，政应兰薏与同宗。"]},{"t":"赋道傍菊 其四","f":"七言绝句","c":["三径虽荒菊尚存，江东书到每伤神。","七盘八叠辰州路，赖尔相看作故人。"]},{"t":"赋道傍菊 其三","f":"七言绝句","c":["山行渐欲堕荆榛，夹道黄花独尔新。","野外篱边非失所，尚能寒眼动诗人。"]},{"t":"赋道傍菊 其二","f":"七言绝句","c":["世无元亮亦无诗，菊亦凄凉孰汝知。","问我无诗宁爱菊，落英闻道可充饥。"]},{"t":"跋长公帖","f":"七言绝句","c":["每见故家观故物，辄思前事念前人。","锦囊玉轴千年秘，儋耳珠崖万里身。"]},{"t":"跋刘溪翁题韩府诗 其一","f":"七言绝句","c":["何人咏出韩家府，是我建阳刘叔通。","尽道唐人工乐府，罕能褒贬似渠工。"]},{"t":"道店菊","f":"七言绝句","c":["种花本欲娱行客，客子逢花特地悲。","忽忽重阳今半月，依然青蕊网蛛丝。"]},{"t":"道傍菊有感","f":"七言绝句","c":["昔日曾升君子堂，祇今萧艾与俱长。","可怜冷蝶无时态，尽日伶俜为汝忙。"]},{"t":"道傍落梅","f":"七言绝句","c":["一树梅花古道边，随风堕落自年年。","情知所遇合如此，未必春风独尔偏。"]},{"t":"鹅湖道中二首 其二","f":"七言绝句","c":["人间那有万株松，莫道名山都未逢。","自拄枯藜行不倦，更听斋后几声钟。"]},{"t":"鹅湖道中二首 其一","f":"七言绝句","c":["两道苍松列翠幢，雨来浑似度桐江。","恨无东绢堪图此，归伴蒲团挂北窗。"]},{"t":"鹅湖道中呈斯远","f":"七言绝句","c":["翠阜奔腾似列屯，老松错落更横陈。","风高日暖鹅湖路，宜此萧然两幅巾。"]},{"t":"微雨三首 其三","f":"五言绝句","c":["云深不见山，雨密还遮树。","相见说相思，相思说何处。"]},{"t":"微雨三首 其二","f":"五言绝句","c":["大雨若盆倾，小雨如丝乱。","盆覆几时收，丝长何日断。"]},{"t":"微雨三首 其一","f":"五言绝句","c":["雨丝情脉脉，雨点泪浪浪。","无处堪回首，如何不断肠。"]},{"t":"感归鸟","f":"五言绝句","c":["鸟雀知既夕，相逢如择栖。","嗟余独何者，失侣自东西。"]},{"t":"感梅属周文显二首 其二","f":"七言绝句","c":["玉薄冰轻不自持，可能当此恶风吹。","要知此物坚牢质，不比渠侬耎脆姿。"]},{"t":"感梅属周文显二首 其一","f":"七言绝句","c":["严冬今日更天风，我与梅花瘦骨同。","我纵寒生犹附火，尔能孤立乱山中。"]},{"t":"楼步","f":"七言绝句","c":["人家簇簇晓烟青，湖上船归渔市腥。","细雨如丝山色暝，一杯浊酒慰飘零。"]},{"t":"溧阳书事","f":"七言绝句","c":["风引仙舟去莫同，自知名愧郭林宗。","倦游偶作连朝住，颇觉临邛费缪恭。"]},{"t":"滩头寺怀莫升之","f":"七言绝句","c":["青衫县尹沈泉久，黄绶尉曹华发多。","重到滩头旧游寺，一觞独举奈愁何。"]},{"t":"简见可觅画三首 其三","f":"七言绝句","c":["少文忘却行山脚，收拾经行入坐中。","我亦江山欲归去，自无画手得君工。"]},{"t":"简见可觅画三首 其二","f":"七言绝句","c":["白头流落离骚国，香草虽多独嗜兰。","犹恨芳时有衰歇，要须貌取四时看。"]},{"t":"简见可觅画三首 其一","f":"七言绝句","c":["我居何有惟脩竹，一日真成不可无。","别后平安久无报，为予十日写成图。"]},{"t":"简全真二首 其二","f":"七言绝句","c":["我诗每觉就匆匆，君句由来咏叹中。","爱我更能怜我友，谁云南北马牛风。"]},{"t":"简全真二首 其一","f":"七言绝句","c":["捐弃悲歌咏白团，未忘卫霍内金盘。","要知公子貂裘煖，孰若山人短褐寒。"]},{"t":"简邢公昭丈","f":"七言绝句","c":["梅园想见绿增深，竹径遥知笋出林。","坐底未能成一出，祇缘多病与多阴。"]},{"t":"简严先辈","f":"七言绝句","c":["闻道君家绿萼梅，韵胜绛袂拥冰肌。","夜来一雨应堪折，好寄尘窗伴觅诗。"]},{"t":"简严承务二首 其二","f":"七言绝句","c":["霜髭不摘老可憎，迹虽未然心已僧。","舌根鼻观习气在，茗椀策勋香事仍。"]},{"t":"简严承务二首 其一","f":"七言绝句","c":["玉梅遭旱颇萧然，清润思逢得水仙。","出门一笑不易致，许送茅斋端可怜。"]},{"t":"简沈沅陵求潮州韩文公庙碑并抄山谷碑诗二首 其二","f":"七言绝句","c":["涪翁昔在黔戎贬，逸翰遗章久更多。","字画公今元祐脚，拟烦妙手定如何。"]},{"t":"简沈沅陵求潮州韩文公庙碑并抄山谷碑诗二首 其一","f":"七言绝句","c":["公曾数载潮阳掾，笔力怪来韩与苏。","璧上庙碑当乞我，庶求涓滴润焦枯。"]},{"t":"简陈择之索诗","f":"七言绝句","c":["游山闻说多诗句，久已传抄听小胥。","屡戒应门老马走，门前驿递不为疏。"]},{"t":"简周允升三首 其三","f":"五言绝句","c":["君为乡校长，我政旅人居。","借屋元相近，相过莫放疏。"]},{"t":"简周允升三首 其二","f":"五言绝句","c":["春来多睡思，茗椀亦时须。","不敢家园乞，芭蕉有剩无。"]},{"t":"简周允升三首 其一","f":"五言绝句","c":["相逢亡恙外，第一问书堂。","为说当年树，如人出屋长。"]},{"t":"简周文显借王有道集二首 其二","f":"七言绝句","c":["先生风节昔人似，白发箪瓢犹嗜书。","家有校书诗百首，可能乞我助三馀。"]},{"t":"简周文显借王有道集二首 其一","f":"七言绝句","c":["乡人不识王有道，抔土空传唐校书。","闻道遗诗尚多有，典型不似晚唐馀。"]},{"t":"简俞尉","f":"七言绝句","c":["世人往往嗜甘言，正味多嫌橄榄严。","寄我要须并海物，花猪顿顿饭难厌。"]},{"t":"简施文叔绝句四首 其四","f":"七言绝句","c":["世上小儿迷黑白，此翁胸中泾渭殊。","少卑高论近流俗，恐妨要路肩安舆。"]},{"t":"简施文叔绝句四首 其三","f":"七言绝句","c":["营营青蝇挥不去，为问适从何处来。","病人埃郁思一洗，沈李浮瓜亦快哉。"]},{"t":"简施文叔绝句四首 其二","f":"七言绝句","c":["今日之热不可触，闭门养疴适所欲。","振衣策杖一欣然，凉风为我生脩竹。"]},{"t":"简施文叔绝句四首 其一","f":"七言绝句","c":["草树阴阴一径开，饥乌閒下啄莓苔。","清风无事自还往，时送官池荷气来。"]},{"t":"简徐季益 其二","f":"七言绝句","c":["不到西湖又五年，况当风雪探梅天。","出门有愧登山屦，寻友空回访戴船。"]},{"t":"简徐季益 其六","f":"七言绝句","c":["自从传得婺州诗，南北飘零阙后期。","一纸忽来湖上信，恍然堕我水仙祠。"]},{"t":"简徐季益 其一","f":"七言绝句","c":["月台台上几经过，白发重登奈我何。","树影漫能参独立，溪声无复乱长哦。"]},{"t":"简徐季益 其三","f":"七言绝句","c":["我诗虽老竟无工，君句能佳更不穷。","立论曾闻紫微老，赠篇期见习轩公。"]},{"t":"简徐季益 其五","f":"七言绝句","c":["南山最数月台高，曾著能诗何水曹。","略计出山今几载，生令梅赋阙风骚。"]},{"t":"简徐季益 其七","f":"七言绝句","c":["故人索我近题诗，何处如今更有之。","十载未论前日梦，一枝还动昔人思。"]},{"t":"简徐季益 其四","f":"七言绝句","c":["问讯西湖旧隐庐，水边雪后又何如。","祇今付与谁人手，籍甚诗名白社徐。"]},{"t":"简莫令求茶","f":"七言绝句","c":["万安近说神潭茶，颇似文当屈宋衙。","山中索居睡不足，碾寄盍令舒眼花。"]},{"t":"简梁叔昭觅香","f":"七言绝句","c":["雨住山岚更郁深，病夫晨起畏岑岑。","可能乞我蓬莱炷，要遣衣襟润不侵。"]},{"t":"简赠欧阳伯威二绝句 其一","f":"七言绝句","c":["江西人物况欧阳，少有诗名老更昌。","左辖虽能诵佳句，子虚胡不荐君王。"]},{"t":"简赠欧阳伯威二绝句 其二","f":"七言绝句","c":["三年身不到穷冈，诗友飘零半在亡。","杯里纵能谈矻矻，镜中无复鬓苍苍。"]},{"t":"雷老欲退普宁二绝句 其一","f":"七言绝句","c":["借阁看山且半年，看山未饱此为迁。","闻师亦欲抛山去，祇恐山灵未许然。"]},{"t":"雷老欲退普宁二绝句 其二","f":"七言绝句","c":["怀玉山中旧住人，岁寒庵里坐禅身。","当年未解来飞锡，今日何妨却问津。"]},{"t":"鼠山","f":"七言绝句","c":["鼠山山下鼠山潭，名字常因艇子谈。","几欲赋诗收拾汝，技穷如我莫多贪。"]},{"t":"漫兴十一首 其十一","f":"七言绝句","c":["寒日萧萧上矮窗，竹阴窗影两舂撞。","是中寓意真无尽，笔底寻诗卒未降。"]},{"t":"漫兴十一首 其十","f":"七言绝句","c":["春风吹绿满天涯，想见山园尽落花。","少日意狂轻节物，祇令流转谩成嗟。"]},{"t":"漫兴十一首 其九","f":"七言绝句","c":["风顺风横总欲乘，传呼虽数不余应。","去程渺渺湖边草，宿伴悠悠水上罾。"]},{"t":"漫兴十一首 其八","f":"七言绝句","c":["一日风帆数日程，绝知快意亦轻生。","延缘始欲滨湖去，可奈同途莫并行。"]},{"t":"漫兴十一首 其七","f":"七言绝句","c":["望极平湖不得山，水长山远画图间。","赋诗不似王摩诘，湖北湖南空往还。"]},{"t":"漫兴十一首 其六","f":"七言绝句","c":["已遭穿颊尚洋洋，尔本何辜饵触香。","断肉未能聊戒杀，念将赎尔又空囊。"]},{"t":"漫兴十一首 其五","f":"七言绝句","c":["钓发关余谓吉徵，长年三老尔何凭。","那知我本江湖士，失脚东来亦堕罾。"]},{"t":"漫兴十一首 其四","f":"七言绝句","c":["截竹钩丝作钓筒，半缠苍石著波中。","忽焉快跃知鱼中，相语相呼促短篷。"]},{"t":"漫兴十一首 其三","f":"七言绝句","c":["风雨萧萧病欲侵，杂然啼鸟在中林。","细听却有黄鹂语，端是当年隔叶音。"]},{"t":"漫兴十一首 其二","f":"七言绝句","c":["风雨属连殊未休，豫章城中十日留。","江云有意作晴色，今者薄暮当行舟。"]},{"t":"漫兴十一首 其一","f":"七言绝句","c":["桃树深红亦浅红，竹竿个个又丛丛。","儿男在田妇行馌，犬卧鸡啼茅舍空。"]},{"t":"瘦梅","f":"七言绝句","c":["清虚日集人当瘦，粪壤不资梅合癯。","君看霜皮藏玉骨，肯如朱粉斗涂糊。"]},{"t":"端午三首 其三","f":"七言绝句","c":["忠言不用竟沉死，留得文章星斗罗。","何意更觞昌歜酒，为君击节一长歌。"]},{"t":"端午三首 其二","f":"七言绝句","c":["年年端午风兼雨，似为屈原陈昔冤。","我欲于谁论许事，舍南舍北鹁鸠喧。"]},{"t":"端午三首 其一","f":"七言绝句","c":["谩说投诗赠汨罗，身今且尔奈渠何。","尝闻求福木居士，试向艾人成祝呵。"]},{"t":"静春堂","f":"五言绝句","c":["游子如蜂蝶，纷纷讵识春。","先生静中观，物物寓吾仁。"]},{"t":"趣成父酿酒用子进家法故及其昆仲","f":"七言律诗","c":["入眼江梅皆好枝，是中劳我几怀思。","诗声何止一头出，酒事乃称百室师。","闻道名方曾口授，定应买秫趁冬炊。","小须旬月酿当熟，寄我茅斋不可迟。"]},{"t":"题三老堂壁","f":"七言绝句","c":["雨过湖边秋思多，怅无轻樴傲渔蓑。","向来梦境今安在，名与青山保不磨。"]},{"t":"题子璿浯溪图","f":"七言绝句","c":["璿之戏墨万之诗，不到浯溪坐可知。","凛凛元颜千载意，若为付与水云期。"]},{"t":"题中团寺柱","f":"七言绝句","c":["向来不识中团寺，一自移家得屡过。","纵使山僧真厌客，淡然相对有维摩。"]},{"t":"题丰陂铺壁","f":"七言绝句","c":["树影当阶日正中，一蝉何适自吟风。","病夫畏病怕触热，聊此设床寻睡功。"]},{"t":"题仁坑铺","f":"七言绝句","c":["四松离立类岩幽，遮我聊为半日留。","更恨月明清影夜，不能于此听飕飕。"]},{"t":"题方士繇伯谟五丈所居三首 其三","f":"七言绝句","c":["远庵庵榜晦庵书，不独人高字亦如。","陇亩纵令非我有，溪山政自要君居。"]},{"t":"题方士繇伯谟五丈所居三首 其二","f":"七言绝句","c":["文定去营衡麓宅，仲容自老籍溪傍。","祇令风月无人主，今代玄英更姓方。"]},{"t":"题方士繇伯谟五丈所居三首 其一","f":"七言绝句","c":["诗名旧仰方丰国，句法亲传吕紫微。","闻道有儿能世业，师门更向晦庵归。"]},{"t":"题王远父所藏苏沧浪帖","f":"七言绝句","c":["吾家旧物见君家，说起漂流屡叹嗟。","甚欲持归试摹写，不堪病眼已昏花。"]},{"t":"题旧宫","f":"七言绝句","c":["新宫改作几何年，像设于今尚俨然。","薜荔绿垂山木槁，长春开尽草芊芊。"]},{"t":"题白龙洞","f":"七言绝句","c":["流水疏梅我有诗，偶来重见雪离披。","五年不蹋常山路，咫尺宁乖一赴期。"]},{"t":"题石潭观音院用王枢密庶愚丘正宗韵二首 其二","f":"七言绝句","c":["所至滔滔不问津，故知此地往来频。","从今更识林间寺，再到不愁无主人。"]},{"t":"题石潭观音院用王枢密庶愚丘正宗韵二首 其一","f":"七言绝句","c":["老衲迎门祇敝裳，问年还举四山黄。","谁云此院通衢著，渠自长閒人自忙。"]},{"t":"题刘正之少陵像二首 其二","f":"七言绝句","c":["我今即有湖南役，准拟扁舟泊耒阳。","敬谢此图非久别，会倾桂酒奠椒浆。"]},{"t":"题刘正之少陵像二首 其一","f":"七言绝句","c":["逢人欲问成都事，见说成都信便回。","欲问草堂亡恙否，恍然图像对人开。"]},{"t":"题刘叔骥所画竹","f":"五言绝句","c":["竹不愧老可，人今无老坡。","聊将一卮酒，相与酹蘋波。"]},{"t":"题刘叔骥梦游赤壁赋后二首 其二","f":"七言绝句","c":["江湖知友亦云多，每叹风流奈若何。","水落故知当石出，镜中宁惜鬓将皤。"]},{"t":"题刘叔骥梦游赤壁赋后二首 其一","f":"七言绝句","c":["三国功名可立谈，赋成赤壁倍崭岩。","想君梦去神游处，慷慨风流真可参。"]},{"t":"题邢园壁","f":"五言绝句","c":["池草似争长，木阴如合围。","不惟催我去，政欲饯春归。"]},{"t":"题君子亭","f":"五言绝句","c":["菊落渊明手，爱人仍及乌。","荷花定好友，周子亦陶徒。"]},{"t":"题杨补之画梅","f":"七言绝句","c":["翠筱横侵鹤膝枝，江南篱落雪残时。","杨郎笔下烟岚集，留作晴窗觅句资。"]},{"t":"题沈弟所作短轴 其一","f":"七言绝句","c":["冥冥细雨熟黄梅，欲起看山懒又回。","咫尺忽能来万里，恍然堕我晓船开。"]},{"t":"题沈弟所作短轴 其二","f":"七言绝句","c":["作诗政欲江山助，老矣东西南北人。","弟却把诗摹作画，东西南北是知津。"]},{"t":"题芭蕉","f":"七言绝句","c":["卷藏政尔待时雨，及此发舒天已秋。","已是萧萧吹我急，主人宁得厌飕飕。"]},{"t":"题钓雪图 其三","f":"五言绝句","c":["画师端为谁，钓者亦安在。","我不识若人，相望大千内。"]},{"t":"题圆通院","f":"七言绝句","c":["吾家旧筑炉峰宅，岂不怀归困转蓬。","奔走微官遍林谷，却寻清磬到圆通。"]},{"t":"题泰州司理廨舍小亭","f":"七言绝句","c":["凿去为亭因得池，面池老柳蔽仍亏。","客来不用勤修供，乞与绳床令赋诗。"]},{"t":"题堂下桃花","f":"七言绝句","c":["桃花颜色晓犹深，薄暮风烟已不禁。","人生抵死朱颜恃，不料青铜霜雪侵。"]},{"t":"题渊明采菊图子璿所作","f":"七言绝句","c":["云出无心还自归，乱峰明处日西微。","白衣不至东篱寂，满把菊花风动衣。"]},{"t":"题船子和尚图","f":"七言绝句","c":["纵有丝纶不暇施，痴鱼吞月自惊疑。","旁观莫作风波想，比著人间未是危。"]},{"t":"题黄溪壁二首 其二","f":"七言绝句","c":["此邦茶品固多有，闻说黄溪独未尝。","何日敲门辱持赠，更须高诵碧云章。"]},{"t":"题黄溪壁二首 其一","f":"七言绝句","c":["新居不见邠山主，及到黄溪又不逢。","锡杖徐飞向何处，槛前山水自为容。"]},{"t":"题曾幼度诗集后二首 其二","f":"七言绝句","c":["客路东西曾数州，诗成宁免暗中投。","我今办取逢人说，倾盖悬知胜白头。"]},{"t":"题曾幼度诗集后二首 其一","f":"七言绝句","c":["江南山水尽宜诗，几欲经营竟不奇。","不料此编能到手，意曾关处辄能知。"]},{"t":"题曾真君炼丹井","f":"七言绝句","c":["樟源岭下炼丹井，建德道间仙女泉。","埋没只今谁汲引，信知名字托人贤。"]},{"t":"题新宫","f":"七言绝句","c":["到处江山非不佳，不归佛屋即仙家。","南山自好不归去，落魄赋诗天一涯。"]},{"t":"题新庵壁间","f":"七言绝句","c":["道人庭宇知何有，几个修篁一树梅。","说似庵门莫深闭，断无俗客此间来。"]},{"t":"憩汭口之秘藏院","f":"七言绝句","c":["老至浑亡旧所经，漫嗟古屋暗丹青。","庭空废扫苍苔长，时听风抛柏子铃。"]},{"t":"篱落间见凌霄偶书","f":"五言绝句","c":["凌霄何自名，缘木与俱生。","底事因蓬附，故为亦蔓荣。"]},{"t":"赠龙王山庵秀上人","f":"七言绝句","c":["道人学易更参禅，一住江头已六年。","劝我小留殊不顾，那知风雪有回船。"]},{"t":"赠许季升五首 其五","f":"七言绝句","c":["学诗自足致寒饥，更欲探求造化机。","我坐一偏犹不免，君今两取是邪非。"]},{"t":"赠许季升五首 其四","f":"七言绝句","c":["惶恐滩头一扁舟，桃花水涨如乘流。","君来叩户喜欲倒，一问此行还遂不。"]},{"t":"赠许季升五首 其三","f":"七言绝句","c":["方朔人传是岁星，又云太白本长庚。","如何未免饥欲死，亦有佯狂万里行。"]},{"t":"赠许季升五首 其二","f":"七言绝句","c":["清江人物推陈谢，不减当年孔与刘。","肯为赋诗仍作序，要明吾子乃儒流。"]},{"t":"赠许季升五首 其一","f":"七言绝句","c":["东都籍甚汝南许，人物尝更月旦评。","后嗣流传齐一变，如今推步有知名。"]},{"t":"赠别耆英二首 其二","f":"七言绝句","c":["忆我移官惶恐滩，肯来徒步不为难。","颇亦念君家四壁，囊中羞涩但频看。"]},{"t":"赠别耆英二首 其一","f":"七言绝句","c":["学诗曾及谢玄晖，传授应同一唯归。","旧宅纵荒书故在，不妨幽僻借僧扉。"]},{"t":"赠吴昴山人二首 其二","f":"七言绝句","c":["君行足迹遍江南，我亦飘零老不堪。","幸自尊中有醇酎，何妨醉倒又空谈。"]},{"t":"赠吴昴山人二首 其一","f":"七言绝句","c":["又是芳菲一番新，寂寥依旧去年贫。","相看不用谈馀事，且道逢迎有故人。"]},{"t":"赠法雷","f":"七言绝句","c":["道人曾与谪仙游，仙去骑鲸师白头。","骑鲸端复向何处，试问援琴招得不。"]},{"t":"赠南首座兼简卢老二首 其二","f":"七言绝句","c":["主人禅伯乃诗伯，招得渠来共此山。","挂搭问侬能胆大，诗关直上有禅关。"]},{"t":"赠南首座兼简卢老二首 其一","f":"七言绝句","c":["旋糊纸屋过冬寒，客至成开去即关。","我亦借寮成挂搭，未妨朝暮往仍还。"]},{"t":"赠笔工","f":"五言绝句","c":["食肉既无相，良工徒苦心。","吁嗟君类我，何处觅知音。"]},{"t":"骤雨记所见","f":"七言绝句","c":["翠筱萧骚入屋寒，欻惊平地起风湍。","驯除饥雀低飞去，弱羽毰毸似畏弹。"]},{"t":"魏昭父惠新刻李西台诸公帖二首 其二","f":"七言绝句","c":["翰墨要知真有种，怪来下笔每多姿。","不如家学相传授，玉轴锦囊皆得师。"]},{"t":"魏昭父惠新刻李西台诸公帖二首 其一","f":"七言绝句","c":["墨妙初闻探锦囊，刻成愈觉烂生光。","登登打就分来处，雨合新篁夏日凉。"]},{"t":"鬻菜者","f":"七言绝句","c":["早禾未熟晚尤迟，卖菜归来始得炊。","谷者本从田户出，未滋反取市人嗤。"]},{"t":"九日","f":"七言律诗","c":["涧落峰寒似往时，重阳面目许谁知。","摇摇枫叶未全赤，草草菊花成后期。","酒量稍增愁渴肺，诗材顿减费衰髭。","一年节物财如此，太息空形老大悲。"]},{"t":"九日","f":"五言律诗","c":["今年重九日，舟楫次兰溪。","怀古心虽壮，登高思却迷。","山空分向背，木落尽高低。","多少羁栖恨，寒猿断续啼。"]},{"t":"九日王越卿司法置酒要客始约登武安之塔为游人所先已过圆通晚更集于彦博之居越卿醉后作画其先大夫公亦能画云作诗二首 其二","f":"七言律诗","c":["王家父子竹林期，谈笑初无世俗姿。","戏搦败毫成冻羽，醉回老力出枯枝。","解吟秀句寰区满，不拟常称老画师。","大令右军疑只尔，外人笑怪若能知。"]},{"t":"九日王越卿司法置酒要客始约登武安之塔为游人所先已过圆通晚更集于彦博之居越卿醉后作画其先大夫公亦能画云作诗二首 其一","f":"七言律诗","c":["登高有约乃相违，故遣村船逆上溪。","寺与松篁元不隔，路经蓬藋却成迷。","数君放逸仍怀古，老我悲凉况哭妻。","郑重莫逃鸡黍社，又随新月共扶藜。"]},{"t":"九日有感","f":"五言律诗","c":["寥落渊明后，凄凉九日期。","寻花漫青蕊，对酒祇空卮。","林密栖鸦早，江寒泊雁迟。","楼高无那倚，弦绝有谁知。"]},{"t":"九日次韵斯远去年是日同成父登半山亭见怀之什寄斯远兼示成父","f":"七言律诗","c":["去岁修途度此晨，今年抱疾更漳滨。","官壶可醉难多致，城菊未开空屡巡。","忆我有诗朝在手，思君何处暮伤神。","遥知置酒登高者，回首西南只两人。"]},{"t":"九日怀周仲材","f":"五言律诗","c":["吹帽今朝是，登高旧俗同。","穷乡怕逢节，病骨怯临风。","此日千忧里，他时一梦中。","白衣殊不至，空绕菊篱东。"]},{"t":"九日莫令置酒县斋余以病不饮作诗呈坐客","f":"七言律诗","c":["孰使庭花未肯黄，政应知我鬓新霜。","茫茫永夜无时旦，索索穷愁曾断肠。","坐久支吾催煮药，饮豪络驿看传觞。","废游不但因公事，风雨连朝故觉妨。"]},{"t":"九日寄和父弟","f":"七言律诗","c":["走马忆登江上台，闻知兴废使人哀。","遥怜冷澹黄花节，远对飘零白雁来。","念尔不堪怀为恶，思余应是首频回。","诗成寄与憨申诵，句累难教心孔开。"]},{"t":"九日晦日雨忽杂霰","f":"五言律诗","c":["九月霰维集，南方见未曾。","马寒添瑟缩，我瘦益崚嶒。","穷相有如此，昔人谁似能。","树深鸦屡落，滩远雁相应。"]},{"t":"九日欲行宜之兄见留赋诗一首","f":"五言律诗","c":["节里留羁客，愁边识此心。","台高午时暖，斋静晚来阴。","白发有衰盛，黄花无古今。","君其赐茱会，我乃见山吟。"]},{"t":"九日游马祖岩","f":"七言律诗","c":["环城往往尽高峰，更欲登高底可同。","马祖自今成故实，龙山翻觉堕虚空。","当公迭唱青霄上，政我孤吟返照中。","要是不孤吹帽节，孰云真隔马牛风。"]},{"t":"九月一日晨起风物凄然不胜怀远之思作五首寄和父憨申并烦转致湖池二州也 其三","f":"五言律诗","c":["秋气故悲哉，连阴况不开。","黄花九日近，白发数茎催。","山际擎新塔，江边峙旧台。","谩看云日暮，安得雁同来。"]},{"t":"九月一日晨起风物凄然不胜怀远之思作五首寄和父憨申并烦转致湖池二州也 其二","f":"五言律诗","c":["节佳重九近，风急授衣初。","茱菊年龄迈，枫柽日夜疏。","欲题怀远句，频展寄来书。","憨子能思我，申儿更忆渠。"]},{"t":"九月一日晨起风物凄然不胜怀远之思作五首寄和父憨申并烦转致湖池二州也 其五","f":"五言律诗","c":["秋浦新为别，秋风阙寄书。","虽然声问阔，未觉梦魂疏。","杜牧登临后，宛陵吟咏馀。","三冬如有暇，五字不妨渠。"]},{"t":"九月一日晨起风物凄然不胜怀远之思作五首寄和父憨申并烦转致湖池二州也 其一","f":"五言律诗","c":["作别已半百，得书无二三。","飘零各天外，摇落共江南。","此去仍加远，相思转不堪。","怀哉对床约，老矣折腰惭。"]},{"t":"九月一日晨起风物凄然不胜怀远之思作五首寄和父憨申并烦转致湖池二州也 其四","f":"五言律诗","c":["姨母比苦胫，涉秋今若何。","音书君定密，离苦我何多。","凫舄思文瑞，灯窗想骥和。","何能俱款集，未厌数经过。"]},{"t":"九月二十七日题桂溪铺","f":"五言律诗","c":["昨日方摇扇，今朝可拥裘。","顿能惊北客，方觉是南州。","岁傥不逢闰，时今宁复秋。","无庸叹疏漏，聊得避飕飕。"]},{"t":"九月二日发舟快阁下","f":"五言律诗","c":["开船风打头，举棹水分流。","到处皆成客，今年未识秋。","意哀吟蟋蟀，声苦乱飕飗。","拊枕仍推枕，谁知梦觉优。"]},{"t":"九月十一夜雨中读吴梦与诗书以示之","f":"七言律诗","c":["疾风吹雨过江干，老屋阙床无处乾。","切切冷蛩深撼壁，累累饥鼠下窥箪。","枕衾屡抚眠难著，灯火重呼诗细看。","谩说为官犹我似，念君怀抱若何宽。"]},{"t":"九月十三日雪","f":"五言律诗","c":["稍稍云初集，泠泠风未停。","粗能成点缀，还是学飘零。","径路高低滑，炊烟远近青。","篮舆所经历，诗语费平亭。"]},{"t":"九月十六日文兴折赠绿萼梅数枝花多而甚香非寻常梅花比也","f":"七言律诗","c":["旧闻良月似春时，真有梅花如许枝。","绿萼深宜翠羽宿，静香独许蜜蜂知。","木犀莫道开能再，庭菊无嗟晚乃移。","不是南方地偏暖，宠光潜已落天涯。"]},{"t":"九月五日具草酌同彦博审知成父集于普宁山半之亭作诗二首 其二","f":"五言律诗","c":["平生羞狗监，何啻失羊斟。","与子风期尚，相要林壑深。","分甘驹在谷，宁事鹤鸣阴。","此日胡为乐，诗成改又吟。"]},{"t":"九月五日具草酌同彦博审知成父集于普宁山半之亭作诗二首 其一","f":"五言律诗","c":["探支重九日，试手菊花斟。","论置人繁寡，觞行自浅深。","风能度林杪，月亦吐山阴。","四听虫仍起，中还著我吟。"]},{"t":"九月廿一日雪书呈进之","f":"七言律诗","c":["一夜悲风晓辄收，布衾如铁强扶头。","乍惊皎皎明窗纸，稍见疏疏集瓦沟。","失怪竞闻村巷犬，乱行难觅远汀鸥。","欣然欲作临流看，却恨凛乎难久留。"]},{"t":"二十一日晚呈全真沅陵师契","f":"五言律诗","c":["酒味虽云薄，谈端却甚长。","过从未能数，咫尺每相望。","几念乘羸出，还嫌触热妨。","檐昏书掩卷，月晚坐移床。"]},{"t":"二十一日湖中","f":"五言律诗","c":["岁晚仍湖路，客中还病身。","似闻今大熟，那故独长贫。","方朔一囊栗，季鹰千里莼。","扁舟固高蹈，金马亦沉沦。"]},{"t":"二十八日同临湘尉曹吕益卿登岳阳楼 其二","f":"五言律诗","c":["草没重湖路，帆孤一叶舟。","飘风来复断，冻雨落还收。","游目穷天末，题诗欠笔头。","登临有如此，好在岳阳楼。"]},{"t":"二十八日同临湘尉曹吕益卿登岳阳楼 其一","f":"五言律诗","c":["地已兼旬住，楼孤百尺登。","谁与同我适，政尔待君曾。","韩杜愁来读，西南乐得朋。","仲春新雨霁，山远水波兴。"]},{"t":"二十八日雪二十九日未已赋诗凡五首 其五","f":"五言律诗","c":["夜久寂无听，晓来微有声。","鸡鸣疑远墅，鼓动忽孤城。","异县留妻子，殊方老弟兄。","怀哉一斗粟，于汝岂无情。"]},{"t":"二十八日雪二十九日未已赋诗凡五首 其四","f":"五言律诗","c":["户户薪充纩，家家炉作床。","悬知火明暗，是系体炎凉。","为俗陋至此，斯民真可伤。","诏条先劝课，王政本耕桑。"]}]};